# Attempt to find the IfcSpace by GUID or GlobalId and extract an area value from quantities or property sets.
space = ifc.by_guid('2UsXAbj6n0fwEWqdkVuHyo')
if not space:
    # try searching all IfcSpace instances by GlobalId attribute
    space = None
    for s in ifc.by_type('IfcSpace'):
        if getattr(s, 'GlobalId', None) == '2UsXAbj6n0fwEWqdkVuHyo':
            space = s
            break

area = None
raw = ''

if not space:
    raw = 'Space with the given id not found.'
    result = {'area': None, 'raw_model_response': raw}
    commit()
else:
    raw += f'Found entity: {space} (GlobalId={getattr(space, "GlobalId", None)})\n'

    # Check common direct attributes
    for attr in ('Area','NetFloorArea','GrossFloorArea'):
        if hasattr(space, attr) and getattr(space, attr) is not None:
            try:
                area = float(getattr(space, attr))
                raw += f'Found attribute {attr} = {area}\n'
                break
            except Exception as e:
                raw += f'Could not parse attribute {attr}: {e}\n'

    # Check IfcElementQuantity linked through IsDefinedBy
    if area is None and hasattr(space, 'IsDefinedBy'):
        for rel in space.IsDefinedBy:
            propdef = getattr(rel, 'RelatingPropertyDefinition', None)
            if not propdef:
                continue
            raw += f'Checking property definition: {propdef} (type={propdef.is_a()})\n'
            if propdef.is_a('IfcElementQuantity'):
                for q in getattr(propdef, 'Quantities', []):
                    if q.is_a('IfcQuantityArea'):
                        try:
                            area = float(getattr(q, 'AreaValue'))
                            raw += f'IfcElementQuantity {getattr(propdef, "Name", None)} -> {getattr(q, "Name", None)} = {area}\n'
                            break
                        except Exception as e:
                            raw += f'Failed reading IfcQuantityArea: {e}\n'
                if area is not None:
                    break
            elif propdef.is_a('IfcPropertySet'):
                for p in getattr(propdef, 'HasProperties', []):
                    if p.is_a('IfcPropertySingleValue'):
                        name = getattr(p, 'Name', '') or ''
                        if 'area' in name.lower():
                            val = getattr(p, 'NominalValue', None)
                            # If NominalValue is a wrapped value
                            try:
                                numeric = None
                                if val is None:
                                    continue
                                if hasattr(val, 'wrappedValue'):
                                    numeric = float(val.wrappedValue)
                                else:
                                    numeric = float(val)
                                area = numeric
                                raw += f'PropertySet {getattr(propdef, "Name", None)} -> {name} = {area}\n'
                                break
                            except Exception as e:
                                raw += f'Failed reading property single value {name}: {e}\n'
                if area is not None:
                    break

    # As a last attempt, search any IfcElementQuantity for matching name values
    if area is None:
        for eq in ifc.by_type('IfcElementQuantity'):
            for q in getattr(eq, 'Quantities', []):
                if q.is_a('IfcQuantityArea'):
                    try:
                        name = getattr(q, 'Name', '') or ''
                        if 'area' in name.lower():
                            area = float(getattr(q, 'AreaValue'))
                            raw += f'Fallback found quantity {name} = {area}\n'
                            break
                    except Exception as e:
                        raw += f'Fallback quantity read error: {e}\n'
            if area is not None:
                break

    if area is None:
        raw += 'No area value found on space via attributes, quantities, or property sets.'

    result = {'area': area, 'raw_model_response': raw}
    commit()

# Inspect the IfcSpace and related IfcRelSpaceBoundary and any geometry-like attributes to try to compute area
space = ifc.by_guid('2UsXAbj6n0fwEWqdkVuHyo')
raw = ''
if not space:
    raw = 'Space not found.'
    result = {'area': None, 'raw_model_response': raw}
    commit()
else:
    raw += f'Space: {space}\n'
    # list attributes of space
    raw += 'Space attributes:\n'
    for a in space.attribs():
        raw += f'  {a} = {getattr(space, a)}\n'

    # Search IfcRelSpaceBoundary
    rels = []
    for r in ifc.by_type('IfcRelSpaceBoundary'):
        if getattr(r, 'RelatingSpace', None) == space or getattr(r, 'RelatedSpace', None) == space:
            rels.append(r)

    raw += f'Found {len(rels)} IfcRelSpaceBoundary referencing space.\n'
    for r in rels:
        raw += f'Rel: {r}\n'
        for a in r.attribs():
            raw += f'  {a} = {getattr(r, a)}\n'
        # inspect ConnectionGeometry if present
        cg = getattr(r, 'ConnectionGeometry', None)
        raw += f'  ConnectionGeometry: {cg}\n'
        if cg:
            raw += f'    type: {cg.is_a()}\n'
            # show attributes of the connection geometry
            for a in cg.attribs():
                raw += f'      {a} = {getattr(cg, a)}\n'
            # try to find polygonal boundary or positions
            if hasattr(cg, 'PolygonalBoundary'):
                pb = getattr(cg, 'PolygonalBoundary')
                raw += f'      PolygonalBoundary: {pb}\n'
                if hasattr(pb, 'Polygon'):
                    raw += f'        Polygon: {getattr(pb, "Polygon")}\n'

    # Also try IfcRelSpaceBoundary1stLevel (older schema names) - list all relating to this space
    raw += 'Searching general inverses for any boundary-like relations...\n'
    invs = []
    for rel in ifc.by_type('IfcRelAssociates'):
        pass
    # Dump all inverses of the space
    inv = ifc.get_inverse(space)
    raw += f'Inverse relations count: {len(inv)}\n'
    for k,v in inv.items():
        raw += f'Inverse type: {k} -> count {len(v)}\n'
        for item in v:
            raw += f'  {item} (is_a={item.is_a()})\n'
            for a in item.attribs():
                raw += f'    {a} = {getattr(item, a)}\n'

    result = {'area': None, 'raw_model_response': raw}
    commit()

# Robust search for area for an IfcSpace by GlobalId
space = ifc.by_guid('2UsXAbj6n0fwEWqdkVuHyo')
raw = ''
area = None
if not space:
    raw = 'Space not found.'
    result = {'area': None, 'raw_model_response': raw}
    commit()
else:
    raw += f'Found space: {space} (GlobalId={getattr(space, "GlobalId", None)})\n'

    # 1) Search IfcRelDefinesByProperties where space is in RelatedObjects
    for rel in ifc.by_type('IfcRelDefinesByProperties'):
        try:
            related = list(rel.RelatedObjects)
        except Exception:
            related = []
        if space in related:
            propdef = getattr(rel, 'RelatingPropertyDefinition', None)
            raw += f'Found RelDefinesByProperties: {rel} -> propdef {propdef} (type={propdef.is_a() if propdef else None})\n'
            if not propdef:
                continue
            if propdef.is_a('IfcElementQuantity'):
                for q in getattr(propdef, 'Quantities', []):
                    if q.is_a('IfcQuantityArea'):
                        # try multiple attribute names
                        for attr in ('AreaValue','Area','AreaValueComponent'):
                            val = getattr(q, attr, None)
                            if val is None:
                                continue
                            try:
                                # handle value wrappers
                                num = None
                                if hasattr(val, 'wrappedValue'):
                                    num = float(val.wrappedValue)
                                else:
                                    num = float(val)
                                area = num
                                raw += f'IfcElementQuantity {getattr(propdef,"Name",None)} -> {getattr(q, "Name", None)} attribute {attr} = {area}\n'
                                break
                            except Exception as e:
                                raw += f'Failed parsing quantity value {attr}: {e}\n'
                        if area is not None:
                            break
            elif propdef.is_a('IfcPropertySet'):
                for p in getattr(propdef, 'HasProperties', []):
                    try:
                        if not p.is_a('IfcPropertySingleValue'):
                            continue
                    except Exception:
                        continue
                    name = getattr(p, 'Name', '') or ''
                    if 'area' in name.lower() or 'floor' in name.lower():
                        val = getattr(p, 'NominalValue', None)
                        try:
                            if val is None:
                                continue
                            num = None
                            if hasattr(val, 'wrappedValue'):
                                num = float(val.wrappedValue)
                            else:
                                num = float(val)
                            area = num
                            raw += f'PropertySet {getattr(propdef, "Name", None)} -> {name} = {area}\n'
                            break
                        except Exception as e:
                            raw += f'Failed reading property single value {name}: {e}\n'
                if area is not None:
                    break
        if area is not None:
            break

    # 2) As a fallback, search all IfcRelDefinesByProperties that reference quantities where the RelatedObjects include this space
    if area is None:
        for rel in ifc.by_type('IfcRelDefinesByProperties'):
            try:
                related = list(rel.RelatedObjects)
            except Exception:
                related = []
            if space not in related:
                continue
            propdef = getattr(rel, 'RelatingPropertyDefinition', None)
            if propdef and propdef.is_a('IfcElementQuantity'):
                for q in getattr(propdef, 'Quantities', []):
                    if q.is_a('IfcQuantityArea'):
                        val = getattr(q, 'AreaValue', None)
                        try:
                            if val is None:
                                continue
                            if hasattr(val, 'wrappedValue'):
                                area = float(val.wrappedValue)
                            else:
                                area = float(val)
                            raw += f'Fallback IfcElementQuantity {getattr(propdef, "Name", None)} -> {getattr(q, "Name", None)} = {area}\n'
                            break
                        except Exception as e:
                            raw += f'Failed parsing fallback quantity: {e}\n'
                if area is not None:
                    break

    # 3) Inspect inverse relations and other psets that were found earlier in a more direct way
    if area is None:
        inv = ifc.get_inverse(space)
        raw += f'Inverse relations keys: {list(inv.keys())}\n'
        # check IsDefinedBy inverses if present
        if 'IsDefinedBy' in inv:
            for rel in inv['IsDefinedBy']:
                propdef = getattr(rel, 'RelatingPropertyDefinition', None)
                raw += f'IsDefinedBy -> {rel} propdef: {propdef} type={propdef.is_a() if propdef else None}\n'
                if propdef and propdef.is_a('IfcElementQuantity'):
                    for q in getattr(propdef, 'Quantities', []):
                        if q.is_a('IfcQuantityArea'):
                            val = getattr(q, 'AreaValue', None)
                            try:
                                if val is None:
                                    continue
                                if hasattr(val, 'wrappedValue'):
                                    area = float(val.wrappedValue)
                                else:
                                    area = float(val)
                                raw += f'IsDefinedBy quantity {getattr(q,"Name",None)} = {area}\n'
                                break
                            except Exception as e:
                                raw += f'Error reading IsDefinedBy quantity: {e}\n'
                    if area is not None:
                        break
                if propdef and propdef.is_a('IfcPropertySet'):
                    for p in getattr(propdef, 'HasProperties', []):
                        if not p.is_a('IfcPropertySingleValue'):
                            continue
                        name = getattr(p, 'Name', '') or ''
                        if 'area' in name.lower() or 'floor' in name.lower():
                            val = getattr(p, 'NominalValue', None)
                            try:
                                if val is None:
                                    continue
                                if hasattr(val, 'wrappedValue'):
                                    area = float(val.wrappedValue)
                                else:
                                    area = float(val)
                                raw += f'IsDefinedBy PSet {getattr(propdef, "Name", None)} -> {name} = {area}\n'
                                break
                            except Exception as e:
                                raw += f'Error reading IsDefinedBy PSet value: {e}\n'
                    if area is not None:
                        break

    # 4) If still not found, attempt minimal geometry-based extraction from Representation (limited handling)
    if area is None and getattr(space, 'Representation', None):
        try:
            reps = getattr(space.Representation, 'Representations', [])
            for rep in reps:
                raw += f'Representation: {getattr(rep, "RepresentationIdentifier", None)} / {getattr(rep, "RepresentationType", None)}\n'
                for item in getattr(rep, 'Items', []):
                    raw += f'  Item: {item} (type={item.is_a()})\n'
                    # Handle IfcExtrudedAreaSolid
                    if item.is_a('IfcExtrudedAreaSolid'):
                        sa = getattr(item, 'SweptArea', None)
                        if sa:
                            # If profile is IfcArbitraryClosedProfileDef with OuterCurve IfcPolyline
                            if sa.is_a('IfcArbitraryClosedProfileDef'):
                                outer = getattr(sa, 'OuterCurve', None)
                                if outer and outer.is_a('IfcPolyline'):
                                    pts = [ (p.X, p.Y) for p in getattr(outer, 'Points', []) if hasattr(p, 'X') and hasattr(p, 'Y') ]
                                    if len(pts) >= 3:
                                        # compute polygon area (planar) using shoelace
                                        a = 0.0
                                        for i in range(len(pts)):
                                            x1,y1 = pts[i]
                                            x2,y2 = pts[(i+1)%len(pts)]
                                            a += x1*y2 - x2*y1
                                        area = abs(a)/2.0
                                        raw += f'Computed area from IfcExtrudedAreaSolid profile polyline = {area}\n'
                                        break
                    # Handle IfcFaceBasedSurfaceModel -> compute projection of first face if planar
                    if item.is_a('IfcFaceBasedSurfaceModel'):
                        faces = getattr(item, 'FbFaces', [])
                        for face in faces:
                            # face is IfcConnectedFaceSet, has CfsFaces
                            for cfs in getattr(face, 'CfsFaces', []):
                                # each cfs is IfcFace, with Bounds -> IfcFaceBound -> Bound -> maybe IfcPolyLoop
                                for b in getattr(cfs, 'Bounds', []):
                                    bound = getattr(b, 'Bound', None)
                                    if bound and bound.is_a('IfcPolyLoop'):
                                        verts = [ (v.X, v.Y) for v in getattr(bound, 'Polygon', []) if hasattr(v,'X') and hasattr(v,'Y') ]
                                        if len(verts) >= 3:
                                            a = 0.0
                                            for i in range(len(verts)):
                                                x1,y1 = verts[i]
                                                x2,y2 = verts[(i+1)%len(verts)]
                                                a += x1*y2 - x2*y1
                                            area = abs(a)/2.0
                                            raw += f'Computed area from IfcFaceBasedSurfaceModel polyloop = {area}\n'
                                            break
                                if area is not None:
                                    break
                            if area is not None:
                                break
                        if area is not None:
                            break
                if area is not None:
                    break
        except Exception as e:
            raw += f'Error while parsing Representation: {e}\n'

    if area is None:
        raw += 'No area found or computed for this space.\n'
    result = {'area': area, 'raw_model_response': raw}
    commit()

# Final attempt to extract or compute area for IfcSpace with given GlobalId
space = ifc.by_guid('2UsXAbj6n0fwEWqdkVuHyo')
raw = ''
area = None

if not space:
    raw = 'Space not found.'
    result = {'area': None, 'raw_model_response': raw}
    commit()
else:
    raw += f'Found space: {space} (GlobalId={getattr(space, "GlobalId", None)})\n'

    # 1) Check direct attributes again
    for attr in ('Area','NetFloorArea','GrossFloorArea'):
        val = getattr(space, attr, None)
        if val is not None:
            try:
                area = float(val)
                raw += f'Found direct attribute {attr} = {area}\n'
            except Exception as e:
                raw += f'Could not parse direct attribute {attr}: {e}\n'
        if area is not None:
            break

    # 2) Search RelDefinesByProperties and IsDefinedBy for quantities and psets
    if area is None:
        try:
            inv = ifc.get_inverse(space)
        except Exception as e:
            inv = {}
            raw += f'get_inverse failed: {e}\n'
        # inv might be dict-like or set; handle both
        items_to_check = []
        if isinstance(inv, dict):
            for key, vals in inv.items():
                try:
                    for v in vals:
                        items_to_check.append(v)
                except Exception:
                    pass
        elif isinstance(inv, (list, tuple, set)):
            for v in inv:
                items_to_check.append(v)

        # Also include all IfcRelDefinesByProperties referencing this space explicitly
        for rel in ifc.by_type('IfcRelDefinesByProperties'):
            try:
                related = list(rel.RelatedObjects)
            except Exception:
                related = []
            if space in related:
                items_to_check.append(rel)

        seen = set()
        for rel in items_to_check:
            if rel is None:
                continue
            if id(rel) in seen:
                continue
            seen.add(id(rel))
            propdef = getattr(rel, 'RelatingPropertyDefinition', None)
            if not propdef:
                # Some inverses might be IfcRelDefinesByType or others with different attrnames
                propdef = getattr(rel, 'RelatingPropertyDefinition', None)
            raw += f'Checking property def: {propdef} (type={propdef.is_a() if propdef else None})\n'
            try:
                if propdef and propdef.is_a('IfcElementQuantity'):
                    for q in getattr(propdef, 'Quantities', []):
                        if q.is_a('IfcQuantityArea'):
                            # try potential names
                            for keyname in ('AreaValue','Area','AreaValueComponent'):
                                val = getattr(q, keyname, None)
                                if val is None:
                                    continue
                                try:
                                    if hasattr(val, 'wrappedValue'):
                                        area = float(val.wrappedValue)
                                    else:
                                        area = float(val)
                                    raw += f'Found IfcQuantityArea {getattr(q, "Name", None)} attr {keyname} = {area}\n'
                                    break
                                except Exception as e:
                                    raw += f'Failed parsing quantity {keyname}: {e}\n'
                        if area is not None:
                            break
                elif propdef and propdef.is_a('IfcPropertySet'):
                    for p in getattr(propdef, 'HasProperties', []):
                        try:
                            if not p.is_a('IfcPropertySingleValue'):
                                continue
                        except Exception:
                            continue
                        name = getattr(p, 'Name', '') or ''
                        if 'area' in name.lower() or 'floor' in name.lower():
                            val = getattr(p, 'NominalValue', None)
                            try:
                                if val is None:
                                    continue
                                if hasattr(val, 'wrappedValue'):
                                    area = float(val.wrappedValue)
                                else:
                                    area = float(val)
                                raw += f'Found PSet property {name} = {area}\n'
                                break
                            except Exception as e:
                                raw += f'Failed reading PSet property {name}: {e}\n'
                    if area is not None:
                        break
            except Exception as e:
                raw += f'Error while checking propdef: {e}\n'
            if area is not None:
                break

    # 3) Try computing from Representation geometry (handle common cases)
    if area is None:
        rep = getattr(space, 'Representation', None)
        if rep:
            try:
                reps = getattr(rep, 'Representations', [])
                for repi in reps:
                    raw += f'Representation {getattr(repi, "RepresentationIdentifier", None)} / {getattr(repi, "RepresentationType", None)}\n'
                    for item in getattr(repi, 'Items', []) or []:
                        try:
                            itype = item.is_a()
                        except Exception:
                            itype = None
                        raw += f'  Item type: {itype}\n'
                        # IfcExtrudedAreaSolid
                        if itype == 'IfcExtrudedAreaSolid':
                            sa = getattr(item, 'SweptArea', None)
                            if sa:
                                # If arbitrary closed profile with polyline
                                if sa.is_a('IfcArbitraryClosedProfileDef'):
                                    outer = getattr(sa, 'OuterCurve', None)
                                    if outer and outer.is_a('IfcPolyline'):
                                        pts = []
                                        for p in getattr(outer, 'Points', []) or []:
                                            x = getattr(p, 'X', None)
                                            y = getattr(p, 'Y', None)
                                            if x is None or y is None:
                                                # try 3d
                                                x = getattr(p, 'Coordinates', None)
                                            try:
                                                pts.append((float(x), float(y)))
                                            except Exception:
                                                pass
                                        if len(pts) >= 3:
                                            a = 0.0
                                            for i in range(len(pts)):
                                                x1,y1 = pts[i]
                                                x2,y2 = pts[(i+1)%len(pts)]
                                                a += x1*y2 - x2*y1
                                            area = abs(a)/2.0
                                            raw += f'Computed area from IfcExtrudedAreaSolid->ArbitraryClosedProfileDef polyline = {area}\n'
                                            break
                        # IfcMappedItem or IfcMappedRepresentation could reference profile
                        if itype == 'IfcMappedItem':
                            mapping = getattr(item, 'MappingSource', None)
                            if mapping:
                                try:
                                    map_rep = getattr(mapping, 'MappedRepresentation', None)
                                    if map_rep:
                                        for it in getattr(map_rep, 'Items', []) or []:
                                            if it.is_a('IfcArbitraryClosedProfileDef'):
                                                outer = getattr(it, 'OuterCurve', None)
                                                if outer and outer.is_a('IfcPolyline'):
                                                    pts = []
                                                    for p in getattr(outer, 'Points', []) or []:
                                                        x = getattr(p, 'X', None); y = getattr(p, 'Y', None)
                                                        try:
                                                            pts.append((float(x), float(y)))
                                                        except Exception:
                                                            pass
                                                    if len(pts) >= 3:
                                                        a = 0.0
                                                        for i in range(len(pts)):
                                                            x1,y1 = pts[i]
                                                            x2,y2 = pts[(i+1)%len(pts)]
                                                            a += x1*y2 - x2*y1
                                                        area = abs(a)/2.0
                                                        raw += f'Computed area from IfcMappedItem->profile polyline = {area}\n'
                                                        break
                                except Exception as e:
                                    raw += f'Error parsing IfcMappedItem mapping: {e}\n'
                        # IfcFaceBasedSurfaceModel
                        if itype == 'IfcFaceBasedSurfaceModel':
                            for face in getattr(item, 'FbFaces', []) or []:
                                for cfs in getattr(face, 'CfsFaces', []) or []:
                                    for b in getattr(cfs, 'Bounds', []) or []:
                                        bound = getattr(b, 'Bound', None)
                                        if bound and bound.is_a('IfcPolyLoop'):
                                            verts = []
                                            for v in getattr(bound, 'Polygon', []) or []:
                                                x = getattr(v, 'X', None); y = getattr(v, 'Y', None)
                                                try:
                                                    verts.append((float(x), float(y)))
                                                except Exception:
                                                    pass
                                            if len(verts) >= 3:
                                                a = 0.0
                                                for i in range(len(verts)):
                                                    x1,y1 = verts[i]
                                                    x2,y2 = verts[(i+1)%len(verts)]
                                                    a += x1*y2 - x2*y1
                                                area = abs(a)/2.0
                                                raw += f'Computed area from IfcFaceBasedSurfaceModel polyloop = {area}\n'
                                                break
                                    if area is not None:
                                        break
                                if area is not None:
                                    break
                            if area is not None:
                                break
                    if area is not None:
                        break
            except Exception as e:
                raw += f'Error while parsing Representation: {e}\n'

    if area is None:
        raw += 'No area value found or computed for this space.\n'

    result = {'area': area, 'raw_model_response': raw}
    commit()

