else:
    def find_depth(obj, visited=None):
        if visited is None:
            visited = set()
        if obj is None:
            return None
        if id(obj) in visited:
            return None
        visited.add(id(obj))
        try:
            if obj.is_a("IfcExtrudedAreaSolid"):
                return float(obj.Depth)
        except Exception:
            pass
        # traverse attributes
        for attr in dir(obj):
            if attr.startswith("__"):
                continue
            try:
                val = getattr(obj, attr)
            except Exception:
                continue
            if val is None:
                continue
            if hasattr(val, "is_a"):
                d = find_depth(val, visited)
                if d is not None:
                    return d
            if isinstance(val, (list, tuple)):
                for item in val:
                    if hasattr(item, "is_a"):
                        d = find_depth(item, visited)
                        if d is not None:
                            return d
        return None

    length = None
    # Common pattern: look for IfcExtrudedAreaSolid in representations
    try:
        rep = getattr(ent, "Representation", None)
        if rep:
            reps = getattr(rep, "Representations", [])
            for r in reps:
                items = getattr(r, "Items", [])
                for it in items:
                    if it is None:
                        continue
                    if hasattr(it, "is_a") and it.is_a("IfcExtrudedAreaSolid"):
                        try:
                            length = float(it.Depth)
                            break
                        except Exception:
                            continue
                    # search nested
                    length = find_depth(it)
                    if length is not None:
                        break
                if length is not None:
                    break
    except Exception:
        length = None

    # If still None, attempt to find IfcGeometricRepresentationItem children within representation items
    if length is None:
        # deep search from the entity
        length = find_depth(ent)

    # prepare raw model response (type and repr)
    try:
        raw = f"{ent.id()} | {ent.is_a()} | GlobalId={getattr(ent, 'GlobalId', None)}"
    except Exception:
        raw = str(ent)

    result = {"length": length, "raw_model_response": raw}

