# Helper to extract numeric value from IfcValue-like objects
def numeric_value(val):
    if val is None:
        return None
    # If it's already a python float/int
    try:
        return float(val)
    except Exception:
        pass
    # If it has wrappedValue (common in ifcopenshell)
    if hasattr(val, 'wrappedValue'):
        try:
            return float(val.wrappedValue)
        except Exception:
            return None
    # Some property containers may store .Value or .NominalValue
    if hasattr(val, 'Value'):
        try:
            return float(val.Value)
        except Exception:
            pass
    if hasattr(val, 'NominalValue'):
        try:
            return float(val.NominalValue)
        except Exception:
            # try wrapped
            nv = getattr(val, 'NominalValue')
            if hasattr(nv, 'wrappedValue'):
                try:
                    return float(nv.wrappedValue)
                except Exception:
                    return None
    return None

