        # If it's an element quantity container
        if rpd.is_a('IfcElementQuantity'):
            for q in getattr(rpd, 'Quantities', []) or []:
                # Direct volume quantity
                if q.is_a('IfcQuantityVolume'):
                    val = numeric_value(getattr(q, 'VolumeValue', None))
                    if val is not None:
                        volumes.append(val)
                else:
                    # Other quantity types: try to find numeric attributes that look like volume
                    name = (getattr(q, 'Name', '') or '').lower()
                    if 'vol' in name:
