# helpers
def get_coords_from_cartesian_point(pt):
    # pt.Coordinates is a list
    coords = []
    try:
        coords = [float(c) for c in pt.Coordinates]
    except Exception:
        # some implementations use .Coordinates[0].wrappedValue etc
        try:
            coords = [float(c.wrappedValue) for c in pt.Coordinates]
        except Exception:
            coords = None
    return coords

def get_coords_from_point_list(pl):
    # IfcCartesianPointList3D has attribute Coordinates: a list of lists
