# polygon area for 3D points by projection
def polygon_area_3d(poly):
    if not poly or len(poly) < 3:
        return 0.0
    # compute normal via Newell's method
    nx = ny = nz = 0.0
    for i in range(len(poly)):
        x1,y1,z1 = poly[i]
        x2,y2,z2 = poly[(i+1)%len(poly)]
        nx += (y1 - y2)*(z1 + z2)
        ny += (z1 - z2)*(x1 + x2)
        nz += (x1 - x2)*(y1 + y2)
    normal = [nx, ny, nz]
    # choose projection axis as largest component
    ax = max(range(3), key=lambda i: abs(normal[i]))
    # project to 2D plane
    area2 = 0.0
    if ax == 0: # drop x, use y,z
        for i in range(len(poly)):
            y1,z1 = poly[i][1], poly[i][2]
            y2,z2 = poly[(i+1)%len(poly)][1], poly[(i+1)%len(poly)][2]
            area2 += y1*z2 - y2*z1
    elif ax == 1: # drop y, use x,z
        for i in range(len(poly)):
            x1,z1 = poly[i][0], poly[i][2]
            x2,z2 = poly[(i+1)%len(poly)][0], poly[(i+1)%len(poly)][2]
            area2 += x1*z2 - x2*z1
    else: # drop z, use x,y
        for i in range(len(poly)):
            x1,y1 = poly[i][0], poly[i][1]
            x2,y2 = poly[(i+1)%len(poly)][0], poly[(i+1)%len(poly)][1]
            area2 += x1*y2 - x2*y1
    area = abs(area2) / 2.0
    # adjust by normal component magnitude ratio
    # The projected area equals area * |normal_component| / |normal| ; to be safe, return area / (abs(normal[ax]) / ( (normal[0]**2+normal[1]**2+normal[2]**2)**0.5 ))
    # But computing that is unnecessary for consistent polygons; we'll compute 3D area via triangulation instead
    # Triangulate around vertex 0
    tri_area = 0.0
    v0 = poly[0]
    for i in range(1, len(poly)-1):
        v1 = poly[i]
        v2 = poly[i+1]
        # area of triangle = 0.5 * |cross(v1-v0, v2-v0)|
        ax1 = [v1[j]-v0[j] for j in range(3)]
        ax2 = [v2[j]-v0[j] for j in range(3)]
        cx = ax1[1]*ax2[2] - ax1[2]*ax2[1]
        cy = ax1[2]*ax2[0] - ax1[0]*ax2[2]
        cz = ax1[0]*ax2[1] - ax1[1]*ax2[0]
        tri_area += (abs((cx**2+cy**2+cz**2)**0.5))/2.0
    return tri_area

