def bbox_length_xy(points):
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]
    if not xs or not ys:
        return None
    dx = max(xs) - min(xs)
    dy = max(ys) - min(ys)
    # return the larger dimension
    return max(dx, dy)

wall_types = []
