    for representation in getattr(rep, 'Representations', []) or []:
        for item in getattr(representation, 'Items', []) or []:
            if item is None:
                continue
            # Collect IfcCartesianPoint directly referenced
            if item.is_a('IfcPoint') and hasattr(item, 'Coordinates'):
                try:
                    coords = [float(c) for c in item.Coordinates]
                    if len(coords) >= 2:
                        pts.append(coords)
                except:
                    pass
            # If polyline
            if item.is_a('IfcPolyline') and hasattr(item, 'Points'):
                for p in item.Points:
                    try:
                        coords = [float(c) for c in p.Coordinates]
                        if len(coords) >= 2:
                            pts.append(coords)
                    except:
                        pass
            # If faceted brep -> faces -> bounds -> loops -> polyLoop -> polygon -> points
            if item.is_a('IfcFacetedBrep') and hasattr(item, 'Outer'):
                outer = item.Outer
                if outer and hasattr(outer, 'Bound'):
                    for face in getattr(outer, 'Bound', []) or []:
                        # face should be IfcFace
                        for face_bound in getattr(face, 'Bounds', []) or []:
                            loop = getattr(face_bound, 'Bound', None)
                            if loop and loop.is_a('IfcPolyLoop') and hasattr(loop, 'Polygon'):
                                for p in loop.Polygon:
                                    try:
                                        coords = [float(c) for c in p.Coordinates]
                                        if len(coords) >= 2:
                                            pts.append(coords)
                                    except:
                                        pass
            # If extruded area solid, try to extract profile points if it's a polygonal profile or rectangle dims
            if item.is_a('IfcExtrudedAreaSolid'):
                swept = getattr(item, 'SweptArea', None)
                if swept:
                    # If profile is rectangle, use Position location and XDim/YDim
                    if swept.is_a('IfcRectangleProfileDef'):
                        xdim = getattr(swept, 'XDim', None)
                        ydim = getattr(swept, 'YDim', None)
                        pos = getattr(swept, 'Position', None)
                        base = [0.0, 0.0, 0.0]
                        if pos and hasattr(pos, 'Location') and pos.Location:
                            try:
                                base = [float(c) for c in pos.Location.Coordinates]
                            except:
                                pass
                        # corners in local XY
                        try:
                            if xdim is not None and ydim is not None:
                                x = float(xdim)/2.0
                                y = float(ydim)/2.0
                                pts.append([base[0]-x, base[1]-y, base[2]])
                                pts.append([base[0]+x, base[1]-y, base[2]])
                                pts.append([base[0]+x, base[1]+y, base[2]])
                                pts.append([base[0]-x, base[1]+y, base[2]])
                        except:
                            pass
                    # If swept area is an IfcArbitraryClosedProfileDef containing an IfcPolyline via OuterCurve
                    if swept.is_a('IfcArbitraryClosedProfileDef'):
                        outer_curve = getattr(swept, 'OuterCurve', None)
                        if outer_curve and outer_curve.is_a('IfcPolyline'):
                            for p in outer_curve.Points:
