import math
# Find the element by GUID, then rotate its local placement's RefDirection by +90 degrees around Z
guid = '22hyxvAPr65PFt9WZfHSP3'
wall = None
try:
    wall = ifc.by_guid(guid)
except Exception:
    wall = None
if not wall:
    # try fallback: search by GlobalId attribute on wall-like entities
    for t in ('IfcWall', 'IfcWallStandardCase', 'IfcProduct'):
        for e in ifc.by_type(t):
            if getattr(e, 'GlobalId', None) == guid:
                wall = e
                break
        if wall:
            break

if not wall:
    result = {'success': False, 'message': f'Element with GUID {guid} not found.'}
else:
    placement = getattr(wall, 'ObjectPlacement', None)
    if not placement:
        result = {'success': False, 'message': 'Element has no ObjectPlacement to modify.'}
    else:
        # find the local placement to modify
        # If it's a local placement, use its RelativePlacement; otherwise, try to find nested local placement
        local_placement = None
        if placement.is_a('IfcLocalPlacement'):
            local_placement = placement
        else:
            # try to resolve if it's a placement that references another local placement
            # (rare for simple walls but handle defensively)
            if getattr(placement, 'PlacementRelTo', None) and placement.PlacementRelTo.is_a('IfcLocalPlacement'):
                local_placement = placement.PlacementRelTo

        if not local_placement:
            result = {'success': False, 'message': 'No IfcLocalPlacement found for the element.'}
        else:
            rel = local_placement.RelativePlacement
            if rel is None:
                result = {'success': False, 'message': 'RelativePlacement is missing on the local placement.'}
            else:
                # get original ref direction (if any)
                old_ref = None
                if rel.is_a('IfcAxis2Placement3D') or rel.is_a('IfcAxis2Placement2D'):
                    rd = getattr(rel, 'RefDirection', None)
                    if rd:
                        # DirectionRatios is a sequence of floats
                        old_ref = tuple(rd.DirectionRatios)
                    else:
                        # default ref direction is X axis
                        old_ref = (1.0, 0.0, 0.0)
                else:
                    # Other placement types: create a default reference
                    old_ref = (1.0, 0.0, 0.0)

                # perform rotation by +90 degrees around Z (counterclockwise looking from +Z)
                angle = math.pi / 2.0
                cos_a = math.cos(angle)
                sin_a = math.sin(angle)

                ox = old_ref[0]
                oy = old_ref[1] if len(old_ref) > 1 else 0.0
                oz = old_ref[2] if len(old_ref) > 2 else 0.0

                nx = cos_a * ox - sin_a * oy
                ny = sin_a * ox + cos_a * oy
                nz = oz

                # create new IfcDirection. Use 3 components for safety
                new_dir = ifc.createIfcDirection((float(nx), float(ny), float(nz)))

                # assign back depending on type
                if rel.is_a('IfcAxis2Placement3D') or rel.is_a('IfcAxis2Placement2D'):
                    rel.RefDirection = new_dir
                else:
                    # if it's some other type, try to replace the relative placement with a new IfcAxis2Placement3D
                    loc = rel.Location if hasattr(rel, 'Location') else None
                    new_axis2 = ifc.createIfcAxis2Placement3D(loc if loc is not None else ifc.createIfcCartesianPoint((0.0,0.0,0.0)), None, new_dir)
                    local_placement.RelativePlacement = new_axis2

                commit()
                result = {
                    'success': True,
                    'message': 'Rotated RefDirection by +90 degrees around Z for the local placement of the element.',
                    'element_guid': guid,
                    'old_ref_direction': old_ref,
                    'new_ref_direction': (float(nx), float(ny), float(nz)),
                    'ifc_file': ifc.schema
                }

