    return ifc.create_entity('IfcCartesianPoint', list(coords))

# helper to set/shift an entity's local placement
def shift_entity_placement(entity, dx, dy, dz, placement_rel_to=None):
    if entity is None:
        return None
    # get or create ObjectPlacement
    pl = getattr(entity, 'ObjectPlacement', None)
    if pl is None:
        # create new local placement with relative placement located at (dx,dy,dz)
        rel_to = placement_rel_to
n        if rel_to is None:
            rel_to = None
        new_point = create_point((dx, dy, dz))
        axis = ifc.create_entity('IfcAxis2Placement3D', new_point)
        new_local = ifc.create_entity('IfcLocalPlacement', rel_to, axis)
        entity.ObjectPlacement = new_local
        return (None, (dx,dy,dz))
    # Expect pl to be IfcLocalPlacement
    rel_placement = getattr(pl, 'RelativePlacement', None)
    if rel_placement is None:
        # create a new axis placement
        new_point = create_point((dx, dy, dz))
        axis = ifc.create_entity('IfcAxis2Placement3D', new_point)
        pl.RelativePlacement = axis
        return (None, (dx,dy,dz))
    # Now rel_placement is IfcAxis2Placement2D or 3D
    loc = getattr(rel_placement, 'Location', None)
    if loc is None:
        new_point = create_point((dx,dy,dz))
        rel_placement.Location = new_point
        return (None, (dx,dy,dz))
    # read old coords
    old_coords = list(getattr(loc, 'Coordinates', []))
    # determine new coords length
    if len(old_coords) >= 3:
        new_coords = (old_coords[0] + dx, old_coords[1] + dy, old_coords[2] + dz)
    elif len(old_coords) == 2:
        new_coords = (old_coords[0] + dx, old_coords[1] + dy)
    elif len(old_coords) == 1:
        new_coords = (old_coords[0] + dx,)
    else:
        new_coords = (dx, dy, dz)
    # create new point and assign
    new_point = create_point(new_coords)
    rel_placement.Location = new_point
    return (tuple(old_coords), tuple(new_coords))

