else:
    result['guid'] = gid
    result['type'] = slab.is_a()
    changed = []
    # Modify any IfcExtrudedAreaSolid depth found in the slab's representations
    try:
        reps = []
        if getattr(slab, 'Representation', None) and getattr(slab.Representation, 'Representations', None):
            reps = slab.Representation.Representations
        for rep in reps:
            # guard for None
            items = getattr(rep, 'Items', []) or []
            for item in items:
                # Direct extruded solid
                if item is None:
                    continue
                if item.is_a('IfcExtrudedAreaSolid'):
                    try:
                        old_depth = float(item.Depth)
                    except Exception:
                        # Depth might be absent or non-numeric
                        continue
                    new_depth = old_depth - 0.5
                    if new_depth <= 0:
                        raise Exception(f'Resulting depth would be non-positive ({new_depth}). Aborting change to preserve geometry.')
                    item.Depth = new_depth
                    changed.append({'representation': rep.RepresentationIdentifier if hasattr(rep, 'RepresentationIdentifier') else None,
                                    'old_depth': old_depth,
                                    'new_depth': new_depth,
                                    'item_id': item.id()})
                # Sometimes extrusion is nested in IfcMappedItem or other wrappers
                # Check if item has 'MappingSource' -> MappedItem -> MappedRepresentation -> Items
                if item.is_a('IfcMappedItem') and getattr(item, 'MappingSource', None) and getattr(item.MappingSource, 'MappedRepresentation', None):
                    for mapped_item in item.MappingSource.MappedRepresentation.Items:
                        if mapped_item.is_a('IfcExtrudedAreaSolid'):
                            try:
                                old_depth = float(mapped_item.Depth)
                            except Exception:
                                continue
                            new_depth = old_depth - 0.5
                            if new_depth <= 0:
                                raise Exception(f'Resulting depth would be non-positive ({new_depth}). Aborting.')
                            mapped_item.Depth = new_depth
                            changed.append({'representation': rep.RepresentationIdentifier if hasattr(rep, 'RepresentationIdentifier') else None,
                                            'old_depth': old_depth,
                                            'new_depth': new_depth,
                                            'item_id': mapped_item.id()})
    except Exception as e:
        result['geometry_error'] = str(e)

    # Update common property set thicknesses if present
    pset_updates = []
    try:
        if getattr(slab, 'IsDefinedBy', None):
            for rel in slab.IsDefinedBy:
                if rel is None:
                    continue
                if rel.is_a('IfcRelDefinesByProperties'):
                    pdef = rel.RelatingPropertyDefinition
                    if pdef is None:
                        continue
                    # If it's a property set
                    if pdef.is_a('IfcPropertySet'):
                        for prop in getattr(pdef, 'HasProperties', []) or []:
                            if prop is None:
                                continue
                            if prop.is_a('IfcPropertySingleValue'):
                                pname = getattr(prop, 'Name', None)
                                if pname in ('NominalThickness', 'Thickness', 'NominalHeight', 'Height'):
                                    # try to read numeric value robustly
                                    val = None
                                    if getattr(prop, 'NominalValue', None) is not None:
                                        nv = prop.NominalValue
                                        # nv might be a simple python type, or an IfcValue with 'wrappedValue'
                                        try:
                                            val = float(nv)
                                        except Exception:
                                            try:
                                                val = float(nv.wrappedValue)
                                            except Exception:
                                                val = None
                                    if val is None:
                                        continue
                                    newv = val - 0.5
                                    if newv <= 0:
                                        # do not set non-positive thickness
                                        continue
                                    # Set NominalValue: if original had wrappedValue, try to preserve structure
                                    try:
                                        if hasattr(prop.NominalValue, 'wrappedValue'):
                                            prop.NominalValue.wrappedValue = newv
                                        else:
                                            prop.NominalValue = newv
                                    except Exception:
                                        # fallback: assign directly
                                        try:
                                            prop.NominalValue = newv
                                        except Exception:
                                            pass
                                    pset_updates.append({'pset': pdef.Name, 'property': pname, 'old': val, 'new': newv})
                    # If property definition is a IfcElementQuantity (quantity sets)
                    if pdef.is_a('IfcElementQuantity'):
                        for qty in getattr(pdef, 'Quantities', []) or []:
                            if qty is None:
                                continue
                            # look for length/volume quantities that indicate thickness
                            if qty.is_a('IfcQuantityLength') and getattr(qty, 'Name', None) in ('Length', 'Thickness', 'NominalThickness'):
                                try:
                                    oldq = float(qty.LengthValue)
                                    newq = oldq - 0.5
                                    if newq <= 0:
                                        continue
                                    qty.LengthValue = newq
                                    pset_updates.append({'quantity_set': pdef.Name, 'quantity': qty.Name, 'old': oldq, 'new': newq})
                                except Exception:
                                    continue
    except Exception as e:
        result['psets_error'] = str(e)

    result['geometry_changes'] = changed
    result['pset_changes'] = pset_updates
    if not changed and not pset_updates and 'geometry_error' not in result:
        result['note'] = 'No extruded solids or thickness properties updated. The slab may use a different geometry representation.'

# Save changes back to the file
commit()

