else:
    # ensure the element has an ObjectPlacement; if not, create one at origin
    op = getattr(entity, 'ObjectPlacement', None)
    created_placement = False
    if not op:
        # create a Cartesian point at origin
        p = ifc.create_entity('IfcCartesianPoint', Coordinates=[0.0, 0.0, 0.0])
        # create an axis2placement3d using that point
        axis = ifc.create_entity('IfcAxis2Placement3D', Location=p, Axis=None, RefDirection=None)
        # create local placement
        op = ifc.create_entity('IfcLocalPlacement', PlacementRelTo=None, RelativePlacement=axis)
        # assign to entity
        entity.ObjectPlacement = op
        created_placement = True

    # now try to find the placement point to modify
    old_coords = None
    new_coords = None
    try:
        rel_placement = None
        # RelativePlacement might be IfcAxis2Placement2D or 3D or others
        if hasattr(op, 'RelativePlacement'):
            rel_placement = op.RelativePlacement
        elif hasattr(op, 'PlacementRelTo') and op.PlacementRelTo is not None and hasattr(op.PlacementRelTo, 'RelativePlacement'):
            rel_placement = op.PlacementRelTo.RelativePlacement

        if rel_placement is None:
            # nothing to modify
            result = {'error': 'No RelativePlacement found on the object placement.'}
        else:
            # the location is usually rel_placement.Location (IfcCartesianPoint)
            location = getattr(rel_placement, 'Location', None)
            if location is None:
                # sometimes 2D placements have Location directly as a point too
                location = getattr(rel_placement, 'RefDirection', None)

            if location is None:
                result = {'error': 'No Location (IfcCartesianPoint) found on RelativePlacement.'}
            else:
                coords = list(getattr(location, 'Coordinates', []) or [])
                # ensure at least 3 components
                while len(coords) < 3:
                    coords.append(0.0)
                old_coords = coords.copy()
                coords[1] = coords[1] + shift_y
                # assign back
                location.Coordinates = coords
                new_coords = coords.copy()
                result = {
                    'entity_type': entity.is_a(),
                    'GlobalId': getattr(entity, 'GlobalId', None),
                    'old_coordinates': old_coords,
                    'new_coordinates': new_coords,
                    'placement_created': created_placement
                }
    except Exception as e:
        result = {'error': f'Exception while modifying placement: {str(e)}'}

# save changes
commit()

# return result
result

