# Helper to generate new IFC GUID
def new_guid():
    try:
        return ifcopenshell.guid.new()
    except Exception:
        # fallback compress
        try:
            return ifcopenshell.guid.compress(uuid.uuid1().hex)
        except Exception:
            return uuid.uuid4().hex

# Helper to get numeric coordinates of an IfcLocalPlacement by summing translations (ignoring rotations)
def get_placement_coords(ifc, placement):
    x = y = z = 0.0
    p = placement
    visited = set()
    while p:
        if p.is_a('IfcLocalPlacement'):
            rp = p.RelativePlacement
            if rp and rp.is_a('IfcAxis2Placement3D'):
                loc = rp.Location
                if loc and hasattr(loc, 'Coordinates'):
                    coords = list(loc.Coordinates)
                    # coords may be tuple, ensure length 3
                    if len(coords) >= 1:
                        x += float(coords[0])
                    if len(coords) >= 2:
                        y += float(coords[1])
                    if len(coords) >= 3:
                        z += float(coords[2])
        # Move to placement it is placed relative to
        try:
            p = p.PlacementRelTo
        except Exception:
            break
    return (x, y, z)

# Find entity by GlobalId
def find_by_globalid(ifc, gid):
    for e in ifc.by_type('IfcProduct') + ifc.by_type('IfcElement'):
        try:
            if getattr(e, 'GlobalId', None) == gid:
                return e
        except Exception:
            continue
    return None

