import ifcopenshell, math

def coords_from_cartesian_point(cp):
    if cp is None:
        return None
    try:
        return tuple(float(c) for c in cp.Coordinates)
    except Exception:
        return None


def collect_points_from_entity(e, pts):
    # Recursively collect Cartesian point coordinates from common geometric entities
    if e is None:
        return
    t = e.is_a() if hasattr(e, 'is_a') else None
    try:
        t = e.is_a()
    except Exception:
        t = None

    if t == 'IfcBoundingBox':
        corner = coords_from_cartesian_point(e.Corner)
        if corner is not None:
            x0,y0,z0 = corner[0], corner[1], corner[2] if len(corner)>2 else 0.0
            x1 = x0 + float(getattr(e, 'XDim', 0.0))
            y1 = y0 + float(getattr(e, 'YDim', 0.0))
            # add two corners
            pts.append((x0,y0,z0))
            pts.append((x1,y1,z0))
        return

    if t == 'IfcPolyline':
        for p in e.Points:
            c = coords_from_cartesian_point(p)
            if c: pts.append(c)
        return

    if t == 'IfcPolyLoop':
        for p in e.Polygon:
            c = coords_from_cartesian_point(p)
            if c: pts.append(c)
        return

    if t == 'IfcCartesianPoint':
        c = coords_from_cartesian_point(e)
        if c: pts.append(c)
        return

    if t == 'IfcExtrudedAreaSolid':
        # try to get profile points
        swept = getattr(e, 'SweptArea', None)
        if swept is not None:
            # Rectangle profile
            if swept.is_a('IfcRectangleProfileDef'):
                pos = getattr(swept, 'Position', None)
                loc = coords_from_cartesian_point(pos.Location) if pos is not None else (0.0,0.0,0.0)
                xdim = float(getattr(swept, 'XDim', 0.0))
                ydim = float(getattr(swept, 'YDim', 0.0))
                cx,cy,cz = loc[0], loc[1], (loc[2] if len(loc)>2 else 0.0)
                hx, hy = xdim/2.0, ydim/2.0
                pts.extend([(cx-hx, cy-hy, cz),(cx+hx, cy-hy, cz),(cx+hx, cy+hy, cz),(cx-hx, cy+hy, cz)])
                return
            # Arbitrary closed profile with OuterCurve
            try:
                oc = getattr(swept, 'OuterCurve', None)
                if oc is not None and oc.is_a('IfcPolyline'):
                    for p in oc.Points:
                        c = coords_from_cartesian_point(p)
                        if c: pts.append(c)
                    return
            except Exception:
                pass
        return

    if t == 'IfcFacetedBrep':
        outer = getattr(e, 'Outer', None)
        if outer is not None:
            shells = getattr(outer, 'CfsFaces', None)
        # try typical structure
        shell = getattr(e, 'Outer', None)
        if shell is not None and hasattr(shell, 'Boundaries'):
            for face in shell.Boundaries:
                collect_points_from_entity(face, pts)
        # fallback iterate attributes
    # Generic: iterate attributes that can contain geometry
    for attr in dir(e):
        if attr.startswith('_'):
            continue
        try:
            val = getattr(e, attr)
        except Exception:
            continue
        if val is None:
            continue
        # if list, iterate
        if isinstance(val, (list, tuple)):
            for item in val:
                # avoid infinite recursion on primitive types
                if hasattr(item, 'is_a'):
                    collect_points_from_entity(item, pts)
        else:
            if hasattr(val, 'is_a'):
                collect_points_from_entity(val, pts)


