ifc = ifcopenshell.open(r"C:\Users\bhara\Documents\University of Rostock\Project\bim-cli\results\run_2026-01-26_14-15-05\edited_ifc_gpt-5-mini-2025-08-07\25\01_01_006_0.ifc")

spaces = ifc.by_type('IfcSpace')

found = None
found_space = None

for space in spaces:
    pts = []
    # try representation items
    rep = getattr(space, 'Representation', None)
    if rep is not None:
        reps = getattr(rep, 'Representations', [])
        for r in reps:
            items = getattr(r, 'Items', [])
            for it in items:
                collect_points_from_entity(it, pts)
    # Also try IfcSpace.BoundedBy (IfcRelSpaceBoundary)
    try:
        bounds = getattr(space, 'BoundedBy', None)
        if bounds:
            for b in bounds:
                # get ConnectionGeometry if present
                conn = getattr(b, 'ConnectionGeometry', None)
                if conn is not None:
                    collect_points_from_entity(conn, pts)
                related = getattr(b, 'RelatedBuildingElement', None)
                if related is not None:
                    # try its representation
                    rep2 = getattr(related, 'Representation', None)
                    if rep2 is not None:
                        reps2 = getattr(rep2, 'Representations', [])
                        for r2 in reps2:
                            for it2 in getattr(r2, 'Items', []):
                                collect_points_from_entity(it2, pts)
    except Exception:
        pass

    # deduplicate points
    uniq = []
    seen = set()
    for p in pts:
        # round to mm
        key = (round(float(p[0]),3), round(float(p[1]),3), round(float(p[2]) if len(p)>2 else 0.0,3))
        if key not in seen:
            seen.add(key)
            uniq.append(key)
    if not uniq:
        continue
    xs = [p[0] for p in uniq]
    ys = [p[1] for p in uniq]
    minx, maxx = min(xs), max(xs)
    miny, maxy = min(ys), max(ys)
    width = maxx - minx
    depth = maxy - miny
    # consider tolerance
    if abs(width - depth) > 0.01:
        length = max(width, depth)
        found = length
        found_space = space
        break

# if none found, attempt fallback using all vertices in model
if found is None:
    all_pts = []
    for e in ifc.by_type('IfcProduct'):
        # skip too many
        rep = getattr(e, 'Representation', None)
        if rep is None:
            continue
        reps = getattr(rep, 'Representations', [])
        for r in reps:
            for it in getattr(r, 'Items', []):
                collect_points_from_entity(it, all_pts)
    uniq = []
    seen = set()
    for p in all_pts:
        key = (round(float(p[0]),3), round(float(p[1]),3), round(float(p[2]) if len(p)>2 else 0.0,3))
        if key not in seen:
            seen.add(key)
            uniq.append(key)
    if uniq:
        xs = [p[0] for p in uniq]
        ys = [p[1] for p in uniq]
        minx, maxx = min(xs), max(xs)
        miny, maxy = min(ys), max(ys)
        width = maxx - minx
        depth = maxy - miny
        if abs(width - depth) > 0.01:
            found = max(width, depth)
            found_space = None

# final result
if found is None:
    result = {'length': None, 'raw_model_response': 'Could not determine a non-square room length from available geometry.'}
else:
    result = {'length': float(found), 'raw_model_response': f'Found non-square space (GlobalId={getattr(found_space, "GlobalId", None)}) length (longest side) = {float(found):.6f} m.'}

