                        if u.is_a('IfcSIUnit') and getattr(u, 'UnitType', None) == 'LENGTHUNIT':
                            name = getattr(u, 'Name', None)
                            prefix = getattr(u, 'Prefix', None)
                            # name expected to be 'METRE'
                            f = 1.0
                            if prefix is not None:
                                pf = str(prefix).upper()
                                if 'MILLI' in pf:
                                    f *= 0.001
                                elif 'CENTI' in pf:
                                    f *= 0.01
                                elif 'DECI' in pf:
                                    f *= 0.1
                                elif 'DEKA' in pf:
                                    f *= 10.0
                                elif 'HECTO' in pf:
                                    f *= 100.0
                                elif 'KILO' in pf:
                                    f *= 1000.0
                            if name is not None:
                                if str(name).upper() == 'METRE' or str(name).upper() == 'METRE':
                                    scale = f
                                    return scale
                        if u.is_a('IfcConversionBasedUnit'):
                            # try to parse name
                            nm = getattr(u, 'Name', '')
                            if nm:
                                s = str(nm).lower()
                                if 'millimet' in s or 'millimetre' in s or 'millimeter' in s:
                                    return 0.001
                                if 'centimet' in s or 'centimeter' in s:
                                    return 0.01
                                if 'metre' in s or 'meter' in s or 'metre' in s:
                                    return 1.0
                                if 'foot' in s:
                                    return 0.3048
                    except Exception:
                        continue
    except Exception:
        pass
    return scale

