    # Compute bounding box ranges in X and Y (assume horizontal length)
    xs = [p[0] if len(p) > 0 else 0.0 for p in pts]
    ys = [p[1] if len(p) > 1 else 0.0 for p in pts]
    zs = [p[2] if len(p) > 2 else 0.0 for p in pts]
