import math
from collections import deque

# Helper vector functions
def norm(v):
    l = math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2])
    if l==0:
        return (0.0,0.0,0.0)
    return (v[0]/l, v[1]/l, v[2]/l)

def dot(a,b):
    return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]

def cross(a,b):
    return (a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0])

def add(a,b):
    return (a[0]+b[0], a[1]+b[1], a[2]+b[2])

def sub(a,b):
    return (a[0]-b[0], a[1]-b[1], a[2]-b[2])

def mul_scalar(v,s):
    return (v[0]*s, v[1]*s, v[2]*s)

# Transform utilities: rotation matrix as 3x3 tuple of tuples, translation as tuple

def mat_vec_mul(mat, v):
    return (mat[0][0]*v[0] + mat[0][1]*v[1] + mat[0][2]*v[2],
            mat[1][0]*v[0] + mat[1][1]*v[1] + mat[1][2]*v[2],
            mat[2][0]*v[0] + mat[2][1]*v[1] + mat[2][2]*v[2])

def mat_mul(a,b):
    # 3x3 matrices
    return tuple(tuple(sum(a[i][k]*b[k][j] for k in range(3)) for j in range(3)) for i in range(3))

IDENTITY = ((1,0,0),(0,1,0),(0,0,1))

# Build rotation matrix from IfcAxis2Placement3D or 2D
def rotation_from_axis2placement(ap):
    # default axes
    z = (0.0,0.0,1.0)
    x = (1.0,0.0,0.0)
    if hasattr(ap, 'Axis') and ap.Axis:
        try:
            z = norm(tuple(ap.Axis.DirectionRatios))
        except Exception:
            pass
    if hasattr(ap, 'RefDirection') and ap.RefDirection:
        try:
            x = norm(tuple(ap.RefDirection.DirectionRatios))
        except Exception:
            pass
    # ensure orthonormal basis: x perpendicular to z
    # compute y = z x x
    y = cross(z, x)
    if math.sqrt(dot(y,y)) < 1e-9:
        # refdir parallel to axis, pick arbitrary x
        if abs(z[0])<0.9:
            x = norm(cross((1,0,0), z))
        else:
            x = norm(cross((0,1,0), z))
        y = cross(z, x)
    x = norm(x)
    y = norm(y)
    # ensure right-hand coordinate system
    if dot(cross(x,y), z) < 0:
        y = mul_scalar(y, -1)
    return ((x[0], y[0], z[0]), (x[1], y[1], z[1]), (x[2], y[2], z[2]))

# Get transform (rotation matrix, translation) for an IfcLocalPlacement
def get_placement_transform(placement):
    rot = IDENTITY
    trans = (0.0,0.0,0.0)
    visited = set()
    p = placement
    # build stack from root to this placement
    stack = []
    while p:
        if id(p) in visited:
            break
        visited.add(id(p))
        stack.append(p)
        p = getattr(p, 'PlacementRelTo', None)
    # apply from root down to local
    for pl in reversed(stack):
        # pl.RelativePlacement is IfcAxis2Placement2D/3D
        ap = getattr(pl, 'RelativePlacement', None)
        local_rot = IDENTITY
        local_trans = (0.0,0.0,0.0)
        if ap is not None:
            # get location if present
            if hasattr(ap, 'Location') and getattr(ap, 'Location') is not None:
                try:
                    coords = tuple(getattr(ap.Location, 'Coordinates'))
                    if len(coords)==2:
                        local_trans = (coords[0], coords[1], 0.0)
                    else:
                        local_trans = (coords[0], coords[1], coords[2])
                except Exception:
                    local_trans = (0.0,0.0,0.0)
            # rotation
            try:
                local_rot = rotation_from_axis2placement(ap)
            except Exception:
                local_rot = IDENTITY
        # compose: new_rot = rot * local_rot ; new_trans = rot*local_trans + trans
        rot = mat_mul(rot, local_rot)
        t = mat_vec_mul(rot, local_trans)
        trans = add(trans, t)
    return rot, trans

# Recursively extract IfcCartesianPoint coordinates from an entity

def extract_cartesian_points(obj, seen=None):
    if seen is None:
        seen = set()
    pts = []
    if obj is None:
        return pts
    uid = getattr(obj, 'id', None)
    if uid is None:
        uid = id(obj)
    if uid in seen:
        return pts
    seen.add(uid)
    # If this is a cartesian point
    try:
        if obj.is_a('IfcCartesianPoint'):
            coords = tuple(obj.Coordinates)
            if len(coords)==2:
                coords = (coords[0], coords[1], 0.0)
            pts.append(tuple(float(c) for c in coords))
            return pts
    except Exception:
        pass
    # iterate attributes
    for attr in obj.__dir__():
        if attr.startswith('__'):
            continue
        try:
            val = getattr(obj, attr)
        except Exception:
            continue
        if val is None:
            continue
        if isinstance(val, (list, tuple)):
            for v in val:
                if hasattr(v, '__dict__') or hasattr(v, 'is_a'):
                    pts.extend(extract_cartesian_points(v, seen))
        else:
            if hasattr(val, '__dict__') or hasattr(val, 'is_a'):
                pts.extend(extract_cartesian_points(val, seen))
    return pts

# Get vertices for an element, trying extruded solids first then general extraction

def get_element_vertices(el):
    verts = []
    # gather vertices from geometric representations
    rep = getattr(el, 'Representation', None)
    if rep:
        for representation in rep.Representations:
            for item in representation.Items:
                # handle extruded area solids explicitly
                try:
                    if item.is_a('IfcExtrudedAreaSolid'):
                        # handle rectangle profile
                        sa = item.SweptArea
                        depth = float(getattr(item, 'Depth', 0.0))
                        # extruded direction
                        ed = getattr(item, 'ExtrudedDirection', None)
                        if ed and getattr(ed, 'DirectionRatios', None):
                            edv = tuple(ed.DirectionRatios)
                            if len(edv)==2:
                                edv = (edv[0], edv[1], 0.0)
                        else:
                            edv = (0.0,0.0,1.0)
                        edv = norm(edv)
                        # profile
                        profile_pts = []
                        if sa and sa.is_a('IfcRectangleProfileDef'):
                            xd = float(getattr(sa, 'XDim', 0.0))
                            yd = float(getattr(sa, 'YDim', 0.0))
                            # center-based rectangle
                            profile_pts = [(-xd/2.0, -yd/2.0, 0.0), (xd/2.0, -yd/2.0, 0.0), (xd/2.0, yd/2.0, 0.0), (-xd/2.0, yd/2.0, 0.0)]
                        else:
                            # fallback: try to extract any cartesian points under swept area
                            profile_pts = extract_cartesian_points(sa)
                        # apply solid position if present
                        local_pts = []
                        pos = getattr(item, 'Position', None)
                        pos_rot = IDENTITY
                        pos_trans = (0.0,0.0,0.0)
                        if pos is not None and getattr(pos, 'Location', None) is not None:
                            try:
                                coords = tuple(pos.Location.Coordinates)
                                if len(coords)==2:
                                    pos_trans = (coords[0], coords[1], 0.0)
                                else:
                                    pos_trans = (coords[0], coords[1], coords[2])
                            except Exception:
                                pos_trans = (0.0,0.0,0.0)
                            try:
                                pos_rot = rotation_from_axis2placement(pos)
                            except Exception:
                                pos_rot = IDENTITY
                        # transform profile_pts by pos_rot and pos_trans
                        for p in profile_pts:
                            tp = mat_vec_mul(pos_rot, p)
                            tp = add(tp, pos_trans)
                            local_pts.append(tp)
                        # create extruded vertices
                        for p in local_pts:
                            verts.append(p)
                            verts.append(add(p, mul_scalar(edv, depth)))
                        continue
                except Exception:
                    pass
                # fallback: extract cartesian points under item
                try:
                    pts = extract_cartesian_points(item)
                    for p in pts:
                        verts.append(p)
                except Exception:
                    pass
    # If no vertices found, fallback to object's placement location
    if not verts:
        # try object placement location
        try:
            lp = getattr(el, 'ObjectPlacement', None)
            if lp is not None and getattr(lp, 'RelativePlacement', None) is not None and getattr(lp.RelativePlacement, 'Location', None) is not None:
                coords = tuple(lp.RelativePlacement.Location.Coordinates)
                if len(coords)==2:
                    verts.append((coords[0], coords[1], 0.0))
                else:
                    verts.append((coords[0], coords[1], coords[2]))
        except Exception:
            pass
    # transform verts by element world transform
    try:
        if getattr(el, 'ObjectPlacement', None) is not None:
            rot, trans = get_placement_transform(el.ObjectPlacement)
            wverts = []
            for p in verts:
                wp = mat_vec_mul(rot, p)
                wp = add(wp, trans)
                wverts.append(wp)
            verts = wverts
    except Exception:
        pass
    return verts

# Get axis-aligned bounding box in world coords for element

def bbox_from_vertices(verts):
    if not verts:
        return None
    xs = [v[0] for v in verts]
    ys = [v[1] for v in verts]
    zs = [v[2] for v in verts]
    return (min(xs), min(ys), min(zs), max(xs), max(ys), max(zs))

# 2D distance between two AABBs in XY plane

def aabb2d_distance(b1, b2):
    # b: (minx,miny,minz,maxx,maxy,maxz)
    minx1, miny1, _, maxx1, maxy1, _ = b1
    minx2, miny2, _, maxx2, maxy2, _ = b2
    dx = 0.0
    if maxx1 < minx2:
        dx = minx2 - maxx1
    elif maxx2 < minx1:
        dx = minx1 - maxx2
    dy = 0.0
    if maxy1 < miny2:
        dy = miny2 - maxy1
    elif maxy2 < miny1:
        dy = miny1 - maxy2
    return math.sqrt(dx*dx + dy*dy)

# Collect walls
walls = list(ifc.by_type('IfcWall')) + list(ifc.by_type('IfcWallStandardCase'))
wall_infos = []
for w in walls:
    verts = get_element_vertices(w)
    bbox = bbox_from_vertices(verts)
    # compute 2D length as diagonal in XY
    length_xy = 0.0
    if bbox:
        minx, miny, _, maxx, maxy, _ = bbox
        length_xy = math.hypot(maxx-minx, maxy-miny)
    else:
        # fallback: use 0
        length_xy = 0.0
    wall_infos.append({'ifc_id': getattr(w, 'GlobalId', getattr(w, 'id', 'unknown')), 'entity': w, 'verts': verts, 'bbox': bbox, 'length_xy': length_xy})

# Need at least 2 walls
if len(wall_infos) < 2:
    result = {'distance_m': 0.0, 'raw_model_response': 'Less than two wall elements found.'}
    commit()
else:
    # sort by length descending
    wall_infos.sort(key=lambda x: x['length_xy'], reverse=True)
    w1 = wall_infos[0]
    w2 = wall_infos[1]
    if w1['bbox'] is None or w2['bbox'] is None:
        # if bbox missing, compute distance between their placement locations
        try:
            p1 = (0.0,0.0,0.0)
            p2 = (0.0,0.0,0.0)
            if getattr(w1['entity'], 'ObjectPlacement', None) and getattr(w1['entity'].ObjectPlacement, 'RelativePlacement', None) and getattr(w1['entity'].ObjectPlacement.RelativePlacement, 'Location', None):
                coords = tuple(w1['entity'].ObjectPlacement.RelativePlacement.Location.Coordinates)
                p1 = (coords[0], coords[1], coords[2] if len(coords)>2 else 0.0)
            if getattr(w2['entity'], 'ObjectPlacement', None) and getattr(w2['entity'].ObjectPlacement, 'RelativePlacement', None) and getattr(w2['entity'].ObjectPlacement.RelativePlacement, 'Location', None):
                coords = tuple(w2['entity'].ObjectPlacement.RelativePlacement.Location.Coordinates)
                p2 = (coords[0], coords[1], coords[2] if len(coords)>2 else 0.0)
            dist = math.hypot(p1[0]-p2[0], p1[1]-p2[1])
        except Exception:
            dist = 0.0
    else:
        dist = aabb2d_distance(w1['bbox'], w2['bbox'])
    raw = 'Wall A GlobalId={} length_xy={:.3f} m bbox={}\nWall B GlobalId={} length_xy={:.3f} m bbox={}'.format(
        w1['ifc_id'], w1['length_xy'], w1['bbox'], w2['ifc_id'], w2['length_xy'], w2['bbox'])
    result = {'distance_m': float(dist), 'raw_model_response': raw}
    commit()

