else:
    # compute reference wall direction (use its placement ref direction)
    ref_placement = getattr(ref_wall, 'ObjectPlacement', None)
    ref_origin, ref_X, ref_Y, ref_Z = placement_world_axes(ref_placement)
    ref_dir = normalize(ref_X)

    # find another wall parallel to ref_wall
    target_wall = None
    for w in ifc.by_type('IfcWall'):
        if w == ref_wall:
