        # compute world X for this wall
        placement = getattr(w, 'ObjectPlacement', None)
        origin, X, Y, Z = placement_world_axes(placement)
        Xn = normalize(X)
        # angle
        dp = max(-1.0, min(1.0, dot(Xn, ref_dir)))
        angle = math.degrees(math.acos(dp))
