        angle_deg = 45.0
        theta = math.radians(angle_deg)
        # compute world axes for target and its parent
        target_placement = getattr(target_wall, 'ObjectPlacement', None)
        # get parent placement (PlacementRelTo)
        parent = None
        if target_placement is not None:
            parent = getattr(target_placement, 'PlacementRelTo', None)
        # world axes for target and for parent
        t_origin, t_X, t_Y, t_Z = placement_world_axes(target_placement)
        if parent is not None:
            p_origin, p_X, p_Y, p_Z = placement_world_axes(parent)
        else:
            p_origin = (0.0,0.0,0.0); p_X=(1,0,0); p_Y=(0,1,0); p_Z=(0,0,1)

        k = normalize(ref_dir)
        if k == (0.0,0.0,0.0):
