        # rotate the target's world RefDirection (t_X) and Axis (t_Z)
        new_t_X = rotate_vector(t_X, k, theta)
        new_t_Z = rotate_vector(t_Z, k, theta)

        # express rotated directions in parent coordinate system for assignment
        # components = dot(rot_vector, parent_axis)
        new_ref_comp = (dot(new_t_X, p_X), dot(new_t_X, p_Y), dot(new_t_X, p_Z))
        new_axis_comp = (dot(new_t_Z, p_X), dot(new_t_Z, p_Y), dot(new_t_Z, p_Z))

        # normalize the direction components to avoid zero-length
        if math.isclose(dot(new_ref_comp,new_ref_comp), 0.0):
            new_ref_comp = (1.0, 0.0, 0.0)
        if math.isclose(dot(new_axis_comp,new_axis_comp), 0.0):
            new_axis_comp = (0.0, 0.0, 1.0)

        # create IfcDirection entities
        new_ref_dir_entity = ifc.create_entity('IfcDirection', new_ref_comp)
        new_axis_dir_entity = ifc.create_entity('IfcDirection', new_axis_comp)

        # ensure target has an IfcAxis2Placement3D in its ObjectPlacement
        if getattr(target_placement, 'RelativePlacement', None) is None:
