import math

def get_point_coords(cart_point):
    return tuple(float(c) for c in cart_point.Coordinates)

def sum_placement_translation(placement):
    x=y=z=0.0
    p = placement
    while p is not None:
        rel = p.RelativePlacement
        if rel is None:
            break
        loc = rel.Location
        coords = get_point_coords(loc)
        x += coords[0]
        y += coords[1] if len(coords) > 1 else 0.0
        z += coords[2] if len(coords) > 2 else 0.0
        if hasattr(p, 'PlacementRelTo') and p.PlacementRelTo:
            p = p.PlacementRelTo
        else:
            break
    return (x,y,z)

def get_global_translation(local_placement):
    return sum_placement_translation(local_placement)

def get_parents_translation(local_placement):
    if not hasattr(local_placement, 'PlacementRelTo') or not local_placement.PlacementRelTo:
        return (0.0, 0.0, 0.0)
    return sum_placement_translation(local_placement.PlacementRelTo)

def cluster_values(values, tol=1e-5):
    if not values:
        return []
    vals = sorted(values)
    clusters = []
    current = [vals[0]]
    for v in vals[1:]:
        if abs(v - current[-1]) <= tol:
            current.append(v)
        else:
            clusters.append(current)
            current = [v]
    clusters.append(current)
    centers = [sum(c)/len(c) for c in clusters]
    return centers

columns = ifc.by_type('IfcColumn')
cols_data = []
for col in columns:
    if not hasattr(col, 'ObjectPlacement') or not col.ObjectPlacement:
        continue
    placement = col.ObjectPlacement
    rel = placement.RelativePlacement
    if rel is None or rel.Location is None:
        continue
    loc = rel.Location
    local_coords = get_point_coords(loc)
    global_coords = get_global_translation(placement)
    cols_data.append({
        'element': col,
        'placement': placement,
        'local_coords': local_coords,
        'global_coords': global_coords,
    })

result = {'initial_count': len(cols_data)}
if len(cols_data) == 0:
    result['message'] = 'No columns found. No changes made.'
else:
    xs = [c['global_coords'][0] for c in cols_data]
    ys = [c['global_coords'][1] for c in cols_data]
    zs = [c['global_coords'][2] for c in cols_data]
    tol_cluster = 1e-4
    x_centers = cluster_values(xs, tol=tol_cluster)
    y_centers = cluster_values(ys, tol=tol_cluster)
    def median_diff(sorted_vals):
        if len(sorted_vals) < 2:
            return None
        diffs = [j-i for i,j in zip(sorted_vals[:-1], sorted_vals[1:]) if abs(j-i) > 1e-9]
        if not diffs:
            return None
        diffs.sort()
        mid = len(diffs)//2
        return diffs[mid]
    sorted_x = sorted(x_centers)
    sorted_y = sorted(y_centers)
    dx = median_diff(sorted_x)
    dy = median_diff(sorted_y)
    if dx is None:
        dx = median_diff(sorted(xs))
    if dy is None:
        dy = median_diff(sorted(ys))
    if dx is None or dy is None:
        dx = dx or 1.0
        dy = dy or 1.0
    min_x = min(xs)
    max_x = max(xs)
    min_y = min(ys)
    max_y = max(ys)
    nx = max(1, int(round((max_x - min_x)/dx)) + 1)
    ny = max(1, int(round((max_y - min_y)/dy)) + 1)
    grid_x = [min_x + i*dx for i in range(nx)]
    grid_y = [min_y + j*dy for j in range(ny)]
    moved = []
    for c in cols_data:
        gx, gy, gz = c['global_coords']
        nearest_x = min(grid_x, key=lambda v: abs(v - gx))
        nearest_y = min(grid_y, key=lambda v: abs(v - gy))
        if abs(nearest_x - gx) <= 1e-6 and abs(nearest_y - gy) <= 1e-6:
            continue
        parents_t = get_parents_translation(c['placement'])
        target_global = (nearest_x, nearest_y, gz)
        local_x = target_global[0] - parents_t[0]
        local_y = target_global[1] - parents_t[1]
        orig_local = c['local_coords']
        if len(orig_local) > 2:
            local_z = orig_local[2]
        else:
            local_z = target_global[2] - parents_t[2]
        rel = c['placement'].RelativePlacement
        loc = rel.Location
        # assign a new Coordinates tuple instead of mutating
        if len(loc.Coordinates) >= 3:
            loc.Coordinates = (local_x, local_y, local_z)
        elif len(loc.Coordinates) == 2:
            loc.Coordinates = (local_x, local_y)
        else:
            loc.Coordinates = (local_x, local_y, local_z)
        moved.append({'ifc_id': c['element'].id(), 'old_global': (gx,gy,gz), 'new_global': target_global})
    result['grid_dx'] = dx
    result['grid_dy'] = dy
    result['grid_x'] = grid_x
    result['grid_y'] = grid_y
    result['moved_count'] = len(moved)
    result['moved'] = moved

commit()

