from math import sqrt

def get_point_from_local_placement(placement):
    # placement: IfcLocalPlacement
    if placement is None:
        return None
    # IfcLocalPlacement has RelativePlacement (IfcAxis2Placement2D/3D)
    rel = getattr(placement, 'RelativePlacement', None)
    pt = None
    if rel is not None:
        loc = getattr(rel, 'Location', None)
        if loc is not None and loc.is_a('IfcCartesianPoint'):
            coords = list(loc.Coordinates)
            # ensure 3D
            if len(coords) == 2:
                coords.append(0.0)
            pt = tuple(float(c) for c in coords)
    # If placement has PlacementRelTo, add recursively (ignoring rotations/axes)
    parent = getattr(placement, 'PlacementRelTo', None)
    if parent is not None:
        parent_pt = get_point_from_local_placement(parent)
        if parent_pt is not None:
            if pt is None:
                pt = parent_pt
            else:
                pt = tuple(p + q for p, q in zip(parent_pt, pt))
    return pt


def get_entity_point(entity):
    # Try ObjectPlacement first
    try:
        placement = getattr(entity, 'ObjectPlacement', None)
        if placement is not None and placement.is_a('IfcLocalPlacement'):
            p = get_point_from_local_placement(placement)
            if p is not None:
                return p
    except Exception:
        pass
    # Fallback: try to find a Cartesian point in representation
    try:
        rep = getattr(entity, 'Representation', None)
        if rep is not None:
            reps = getattr(rep, 'Representations', None) or []
            for r in reps:
                items = getattr(r, 'Items', None) or []
                for it in items:
                    # If item has an 'Location' or 'Position'
                    for attr in ['Position', 'Location', 'Placement']:
                        val = getattr(it, attr, None)
                        if val is not None and getattr(val, 'is_a', lambda x: False)('IfcCartesianPoint'):
                            coords = list(val.Coordinates)
                            if len(coords) == 2:
                                coords.append(0.0)
                            return tuple(float(c) for c in coords)
                    # recursive: if item has 'MappedRepresentation' or 'MappingSource'
                    # try attributes that may contain points
                    for subattr in dir(it):
                        try:
                            sub = getattr(it, subattr)
                        except Exception:
                            continue
                        if hasattr(sub, 'is_a') and sub.is_a('IfcCartesianPoint'):
                            coords = list(sub.Coordinates)
                            if len(coords) == 2:
                                coords.append(0.0)
                            return tuple(float(c) for c in coords)
    except Exception:
        pass
    return None


def distance(a, b):
    return sqrt((a[0]-b[0])**2 + (a[1]-b[1])**2 + (a[2]-b[2])**2)

# Given GlobalIds
gid1 = "1g0NIEjcH1lfGqbYWRqtDg"
gid2 = "1g0NIEjcH1lfGqbYWRqt8M"

doors = ifc.by_type('IfcDoor')
# find door entities for the two GlobalIds
door1 = None
door2 = None
for d in doors:
    try:
        if getattr(d, 'GlobalId', None) == gid1:
            door1 = d
        if getattr(d, 'GlobalId', None) == gid2:
            door2 = d
    except Exception:
        continue

result = {
    'found_door1': bool(door1),
    'found_door2': bool(door2),
    'removed': None,
    'reason': None
}

if not door1 or not door2:
    result['reason'] = 'One or both reference doors not found.'
else:
    p1 = get_entity_point(door1)
    p2 = get_entity_point(door2)
    if p1 is None or p2 is None:
        result['reason'] = 'Could not determine placement points for reference doors.'
    else:
        # Find candidate doors between (excluding the two)
        candidates = []
        vx = (p2[0]-p1[0], p2[1]-p1[1], p2[2]-p1[2])
        vlen2 = vx[0]*vx[0] + vx[1]*vx[1] + vx[2]*vx[2]
        if vlen2 == 0:
            result['reason'] = 'Reference doors have identical positions.'
        else:
            for d in doors:
                if d is door1 or d is door2:
                    continue
                p = get_entity_point(d)
                if p is None:
                    continue
                # project p onto segment p1->p2
                w = (p[0]-p1[0], p[1]-p1[1], p[2]-p1[2])
                t = (w[0]*vx[0] + w[1]*vx[1] + w[2]*vx[2]) / vlen2
                # compute perpendicular distance to infinite line
                # point on line = p1 + t*vx
                proj = (p1[0]+t*vx[0], p1[1]+t*vx[1], p1[2]+t*vx[2])
                perp_dist = distance(p, proj)
                # consider between if t in (0,1) with margin and perp_dist small
                if t > 0.0 and t < 1.0 and perp_dist < 1.0:  # threshold 1.0m
                    # also check aligned roughly: include
                    candidates.append((d, t, perp_dist))
            if not candidates:
                result['reason'] = 'No door found between the two reference doors based on placement and thresholds.'
            else:
                # choose candidate closest to midpoint (t ~ 0.5) or minimal perp_dist
                candidates.sort(key=lambda x: (abs(x[1]-0.5), x[2]))
                target = candidates[0][0]
                try:
                    gid_removed = getattr(target, 'GlobalId', None)
                    # remove entity
                    ifc.remove(target)
                    # commit/save
                    commit()
                    result['removed'] = gid_removed
                except Exception as e:
                    result['reason'] = 'Failed to remove door: ' + str(e)

