from ifcopenshell.util.element import get_bounding_box

result = {"removed": []}

# helper to get bbox as ((minx,miny,minz),(maxx,maxy,maxz))
def get_bbox(entity):
    try:
        bbox = get_bounding_box(entity)
        if not bbox:
            return None
        # bbox may be dict or tuple
        if isinstance(bbox, dict):
            minp = bbox.get('min')
            maxp = bbox.get('max')
            return (tuple(minp), tuple(maxp))
        if isinstance(bbox, (list, tuple)) and len(bbox) == 2:
            return (tuple(bbox[0]), tuple(bbox[1]))
    except Exception:
        return None


def boxes_intersect(b1, b2):
    (min1, max1) = b1
    (min2, max2) = b2
    for i in range(3):
        if min1[i] > max2[i] or min2[i] > max1[i]:
            return False
    return True

# find ground storey
storeys = ifc.by_type('IfcBuildingStorey')
ground = None
if storeys:
    import re
    for s in storeys:
        name = (s.Name or '').lower() if getattr(s, 'Name', None) else ''
        longname = (getattr(s, 'LongName', None) or '').lower()
        if re.search(r'\b(ground floor|ground|gf|eg|g|0)\b', name) or re.search(r'\b(ground floor|ground|gf|eg|g|0)\b', longname):
            ground = s
            break
    if ground is None:
        # pick lowest elevation
        storeys_with_elev = []
        for s in storeys:
            elev = getattr(s, 'Elevation', None)
            try:
                elevf = float(elev) if elev is not None else 0.0
            except Exception:
                elevf = 0.0
            storeys_with_elev.append((s, elevf))
        ground = min(storeys_with_elev, key=lambda x: x[1])[0]
else:
    result['error'] = 'No IfcBuildingStorey found'
    commit()

# collect contained elements for ground storey
contained = []
for rel in ifc.by_type('IfcRelContainedInSpatialStructure'):
