removed = []
for w in walls:
    b_w = bbox_map.get(w)
    if not b_w:
        # cannot determine geometry
        continue
    minp, maxp = b_w
    max_dim = max(maxp[i] - minp[i] for i in range(3))
    if max_dim < 0.5:
        # skip very small elements
        continue
    intersects_any = False
    for other, b_o in bbox_map.items():
        if other is w:
            continue
        if boxes_intersect(b_w, b_o):
            intersects_any = True
            break
    if not intersects_any:
        try:
            ifc.remove(w)
            removed.append({
                'ifc_id': w.id(),
                'GlobalId': getattr(w, 'GlobalId', None),
                'Name': getattr(w, 'Name', None)
