        if not rels:
            # no opening relation; skip
            continue
        rel = rels[0]
        opening = rel.RelatingOpeningElement
        # find IfcRelVoidsElement linking opening to host
        void_rels = [r for r in ifc.by_type('IfcRelVoidsElement') if hasattr(r, 'RelatedOpeningElement') and r.RelatedOpeningElement == opening]
        if not void_rels:
            continue
        void = void_rels[0]
        host = void.RelatingBuildingElement
        if not host:
            continue
        # get host placement transform
        host_placement = host.ObjectPlacement if hasattr(host, 'ObjectPlacement') else None
        R_host, T_host = get_local_placement_transform(host_placement)
        # local Y column is R_host[1]
        Y = R_host[1]
        # compute dot with west direction
        dot = vec_dot(Y, west_dir)
        # threshold
        if dot > 0.5:
            # consider west-facing
            # remove relations filling and then window itself
            # remove IfcRelFillsElement relations
            for r in rels:
                try:
                    ifc.remove(r)
                except Exception:
                    pass
            # also remove any IfcRelDefinesByType or similar referencing this window
            # remove the window
            try:
                removed.append({'id': win.id(), 'GlobalId': getattr(win, 'GlobalId', None), 'Name': getattr(win,'Name',None)})
                ifc.remove(win)
            except Exception:
                pass
    except Exception:
        # skip problematic window
        continue

