import math

def get_coords_from_cartesian_point(pt):
    if pt is None:
        return None
    coords = []
    try:
        coords = list(pt.Coordinates)
    except Exception:
        try:
            # sometimes it is stored as tuple
            coords = list(pt.Coordinates)
        except Exception:
            return None
    # ensure length 3
    if len(coords) == 2:
        coords = [coords[0], coords[1], 0.0]
    elif len(coords) == 1:
        coords = [coords[0], 0.0, 0.0]
    return tuple(float(c) for c in coords)


def get_placement_point(placement):
    # accumulate translations from nested IfcLocalPlacement
    if placement is None:
        return (0.0, 0.0, 0.0)
    x = y = z = 0.0
    current = placement
    visited = set()
    while current is not None:
        # guard against cycles
        if id(current) in visited:
            break
        visited.add(id(current))
        if current.is_a('IfcLocalPlacement'):
            rel = current.RelativePlacement
            if rel is not None and rel.is_a('IfcAxis2Placement3D'):
                loc = rel.Location
                pt = get_coords_from_cartesian_point(loc)
                if pt:
                    x += pt[0]; y += pt[1]; z += pt[2]
            elif rel is not None and rel.is_a('IfcAxis2Placement2D'):
                loc = rel.Location
                pt = get_coords_from_cartesian_point(loc)
                if pt:
                    x += pt[0]; y += pt[1]; # z unchanged
            # move to placement relative to
            if hasattr(current, 'PlacementRelTo') and current.PlacementRelTo is not None:
                current = current.PlacementRelTo
            else:
                break
        else:
            break
    return (x, y, z)


def extract_points_from_rep_item(item):
    pts = []
    t = item
    if t is None:
        return pts
    # IfcExtrudedAreaSolid
    if t.is_a('IfcExtrudedAreaSolid'):
        profile = t.SweptArea
        depth = float(t.Depth) if t.Depth is not None else 0.0
        # base placement of the solid
        pos = t.Position if hasattr(t, 'Position') else None
        base = (0.0, 0.0, 0.0)
        if pos is not None and pos.is_a('IfcAxis2Placement3D'):
            loc = get_coords_from_cartesian_point(pos.Location)
            if loc:
                base = loc
        # profile rectangle
        if profile is not None and profile.is_a('IfcRectangleProfileDef'):
            xdim = float(profile.XDim)
            ydim = float(profile.YDim)
            # profile position
            pref = profile.Position if hasattr(profile, 'Position') else None
            pref_loc = (0.0,0.0,0.0)
            if pref is not None and pref.is_a('IfcAxis2Placement2D'):
                p = get_coords_from_cartesian_point(pref.Location)
                if p:
                    pref_loc = (p[0], p[1], 0.0)
            # corners in local profile coords (centered around profile position)
            halfx = xdim/2.0
            halfy = ydim/2.0
            local_corners = [
                (pref_loc[0]-halfx, pref_loc[1]-halfy, 0.0),
                (pref_loc[0]+halfx, pref_loc[1]-halfy, 0.0),
                (pref_loc[0]+halfx, pref_loc[1]+halfy, 0.0),
                (pref_loc[0]-halfx, pref_loc[1]+halfy, 0.0),
            ]
            # extrusion direction
            ed = (0.0, 0.0, 1.0)
            if hasattr(t, 'ExtrusionDirection') and t.ExtrusionDirection is not None:
                try:
                    coords = list(t.ExtrusionDirection.DirectionRatios)
                    if len(coords) >= 3:
                        ed = (float(coords[0]), float(coords[1]), float(coords[2]))
                except Exception:
                    pass
            for c in local_corners:
                # bottom
                pts.append((base[0]+c[0], base[1]+c[1], base[2]+c[2]))
                # top
                pts.append((base[0]+c[0]+ed[0]*depth, base[1]+c[1]+ed[1]*depth, base[2]+c[2]+ed[2]*depth))
            return pts
        else:
            # unknown swept area: fallback to position only
            pts.append(base)
            return pts
    # IfcFacetedBrep
    if t.is_a('IfcFacetedBrep'):
        outer = t.Outer
        if outer is not None and outer.is_a('IfcConnectedFaceSet'):
            for face in outer.CfsFaces:
                # face is IfcFace -> has Bounds
                for bound in face.Bounds:
                    b = bound
                    # IfcFaceOuterBound may contain BoundingLoop which can be IfcPolyLoop
                    if hasattr(b, 'Bound'):
                        loop = b.Bound
                        if loop is not None and loop.is_a('IfcPolyLoop'):
                            for p in loop.Polygon:
                                coords = get_coords_from_cartesian_point(p)
                                if coords:
                                    pts.append(coords)
        return pts
    # IfcPolyLine or IfcCartesianPoint directly
    if t.is_a('IfcPolyline'):
        for p in t.Points:
            coords = get_coords_from_cartesian_point(p)
            if coords:
                pts.append(coords)
        return pts
    if t.is_a('IfcMappedItem'):
        # Attempt to resolve mapped item: it references MappingSource and MappingTarget
        try:
            mapping_src = t.MappingSource
            map_rep = mapping_src.MappedRepresentation
            for item2 in map_rep.Items:
                pts += extract_points_from_rep_item(item2)
            return pts
        except Exception:
            return pts
    # If item contains geometry with Points attribute
    for attr in ['Points', 'Coords', 'Vertices']:
        if hasattr(t, attr):
            try:
                seq = getattr(t, attr)
                for p in seq:
                    coords = None
                    if hasattr(p, 'Coordinates'):
                        coords = get_coords_from_cartesian_point(p)
                    elif hasattr(p, 'Point'):
                        coords = get_coords_from_cartesian_point(p.Point)
                    if coords:
                        pts.append(coords)
                if pts:
                    return pts
            except Exception:
                pass
    # fallback: if object has a 'Location' attribute
    if hasattr(t, 'Location') and t.Location is not None:
        coords = get_coords_from_cartesian_point(t.Location)
        if coords:
            pts.append(coords)
    return pts


def compute_bbox_from_points(points):
    if not points:
        return None
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]
    zs = [p[2] for p in points]
    return (min(xs), min(ys), min(zs), max(xs), max(ys), max(zs))


def distance_point_to_bbox(pt, bbox):
    if bbox is None:
        return float('inf')
    px,py,pz = pt
    minx,miny,minz,maxx,maxy,maxz = bbox
    dx = 0.0
    if px < minx:
        dx = minx - px
    elif px > maxx:
        dx = px - maxx
    dy = 0.0
    if py < miny:
        dy = miny - py
    elif py > maxy:
        dy = py - maxy
    dz = 0.0
    if pz < minz:
        dz = minz - pz
    elif pz > maxz:
        dz = pz - maxz
    return math.sqrt(dx*dx + dy*dy + dz*dz)

