    if hasattr(entity, 'id'):
        if entity.id() in visited:
            return
        visited.add(entity.id())
    # direct IfcCartesianPoint
    if entity.__class__.__name__ == 'IfcCartesianPoint':
        coords = getattr(entity, 'Coordinates', None)
        if coords:
            points.append(tuple(float(c) for c in coords))
        return
    # rectangle profile
    if entity.__class__.__name__ == 'IfcRectangleProfileDef':
        try:
            x = float(getattr(entity, 'XDim', 0.0) or 0.0)
            y = float(getattr(entity, 'YDim', 0.0) or 0.0)
            pos = getattr(entity, 'Position', None)
            loc = None
            if pos is not None:
                # Position may be IfcAxis2Placement2D
                if hasattr(pos, 'Location') and pos.Location is not None:
                    loc = pos.Location
                elif hasattr(pos, 'Coordinates'):
                    loc = pos
            if loc is not None and hasattr(loc, 'Coordinates'):
                cx, cy = float(loc.Coordinates[0]), float(loc.Coordinates[1])
            else:
                cx, cy = 0.0, 0.0
            # add four corners in XY plane
            hx = x/2.0
            hy = y/2.0
            corners = [(cx - hx, cy - hy, 0.0), (cx + hx, cy - hy, 0.0), (cx + hx, cy + hy, 0.0), (cx - hx, cy + hy, 0.0)]
            for c in corners:
                points.append(c)
        except Exception:
            pass
        return
    # explore attributes
    for attr in entity.__dict__:
        try:
            val = getattr(entity, attr)
        except Exception:
            continue
        if val is None:
            continue
        if isinstance(val, (list, tuple)):
            for v in val:
                if hasattr(v, '__class__'):
                    collect_points(v)
        else:
            if hasattr(val, '__class__'):
                collect_points(val)

