            exmin, exmax = min(xs_e), max(xs_e)
            eymin, eymax = min(ys_e), max(ys_e)
            wall_boundaries.append((exmin, exmax, eymin, eymax))

    # determine missing side: check sides with no wall within tolerance
    tol = max(xmax-xmin, ymax-ymin) * 0.1 + 0.001
    sides = {'min_x': True, 'max_x': True, 'min_y': True, 'max_y': True}
    for wb in wall_boundaries:
        exmin, exmax, eymin, eymax = wb
        # if wall spans near min_x side
        if abs(exmin - xmin) < tol or abs(exmax - xmin) < tol:
            sides['min_x'] = False
        if abs(exmin - xmax) < tol or abs(exmax - xmax) < tol:
            sides['max_x'] = False
        if abs(eymin - ymin) < tol or abs(eymax - ymin) < tol:
            sides['min_y'] = False
        if abs(eymin - ymax) < tol or abs(eymax - ymax) < tol:
            sides['max_y'] = False

    # choose a side to add wall: prefer min_x, max_x, min_y, max_y that is True
    chosen_side = None
    for s in ['min_x','max_x','min_y','max_y']:
        if sides.get(s, True):
            chosen_side = s
            break
    if chosen_side is None:
        chosen_side = 'min_x'

    # wall parameters
    wall_thickness = 0.2
    wall_height = 3.0
    if chosen_side in ('min_x','max_x'):
        # wall runs along Y from ymin to ymax; X at xmin or xmax
        x_pos = xmin if chosen_side=='min_x' else xmax
        length = ymax - ymin
        # wall placement origin at (x_pos - sign*thickness/2, ymin, zmin)
        sign = -1 if chosen_side=='min_x' else 1
        origin_x = x_pos - (wall_thickness/2.0)*sign
        origin_y = ymin
        origin_z = zmin
        extrude_dir = (0.0, 1.0, 0.0)
        depth = length
    else:
        # wall runs along X from xmin to xmax; Y at ymin or ymax
        y_pos = ymin if chosen_side=='min_y' else ymax
        length = xmax - xmin
        sign = -1 if chosen_side=='min_y' else 1
        origin_x = xmin
        origin_y = y_pos - (wall_thickness/2.0)*sign
        origin_z = zmin
        extrude_dir = (1.0, 0.0, 0.0)
        depth = length

