    p_point = ifc.create_entity('IfcCartesianPoint', (0.0, 0.0, 0.0))
    axis2_2d = ifc.create_entity('IfcAxis2Placement2D', p_point)
    rect_profile = ifc.create_entity('IfcRectangleProfileDef', ProfileType='AREA', ProfileName=None, Position=axis2_2d, XDim=wall_thickness, YDim=wall_height)

    # position for extrusion: use Axis2Placement3D located at origin
    pos_point = ifc.create_entity('IfcCartesianPoint', (origin_x, origin_y, origin_z))
    axis2_3d = ifc.create_entity('IfcAxis2Placement3D', pos_point)
    extr_dir = ifc.create_entity('IfcDirection', extrude_dir)
    extruded = ifc.create_entity('IfcExtrudedAreaSolid', SweptArea=rect_profile, Position=axis2_3d, ExtrudedDirection=extr_dir, Depth=depth)

    # shape representation
    if geom is None:
        shape_rep = ifc.create_entity('IfcShapeRepresentation', ContextOfItems=None, RepresentationIdentifier='Body', RepresentationType='SweptSolid', Items=[extruded])
    else:
