    prod_shape = ifc.create_entity('IfcProductDefinitionShape', None, [shape_rep])

    # local placement relative to storey placement if available
    storey_placement = getattr(storey, 'ObjectPlacement', None)
    local_place = ifc.create_entity('IfcLocalPlacement', PlacementRelTo=storey_placement, RelativePlacement=axis2_3d)

    # create the wall
    wall_guid = new_guid() if callable(new_guid) else None
