        # fallback: use space guid with suffix
        wall_guid = (getattr(space, 'GlobalId', 'wall') + '_w')[:22]
    wall = ifc.create_entity('IfcWallStandardCase', GlobalId=wall_guid, OwnerHistory=owner, Name='Auto_Closure_Wall', ObjectPlacement=local_place, Representation=prod_shape)

    # contain in storey
    if storey is not None:
        rel_guid = new_guid() if callable(new_guid) else None
        if rel_guid is None:
            rel_guid = 'rel_cont_' + (getattr(space, 'GlobalId', 's'))
        rel = ifc.create_entity('IfcRelContainedInSpatialStructure', GlobalId=rel_guid, OwnerHistory=owner, Name=None, Description=None, RelatedElements=[wall], RelatingStructure=storey)

    # relate wall as space boundary
    try:
        b_guid = new_guid() if callable(new_guid) else None
        if b_guid is None:
            b_guid = 'rel_sb_' + (getattr(space, 'GlobalId', 's'))
        relsb = ifc.create_entity('IfcRelSpaceBoundary', GlobalId=b_guid, OwnerHistory=owner, Name='Boundary', Description=None, RelatingSpace=space, RelatedBuildingElement=wall, ConnectionGeometry=None)
    except Exception:
        # older schema order of args: try positional
        try:
            relsb = ifc.create_entity('IfcRelSpaceBoundary', space, wall, None)
        except Exception:
            relsb = None

    # commit changes
    commit()

    result = {
        'space_global_id': getattr(space, 'GlobalId', None),
        'created_wall_global_id': getattr(wall, 'GlobalId', None),
        'created_wall_entity': wall,
        'placement_origin': (origin_x, origin_y, origin_z),
        'chosen_side': chosen_side
    }

