    '3_DHXxtdb3wRKlXgyMiH5o',
    '1IMYx2Ej12vu3iYKHoTn08'
]

# Helper to find products by GlobalId
products = []
for p in ifc.by_type('IfcProduct'):
    gid = getattr(p, 'GlobalId', None)
    if gid in target_ids:
        products.append(p)

# If none found, try searching all entity types for matching GlobalId
if not products:
    for ent in ifc:
        try:
            if getattr(ent, 'GlobalId', None) in target_ids:
                products.append(ent)
        except Exception:
            pass

# If still none, return early
if not products:
    result = {'error': 'No products found with the provided GlobalId values.'}
else:
    # Recursive traversal to collect all IfcCartesianPoint coordinates referenced by a product
    def collect_points(obj, points, visited):
        if obj is None:
            return
        oid = getattr(obj, 'id', None)
        if oid and oid in visited:
            return
        if oid:
            visited.add(oid)
        # If this is a Cartesian point
        try:
            if obj.is_a('IfcCartesianPoint'):
                coords = list(obj.Coordinates)
                # ensure floats
                if len(coords) >= 2:
                    # pad to 3
                    while len(coords) < 3:
                        coords = coords + [0.0]
                    points.append(tuple(float(c) for c in coords[:3]))
                return
        except Exception:
            pass
        # If iterable
        if isinstance(obj, (list, tuple)):
            for v in obj:
                try:
                    collect_points(v, points, visited)
                except Exception:
                    pass
            return
        # Iterate attributes of entity-like objects
        try:
            for attr in obj.__dict__:
                try:
                    v = getattr(obj, attr)
                except Exception:
                    continue
                if v is None:
                    continue
                if isinstance(v, (list, tuple)):
                    for item in v:
                        try:
                            if hasattr(item, 'is_a'):
                                collect_points(item, points, visited)
                        except Exception:
                            pass
                else:
                    if hasattr(v, 'is_a'):
                        collect_points(v, points, visited)
        except Exception:
            # Fallback: try iterating through all attribute names from schema
            try:
                for name in obj.__dict__:
                    v = getattr(obj, name)
                    if hasattr(v, 'is_a'):
                        collect_points(v, points, visited)
            except Exception:
                pass

    # Collect points for all target products
    all_points = []
    for prod in products:
        pts = []
        collect_points(prod, pts, set())
        if pts:
            all_points.extend(pts)
        else:
            # Try to get placement location as fallback
            try:
                pl = getattr(prod, 'ObjectPlacement', None)
                if pl and hasattr(pl, 'RelativePlacement'):
                    rp = pl.RelativePlacement
                    if rp and hasattr(rp, 'Location') and rp.Location is not None and rp.Location.is_a('IfcCartesianPoint'):
                        coords = list(rp.Location.Coordinates)
                        while len(coords) < 3:
                            coords.append(0.0)
                        all_points.append(tuple(float(c) for c in coords[:3]))
            except Exception:
                pass

    # If still no points found, use product bounding boxes if present
    if not all_points:
        for prod in products:
            try:
                # If there is an IfcBoundingBox somewhere
                for bbox in ifc.by_type('IfcBoundingBox'):
                    # no direct link; skip
                    pass
            except Exception:
                pass

    # Compute bounds
    if all_points:
        min_x = min(p[0] for p in all_points)
        min_y = min(p[1] for p in all_points)
        min_z = min(p[2] for p in all_points)
        max_x = max(p[0] for p in all_points)
        max_y = max(p[1] for p in all_points)
        max_z = max(p[2] for p in all_points)
    else:
        # Default box near origin if nothing found
        min_x, min_y, min_z = 0.0, 0.0, 0.0
        max_x, max_y, max_z = 1.0, 1.0, 0.2

    # Expand bounds slightly to ensure closure
    margin = 0.05
    min_x -= margin
    min_y -= margin
    max_x += margin
    max_y += margin

    dx = max_x - min_x
    dy = max_y - min_y
    # thickness: choose either small thickness or cover full Z-range depending on elements' heights
    # We'll set base at min_z and thickness as max(0.2, max_z - min_z)
    base_z = min_z
    thickness = max(0.2, max_z - min_z)
    if thickness <= 0.0:
        thickness = 0.2

    # Center position
    center_x = (min_x + max_x) / 2.0
    center_y = (min_y + max_y) / 2.0

    # Get representation context
    contexts = ifc.by_type('IfcGeometricRepresentationContext')
    if contexts:
        geom_context = contexts[0]
    else:
        geom_context = None

    # OwnerHistory reuse
    owner_histories = ifc.by_type('IfcOwnerHistory')
    owner = owner_histories[0] if owner_histories else None

    # Create placement for slab (local placement at center, base_z)
    origin_point = ifc.create_entity('IfcCartesianPoint', (center_x, center_y, base_z))
    axis_placement_prod = ifc.create_entity('IfcAxis2Placement3D', (origin_point, None, None))
    local_placement = ifc.create_entity('IfcLocalPlacement', (None, axis_placement_prod))

    # Create 2D rectangle profile and extrude it
    # Profile in local coordinates: we'll place the rectangle centered, so extrude position will offset by -dx/2, -dy/2
    # Axis2Placement2D origin at (0,0)
    point2d = ifc.create_entity('IfcCartesianPoint', (0.0, 0.0))
    axis2d = ifc.create_entity('IfcAxis2Placement2D', (point2d, None))
    rect_profile = ifc.create_entity('IfcRectangleProfileDef', ('AREA', 'ClosingSlabProfile', axis2d, dx, dy))

    # Extruded area solid: position offset so rectangle centered over product local placement
    pos_point = ifc.create_entity('IfcCartesianPoint', (-dx / 2.0, -dy / 2.0, 0.0))
    pos_axis3 = ifc.create_entity('IfcAxis2Placement3D', (pos_point, None, None))
    dir_vector = ifc.create_entity('IfcDirection', (0.0, 0.0, 1.0))
    extruded = ifc.create_entity('IfcExtrudedAreaSolid', (rect_profile, pos_axis3, dir_vector, float(thickness)))

    # Create shape representation
    if geom_context is not None:
        shape_rep = ifc.create_entity('IfcShapeRepresentation', (geom_context, 'Body', 'SweptSolid', [extruded]))
    else:
        shape_rep = ifc.create_entity('IfcShapeRepresentation', (None, 'Body', 'SweptSolid', [extruded]))

    prod_def_shape = ifc.create_entity('IfcProductDefinitionShape', (None, [shape_rep]))

    # Create slab
    new_guid = ifcopenshell.guid.new()

    slab = ifc.create_entity('IfcSlab', (new_guid, owner, 'Closing Slab', None, None, local_placement, prod_def_shape))

    # Try to attach slab to the same spatial structure as the first product
    attached = False
    try:
        first_prod = products[0]
        for rel in ifc.by_type('IfcRelContainedInSpatialStructure'):
            if hasattr(rel, 'RelatedElements'):
                rel_elems = list(rel.RelatedElements)
                for e in rel_elems:
                    if e == first_prod:
                        # Found the container
                        relating = rel.RelatingStructure
                        # Create a new containment relationship or extend existing one
                        # We'll create a new relation that contains the slab and relates to the same structure
                        rel_guid = ifcopenshell.guid.new()
                        new_rel = ifc.create_entity('IfcRelContainedInSpatialStructure', (rel_guid, owner, 'Contains closing slab', None, [slab], relating))
                        attached = True
                        break
            if attached:
                break
    except Exception:
        attached = False

    # If not attached, try to link to first building storey in file
    if not attached:
        storeys = ifc.by_type('IfcBuildingStorey')
        if storeys:
            relating = storeys[0]
            rel_guid = ifcopenshell.guid.new()
            new_rel = ifc.create_entity('IfcRelContainedInSpatialStructure', (rel_guid, owner, 'Contains closing slab', None, [slab], relating))
            attached = True

    # Commit changes
    commit()

    result = {
        'slab_global_id': slab.GlobalId,
        'slab_entity': slab,
        'bounds': {
            'min_x': min_x, 'min_y': min_y, 'min_z': base_z,
            'max_x': max_x, 'max_y': max_y, 'max_z': base_z + thickness
        },
        'thickness': thickness,
        'attached_to_spatial_structure': attached
    }

