# function to extract inverse references from an entity
def extract_inverses(ent):
    inv = {}
    if not ent:
        return inv
    for attr in dir(ent):
        if attr.startswith('_'):
            continue
        try:
            val = getattr(ent, attr)
        except Exception:
            continue
        if val is None:
            continue
        # lists of references
        if isinstance(val, (list, tuple)) and len(val) > 0:
            guids = []
            types = []
            for v in val:
                try:
                    gid = getattr(v, 'GlobalId', None)
                    t = v.is_a() if hasattr(v, 'is_a') else None
                    guids.append(gid)
                    types.append(t)
                except Exception:
                    guids.append(None)
                    types.append(None)
            inv[attr] = {'count': len(val), 'guids': guids, 'types': types}
        else:
            # single entity
            try:
                if hasattr(val, 'is_a'):
                    inv[attr] = {'count': 1, 'guids': [getattr(val,'GlobalId',None)], 'types': [val.is_a()]}
            except Exception:
                continue
    return inv

