def get_centroid_space(sp):
    # Try representation items to get centroid; fallback to placement location
    if not sp:
        return None
    # try to find a geometric item with coordinates
    try:
        rep = getattr(sp, 'Representation', None)
        if rep:
            for r in rep.Representations:
                for item in getattr(r, 'Items', []) or []:
                    # If it has 'Vertices' (IfcFaceBasedSurfaceModel) or 'Points'
                    if hasattr(item, 'Vertices') and item.Vertices:
                        pts = []
                        for v in item.Vertices:
                            if hasattr(v, 'Coordinates') and v.Coordinates:
                                pts.append(tuple(float(c) for c in v.Coordinates))
                        if pts:
                            xs = [p[0] for p in pts]
                            ys = [p[1] for p in pts]
                            zs = [p[2] if len(p)>2 else 0.0 for p in pts]
                            return (sum(xs)/len(xs), sum(ys)/len(ys), sum(zs)/len(zs))
                    if item.is_a('IfcExtrudedAreaSolid'):
                        # try to compute approximate centroid from SweptArea and Depth
                        prof = item.SweptArea
                        depth = getattr(item, 'Depth', 0.0) or 0.0
                        # if rectangle profile
                        if prof.is_a('IfcRectangleProfileDef'):
                            x = float(getattr(prof, 'XDim', 0.0) or 0.0)
                            y = float(getattr(prof, 'YDim', 0.0) or 0.0)
                            # centroid local
                            cx = x/2.0
                            cy = y/2.0
                            cz = depth/2.0
                            # try to get position
                            pos = getattr(item, 'Position', None)
                            if pos and hasattr(pos, 'Location') and getattr(pos.Location,'Coordinates',None):
                                loc = tuple(float(c) for c in pos.Location.Coordinates)
                                return (loc[0]+cx, loc[1]+cy, (loc[2] if len(loc)>2 else 0.0)+cz)
    except Exception:
        pass
    # fallback to object placement
    try:
        pl = getattr(sp, 'ObjectPlacement', None)
        pt = point_from_placement(pl)
        if pt:
            return pt
    except Exception:
        pass
    return None

