def get_wall_point(w):
    # try placement
    try:
        pl = getattr(w, 'ObjectPlacement', None)
        pt = point_from_placement(pl)
        if pt:
            return pt
    except Exception:
        pass
    # try representation centroid
    try:
        rep = getattr(w, 'Representation', None)
        if rep:
            for r in rep.Representations:
                for item in getattr(r, 'Items', []) or []:
                    if hasattr(item, 'Vertices') and item.Vertices:
                        pts = []
                        for v in item.Vertices:
                            if hasattr(v, 'Coordinates') and v.Coordinates:
                                pts.append(tuple(float(c) for c in v.Coordinates))
                        if pts:
                            xs = [p[0] for p in pts]
                            ys = [p[1] for p in pts]
                            zs = [p[2] if len(p)>2 else 0.0 for p in pts]
                            return (sum(xs)/len(xs), sum(ys)/len(ys), sum(zs)/len(zs))
    except Exception:
        pass
    return None

candidates = []
if c1 and c2:
    vx = c2[0]-c1[0]
    vy = c2[1]-c1[1]
    vz = c2[2]-c1[2]
    vlen2 = vx*vx+vy*vy+vz*vz
    total_dist = math.sqrt(vlen2) if vlen2>0 else 0.0
    for w in walls:
        wp = get_wall_point(w)
        if not wp:
            continue
        # projection parameter t
        wx = wp[0]-c1[0]
        wy = wp[1]-c1[1]
        wz = wp[2]-c1[2]
        t = (wx*vx + wy*vy + wz*vz) / (vlen2 if vlen2>0 else 1.0)
        # perpendicular distance
        projx = c1[0] + t*vx
        projy = c1[1] + t*vy
        projz = c1[2] + t*vz
        perp_dist = math.sqrt((wp[0]-projx)**2 + (wp[1]-projy)**2 + (wp[2]-projz)**2)
        # distances to each center
        d1 = math.sqrt((wp[0]-c1[0])**2 + (wp[1]-c1[1])**2 + (wp[2]-c1[2])**2)
        d2 = math.sqrt((wp[0]-c2[0])**2 + (wp[1]-c2[1])**2 + (wp[2]-c2[2])**2)
        # heuristics: projection between centers (with margin) and perp_dist small relative to total_dist
        if t >= -0.1 and t <= 1.1 and perp_dist <= max(0.6, total_dist*0.15):
            candidates.append({'wall_guid': getattr(w,'GlobalId',None),'t': t, 'perp_dist': perp_dist, 'd1':d1,'d2':d2})

# sort candidates by perp_dist
candidates_sorted = sorted(candidates, key=lambda x: x['perp_dist'])

result = {
    'space1': {'GlobalId': guid1, 'Name': getattr(space1,'Name',None), 'centroid': c1},
    'space2': {'GlobalId': guid2, 'Name': getattr(space2,'Name',None), 'centroid': c2},
    'candidates': candidates_sorted
}

