# function to compute bounding box for a representation item

def bbox_from_item(item):
    # return (minx,miny,minz),(maxx,maxy,maxz) or None
    try:
        if item.is_a('IfcExtrudedAreaSolid'):
            prof = item.SweptArea
            depth = float(getattr(item, 'Depth', 0.0) or 0.0)
            pos = getattr(item, 'Position', None)
            # default local origin
            ox,oy,oz = 0.0,0.0,0.0
            if pos and getattr(pos,'Location',None) and getattr(pos.Location,'Coordinates',None):
                coords = pos.Location.Coordinates
                ox,oy,oz = float(coords[0]), float(coords[1]), float(coords[2]) if len(coords)>2 else 0.0
            # handle rectangle profile
            if prof.is_a('IfcRectangleProfileDef'):
                x = float(getattr(prof,'XDim',0.0) or 0.0)
                y = float(getattr(prof,'YDim',0.0) or 0.0)
                # assume extrusion along local Z
                minx = ox
                miny = oy
                minz = oz
                maxx = ox + x
                maxy = oy + y
                maxz = oz + depth
                # normalize min/max
                mn = (min(minx,maxx), min(miny,maxy), min(minz,maxz))
                mx = (max(minx,maxx), max(miny,maxy), max(minz,maxz))
                return mn,mx
        if item.is_a('IfcFacetedBrep'):
            verts = []
            for shell in getattr(item, 'Outer', []) or []:
                if hasattr(shell, 'Boundaries'):
                    for b in shell.Boundaries:
                        for poly in getattr(b, 'Polygon', []) or []:
                            for v in getattr(poly, 'Vertices', []) or []:
                                if getattr(v,'Coordinates',None):
                                    coords = v.Coordinates
                                    verts.append(tuple(float(c) for c in coords))
            if verts:
                xs = [p[0] for p in verts]
                ys = [p[1] for p in verts]
                zs = [p[2] if len(p)>2 else 0.0 for p in verts]
                return (min(xs),min(ys),min(zs)), (max(xs),max(ys),max(zs))
        # Some IfcRepresentationItem might be IfcMappedItem or IfcTriangulatedFaceSet with Vertices
        if hasattr(item, 'Vertices') and item.Vertices:
            pts = []
            for v in item.Vertices:
                if getattr(v,'Coordinates',None):
                    pts.append(tuple(float(c) for c in v.Coordinates))
            if pts:
                xs = [p[0] for p in pts]
                ys = [p[1] for p in pts]
                zs = [p[2] if len(p)>2 else 0.0 for p in pts]
                return (min(xs),min(ys),min(zs)), (max(xs),max(ys),max(zs))
    except Exception:
        pass
    return None

# compute bbox for an element by scanning its representation

def bbox_for_element(el):
    try:
        rep = getattr(el, 'Representation', None)
        if not rep:
            return None
        boxes = []
        for r in getattr(rep, 'Representations', []) or []:
            for item in getattr(r, 'Items', []) or []:
                b = bbox_from_item(item)
                if b:
                    boxes.append(b)
        if not boxes:
            return None
        # merge
        minx = min(b[0][0] for b in boxes)
        miny = min(b[0][1] for b in boxes)
        minz = min(b[0][2] for b in boxes)
        maxx = max(b[1][0] for b in boxes)
        maxy = max(b[1][1] for b in boxes)
        maxz = max(b[1][2] for b in boxes)
        return (minx,miny,minz),(maxx,maxy,maxz)
    except Exception:
        return None

# distance from segment to axis-aligned box

def seg_box_dist(seg_a, seg_b, box_min, box_max):
    # sample closest point by clamping projection points? Use conservative approach: compute minimum distance among segment endpoints and box, and also check if segment intersects box
    # First check if segment intersects box: using separating axis test simplified by clamping
    # Compute closest point on segment to box
    # For simplicity, sample several points along segment and take min distance to box
    samples = 11
    min_dist = float('inf')
    ax,ay,az = seg_a
    bx,by,bz = seg_b
    for i in range(samples):
        t = i/(samples-1)
        x = ax + t*(bx-ax)
        y = ay + t*(by-ay)
        z = az + t*(bz-az)
        # distance from point to box
        dx = 0.0
        if x < box_min[0]:
            dx = box_min[0]-x
        elif x > box_max[0]:
            dx = x-box_max[0]
        dy = 0.0
        if y < box_min[1]:
            dy = box_min[1]-y
        elif y > box_max[1]:
            dy = y-box_max[1]
        dz = 0.0
        if z < box_min[2]:
            dz = box_min[2]-z
        elif z > box_max[2]:
            dz = z-box_max[2]
        dist = math.sqrt(dx*dx+dy*dy+dz*dz)
        if dist < min_dist:
            min_dist = dist
    return min_dist

# iterate walls
