        if not boxes:
            return None
        minx = min(b[0][0] for b in boxes)
        miny = min(b[0][1] for b in boxes)
        minz = min(b[0][2] for b in boxes)
        maxx = max(b[1][0] for b in boxes)
        maxy = max(b[1][1] for b in boxes)
        maxz = max(b[1][2] for b in boxes)
        return (minx,miny,minz),(maxx,maxy,maxz)
    except Exception:
        return None

# centroid for space by bbox or placement

def centroid_space(sp):
    if not sp:
        return None
    b = bbox_for_element(sp)
    if b:
        mn, mx = b
        return ((mn[0]+mx[0])/2.0, (mn[1]+mx[1])/2.0, (mn[2]+mx[2])/2.0)
    p = point_from_placement(getattr(sp,'ObjectPlacement',None))
