# seg-box distance function

def seg_box_dist(seg_a, seg_b, box_min, box_max):
    samples = 21
    min_dist = float('inf')
    ax,ay,az = seg_a
    bx,by,bz = seg_b
    for i in range(samples):
        t = i/(samples-1)
        x = ax + t*(bx-ax)
        y = ay + t*(by-ay)
        z = az + t*(bz-az)
        dx = 0.0
        if x < box_min[0]: dx = box_min[0]-x
        elif x > box_max[0]: dx = x-box_max[0]
        dy = 0.0
        if y < box_min[1]: dy = box_min[1]-y
        elif y > box_max[1]: dy = y-box_max[1]
        dz = 0.0
        if z < box_min[2]: dz = box_min[2]-z
        elif z > box_max[2]: dz = z-box_max[2]
        dist = math.sqrt(dx*dx+dy*dy+dz*dz)
        if dist < min_dist: min_dist = dist
    return min_dist

