                        if hasattr(it, 'Depth'):
                            it.Depth = new_depth
                            changed = True
                        elif hasattr(it, 'Length'):
                            it.Length = new_depth
                            changed = True
            if changed:
                modified.append({'beam_globalid': getattr(beam, 'GlobalId', None), 'new_depth': new_depth, 'beam_express_id': beam.id()})
        except Exception as e:
