from math import sqrt

def vec_coords(ifc_point):
    if ifc_point is None:
        return None
    if hasattr(ifc_point, 'Coordinates'):
        coords = list(ifc_point.Coordinates)
    elif hasattr(ifc_point, 'DirectionRatios'):
        coords = list(ifc_point.DirectionRatios)
    else:
        try:
            coords = list(ifc_point)
        except Exception:
            return None
    return tuple(float(c) for c in coords)

def dot(a, b):
    return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]

def length(a):
    from math import sqrt
    return sqrt(dot(a,a))

def normalize(a):
    l = length(a)
    if l == 0:
        return (0.0,0.0,0.0)
    return (a[0]/l, a[1]/l, a[2]/l)

def sub(a,b):
    return (a[0]-b[0], a[1]-b[1], a[2]-b[2])

def cross(a,b):
    return (a[1]*b[2] - a[2]*b[1], a[2]*b[0] - a[0]*b[2], a[0]*b[1] - a[1]*b[0])

