    # Build adjacency map from relationships that connect elements
    adjacency = {}
    def add_adj(a,b):
        adjacency.setdefault(a, set()).add(b)

    # IfcRelConnectsElements
    for rel in ifc.by_type('IfcRelConnectsElements'):
        a = getattr(rel, 'RelatingElement', None)
        b = getattr(rel, 'RelatedElement', None)
        if a is None or b is None:
            continue
        add_adj(a.id(), b.id())
        add_adj(b.id(), a.id())

    # IfcRelInterferesElements (clash relationships)
    for rel in ifc.by_type('IfcRelInterferesElements'):
        a = getattr(rel, 'RelatingElement', None)
        b = getattr(rel, 'RelatedElement', None)
        if a is None or b is None:
            continue
        # b can be list or single
        if isinstance(b, (list, tuple)):
            for bi in b:
                add_adj(a.id(), bi.id())
                add_adj(bi.id(), a.id())
        else:
            add_adj(a.id(), b.id())
            add_adj(b.id(), a.id())

    # Also consider IfcRelAggregates and IfcRelContainedInSpatialStructure (parent-child)
    for rel in ifc.by_type('IfcRelAggregates'):
        parent = getattr(rel, 'RelatingObject', None)
        children = getattr(rel, 'RelatedObjects', None)
        if parent and children:
            for c in children:
                add_adj(parent.id(), c.id())
                add_adj(c.id(), parent.id())
    for rel in ifc.by_type('IfcRelContainedInSpatialStructure'):
        parent = getattr(rel, 'RelatingStructure', None)
        children = getattr(rel, 'RelatedElements', None)
        if parent and children:
