from collections import deque

def collect_points_from_entity(ent):
    pts = []
    visited = set()
    q = deque([ent])
    while q:
        e = q.popleft()
        if e is None:
            continue
        # avoid infinite loops
        if hasattr(e, 'id'):
            ident = (e.__class__.__name__, getattr(e, 'id', None))
            if ident in visited:
                continue
            visited.add(ident)
        # IfIfcCartesianPoint
        if e.__class__.__name__ == 'IfcCartesianPoint':
            try:
                coords = list(e.Coordinates)
                if len(coords) >= 2:
                    pts.append((float(coords[0]), float(coords[1]), float(coords[2]) if len(coords) > 2 else 0.0))
                continue
            except Exception:
                pass
        # IfcCartesianPointList3D
        if e.__class__.__name__ == 'IfcCartesianPointList3D':
            try:
                for c in e.Coordinates:
                    pts.append((float(c[0]), float(c[1]), float(c[2])))
                continue
            except Exception:
                pass
        # IfcBoundingBox
        if e.__class__.__name__ == 'IfcBoundingBox':
            try:
                corner = e.Corner
                dim = e.XDim, e.YDim, getattr(e, 'ZDim', 0.0)
                if corner is not None and corner.__class__.__name__ == 'IfcCartesianPoint':
                    c = corner.Coordinates
                    cx = float(c[0]); cy = float(c[1]); cz = float(c[2]) if len(c)>2 else 0.0
                    pts.append((cx, cy, cz))
                    pts.append((cx+float(dim[0]), cy+float(dim[1]), cz+float(dim[2])))
                    continue
            except Exception:
                pass
        # IfcPolyLoop / IfcPolyLine etc contain IfcCartesianPoint or lists
        # iterate attributes
        for attr in e.__dict__.get('attributes', []) if hasattr(e, '__dict__') else []:
            try:
                val = getattr(e, attr)
            except Exception:
                continue
            if val is None:
                continue
            if isinstance(val, (list, tuple)):
                for v in val:
                    if v is None:
                        continue
                    if hasattr(v, '__class__'):
                        q.append(v)
            else:
                if hasattr(val, '__class__'):
                    q.append(val)
    return pts


def get_product_points(product):
    pts = []
    # Try object placement location
    try:
        if hasattr(product, 'ObjectPlacement') and product.ObjectPlacement is not None:
            # drill into IfcLocalPlacement->PlacementRelTo->RelativePlacement->Location
            lp = product.ObjectPlacement
            # Sometimes lp is IfcLocalPlacement
            if lp.__class__.__name__ == 'IfcLocalPlacement':
                # traverse RelTo chain to accumulate origin - we'll take the last Location found
                stack = [lp]
                visited = set()
                while stack:
                    cur = stack.pop()
                    if not hasattr(cur, '__class__'):
                        continue
                    if getattr(cur, 'id', None) in visited:
                        continue
                    visited.add(getattr(cur, 'id', None))
                    if hasattr(cur, 'RelativePlacement') and cur.RelativePlacement is not None:
                        rp = cur.RelativePlacement
                        if hasattr(rp, 'Location') and rp.Location is not None:
                            loc = rp.Location
                            if loc.__class__.__name__ == 'IfcCartesianPoint':
                                coords = list(loc.Coordinates)
                                pts.append((float(coords[0]), float(coords[1]), float(coords[2]) if len(coords)>2 else 0.0))
                    if hasattr(cur, 'PlacementRelTo') and cur.PlacementRelTo is not None:
                        stack.append(cur.PlacementRelTo)
    except Exception:
        pass
    # Try representation geometry
    try:
        if hasattr(product, 'Representation') and product.Representation is not None:
            for rep in product.Representation.Representations:
                for item in rep.Items:
                    try:
                        p = collect_points_from_entity(item)
                        if p:
                            pts.extend(p)
                    except Exception:
                        pass
    except Exception:
        pass
    return pts


def bbox_from_points(pts):
    if not pts:
        return None
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    zs = [p[2] for p in pts]
    return (min(xs), min(ys), min(zs), max(xs), max(ys), max(zs))


def bbox_center(bbox):
    if bbox is None:
        return None
    return ((bbox[0]+bbox[3])/2.0, (bbox[1]+bbox[4])/2.0, (bbox[2]+bbox[5])/2.0)


def bbox_intersect(b1, b2):
    if b1 is None or b2 is None:
        return None
    x0 = max(b1[0], b2[0])
    y0 = max(b1[1], b2[1])
