else:
    def poly_area_xy(points):
        # points: list of (x,y,z) or (x,y)
        pts = [(p[0], p[1]) for p in points]
        a = 0.0
        n = len(pts)
        for i in range(n):
            x1,y1 = pts[i]
            x2,y2 = pts[(i+1)%n]
            a += x1*y2 - x2*y1
        return abs(a)/2.0

    def try_profile_area(profile):
        if profile is None:
            return None
        t = profile.is_a()
        # Rectangle
        if t == 'IfcRectangleProfileDef':
            try:
                x = float(profile.XDim)
                y = float(profile.YDim)
                return x*y
            except Exception:
                return None
        # Circle
        if t == 'IfcCircleProfileDef':
            try:
                r = float(profile.Radius)
                return math.pi * r * r
            except Exception:
                return None
        # Arbitrary closed profile
        if t == 'IfcArbitraryClosedProfileDef':
            outer = getattr(profile, 'OuterCurve', None)
            if outer is None:
                return None
            if outer.is_a('IfcPolyline'):
                pts = []
                for p in getattr(outer, 'Points') or []:
                    coords = getattr(p, 'Coordinates', None)
                    if coords is None:
                        # IfcCartesianPoint has Coordinates attribute as list
                        coords = getattr(p, 'Coordinates', None)
                    # try to get x,y,z
                    try:
                        # if coords is an IfcCartesianPoint wrapper, try x,y,z
                        if hasattr(p, 'Coordinates') and p.Coordinates:
                            co = p.Coordinates
                            # sometimes it's a tuple
                            pts.append((float(co[0]), float(co[1]), float(co[2]) if len(co)>2 else 0.0))
                        else:
                            # try attributes X,Y,Z
                            x = getattr(p, 'X', None)
                            y = getattr(p, 'Y', None)
                            z = getattr(p, 'Z', None)
                            if x is not None and y is not None:
                                pts.append((float(x), float(y), float(z) if z is not None else 0.0))
                    except Exception:
                        continue
                if len(pts) >= 3:
                    return poly_area_xy(pts)
            # other curve types not handled
            return None
        # If other profile types, no handling
        return None

    def traverse_item(item):
        if item is None:
            return None
        typ = item.is_a()
        # If ExtrudedAreaSolid
        if typ == 'IfcExtrudedAreaSolid':
            profile = getattr(item, 'SweptArea', None)
            area = try_profile_area(profile)
            if area is not None:
                return area
            # if profile not giving area, maybe Thickness? ignore
            return None
        # If CSG primitive like IfcBox? handled via Profile? Rare
        if typ == 'IfcAdvancedBrep' or typ == 'IfcFacetedBrep' or typ == 'IfcBrep' or typ == 'IfcFacetedBrepWithVoids':
            # try to compute area of faces with horizontal normal by summing face polygon areas
            try:
                shell = getattr(item, 'Outer') or getattr(item, 'OuterShell', None) or getattr(item, 'Outer', None)
                faces = []
                # For IfcFacetedBrep, shell is IfcClosedShell with list of faces
                if shell is None:
                    return None
                face_list = getattr(shell, 'Faces', None) or getattr(shell, 'CfsFaces', None) or []
                total_top_area = 0.0
                for f in face_list:
                    # Each face has Bounds -> IfcFaceBound with Bound-> IfcPolyLoop -> Polygon
                    bounds = getattr(f, 'Bounds', None) or []
                    for b in bounds:
                        loop = getattr(b, 'Bound')
                        if loop is None:
                            continue
                        # loop is IfcPolyLoop with polygon list (IfcCartesianPoint list)
                        pts = []
                        for p in getattr(loop, 'Polygon') or []:
                            try:
                                co = getattr(p, 'Coordinates', None)
                                if co:
                                    pts.append((float(co[0]), float(co[1]), float(co[2]) if len(co)>2 else 0.0))
                            except Exception:
                                continue
                        if len(pts) < 3:
                            continue
                        # compute normal to decide if approximately horizontal
                        # compute normal from first three points
                        p0 = pts[0]; p1 = pts[1]; p2 = pts[2]
                        ux = p1[0]-p0[0]; uy = p1[1]-p0[1]; uz = p1[2]-p0[2]
                        vx = p2[0]-p0[0]; vy = p2[1]-p0[1]; vz = p2[2]-p0[2]
                        nx = uy*vz - uz*vy
                        ny = uz*vx - ux*vz
                        nz = ux*vy - uy*vx
                        # normalize length
                        ln = math.sqrt(nx*nx+ny*ny+nz*nz) if (nx or ny or nz) else 0.0
                        if ln == 0:
                            continue
                        nzn = nz/ln
                        # consider face horizontal if |nz| > 0.9
                        if abs(nzn) > 0.9:
                            area = poly_area_xy(pts)
                            total_top_area += area
                if total_top_area > 0.0:
                    return total_top_area
            except Exception:
                return None
            return None
        # If mapped item, follow Mapping
        if typ == 'IfcMappedItem':
            mapdef = getattr(item, 'MappingSource', None)
            if mapdef is not None:
                target = getattr(mapdef, 'MappingTarget', None)
                if target is not None:
                    return traverse_item(target)
            return None
        # If GeometricRepresentationItem that contains other items
        # check common container attributes
        for colattr in ['Items','RepresentationItems','Faces','GeometricItems','Shapes']:
            coll = getattr(item, colattr, None)
            if coll:
                for it in coll:
                    area = traverse_item(it)
                    if area is not None:
                        return area
        return None

    # Inspect Representation
    rep = getattr(space, 'Representation', None)
    area_found = None
    if rep is not None:
        for r in getattr(rep, 'Representations') or []:
            for item in getattr(r, 'Items') or []:
