# Helper functions

def point_to_tuple(pt):
    # If pt is IfcCartesianPoint or similar
    try:
        coords = list(pt.Coordinates)
        return tuple(float(c) for c in coords)
    except Exception:
        # pt might be a direct list/tuple
        try:
            return tuple(float(c) for c in pt)
        except Exception:
            return None

def norm(v):
    return math.sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2])

def cross(a, b):
    return (a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0])

def sub(a,b):
    return (a[0]-b[0], a[1]-b[1], a[2]-b[2])

def poly_area_3d(pts):
    # pts: list of 3-tuples
    if len(pts) < 3:
        return 0.0
    sum_cross = (0.0, 0.0, 0.0)
    for i in range(len(pts)):
        p1 = pts[i]
        p2 = pts[(i+1)%len(pts)]
        cr = cross(p1, p2)
        sum_cross = (sum_cross[0]+cr[0], sum_cross[1]+cr[1], sum_cross[2]+cr[2])
    area = 0.5 * norm(sum_cross)
    return area


def extract_points_from_ifc_entity(ent):
    # Try common containers
    pts = []
    if ent is None:
        return pts
    # If it's an IfcPolyline
    if getattr(ent, 'Points', None) is not None:
        for p in ent.Points:
            t = point_to_tuple(p)
            if t is not None:
                # ensure 3 coords
                if len(t) == 2:
                    t = (t[0], t[1], 0.0)
                pts.append(t)
        return pts
    # If it's IfcCartesianPointList or IfcCartesianPointList3D
    if getattr(ent, 'CoordList', None) is not None:
        for coords in ent.CoordList:
            try:
                coords = list(coords)
                if len(coords) == 2:
                    coords = (float(coords[0]), float(coords[1]), 0.0)
                elif len(coords) >= 3:
                    coords = (float(coords[0]), float(coords[1]), float(coords[2]))
                pts.append(coords)
            except Exception:
                continue
        return pts
    # If it's IfcFaceBound -> Bound -> Bound.Polygon maybe
    # Fallback: if ent has attribute 'Outer' or 'Bound'
    if getattr(ent, 'Bound', None) is not None:
        return extract_points_from_ifc_entity(ent.Bound)
    if getattr(ent, 'Bound', None) is None and getattr(ent, 'Bounds', None) is not None:
        # face bounds
        for b in ent.Bounds:
            # each b may be IfcFaceBound
            try:
                geom = getattr(b, 'Bound', None) or getattr(b, 'BoundGeometry', None)
                if geom is not None:
                    pts += extract_points_from_ifc_entity(geom)
            except Exception:
                continue
        return pts
    return pts


