from math import isfinite

# Helper functions

def name_matches_area(n):
    if not n:
        return False
    s = n.strip().lower()
    # common patterns indicating gross floor area or area
    if 'gross' in s and 'area' in s:
        return True
    if 'grossfloor' in s or 'gross_floor' in s or 'grossfloorarea' in s:
        return True
    # generic area name (fallback)
    if s == 'area' or s.endswith('area') or s == 'areameasure':
        return True
    return False


def get_value_from_property_single(prop):
    # IfcPropertySingleValue: check NominalValue
    val = None
    if hasattr(prop, 'NominalValue') and prop.NominalValue is not None:
        # wrappedValue gives the Python value for IfcSimpleValue types
        try:
            val = getattr(prop.NominalValue, 'wrappedValue', None)
        except Exception:
            val = None
    return val


def search_property_def_for_area(prop_def):
    # prop_def may be IfcPropertySet or IfcElementQuantity or other
    if prop_def is None:
        return None
    # If IfcElementQuantity
    if prop_def.is_a('IfcElementQuantity'):
        for q in getattr(prop_def, 'Quantities', []) or []:
            if q is None:
                continue
            # IfcQuantityArea
            if q.is_a('IfcQuantityArea'):
                name = getattr(q, 'Name', None)
                if name_matches_area(name):
                    val = getattr(q, 'AreaValue', None)
                    if val is not None:
                        return float(val)
                # fallback: accept any IfcQuantityArea
                if name is not None and name.strip() != '':
                    # as fallback return the first area quantity
                    val = getattr(q, 'AreaValue', None)
                    if val is not None:
                        return float(val)
    # If IfcPropertySet
    if prop_def.is_a('IfcPropertySet'):
        for p in getattr(prop_def, 'HasProperties', []) or []:
            if p is None:
                continue
            if p.is_a('IfcPropertySingleValue'):
                name = getattr(p, 'Name', None)
                val = get_value_from_property_single(p)
                if val is None:
                    continue
                try:
                    v = float(val)
                except Exception:
                    continue
                if name_matches_area(name):
                    return v
                # fallback: accept first numeric property that looks like area
                if 'area' in (name or '').lower():
                    return v
    return None

