from math import isfinite

def get_area_from_quantity(q):
    try:
        # IfcQuantityArea
        if q.is_a('IfcQuantityArea'):
            for attr in ('AreaValue', 'Area'):
                if hasattr(q, attr):
                    val = getattr(q, attr)
                    if val is not None:
                        return float(val)
        # IfcPropertySingleValue
        if q.is_a('IfcPropertySingleValue'):
            val = getattr(q, 'NominalValue', None)
            if val is None:
                try:
                    val = q.NominalValue.wrappedValue
                except Exception:
                    pass
            if val is not None:
                return float(val)
    except Exception:
        pass
    return None

# Collect storeys
storeys = ifc.by_type('IfcBuildingStorey')

gross_total = 0.0
storey_areas = {}

# Pre-collect all RelContained to speed lookup
rels_contained = ifc.by_type('IfcRelContainedInSpatialStructure')

for st in storeys:
    st_area = 0.0
    # find related spaces via IfcRelContainedInSpatialStructure
    for rel in rels_contained:
        try:
            if rel.RelatingStructure is st:
                for prod in rel.RelatedElements:
                    if prod.is_a('IfcSpace'):
                        # Look for quantities or properties on the space
                        if hasattr(prod, 'IsDefinedBy'):
                            for rd in prod.IsDefinedBy:
                                if not rd:
                                    continue
                                if rd.is_a('IfcRelDefinesByProperties'):
                                    prop = rd.RelatingPropertyDefinition
                                    if not prop:
                                        continue
                                    if prop.is_a('IfcElementQuantity'):
                                        for q in getattr(prop, 'Quantities', []):
                                            a = get_area_from_quantity(q)
                                            if a is not None:
                                                st_area += a
                                                break
                                    elif prop.is_a('IfcPropertySet'):
                                        for p in getattr(prop, 'HasProperties', []):
                                            a = get_area_from_quantity(p)
                                            if a is not None:
                                                st_area += a
                                                break
                        # direct attributes fallback
                        for attr in ('GrossFloorArea', 'Area'):
                            if hasattr(prod, attr):
                                try:
                                    v = getattr(prod, attr)
                                    if v is not None:
                                        st_area += float(v)
                                except Exception:
                                    pass
        except Exception:
            pass
    # fallback: check storey-level properties if no space areas found
    if st_area == 0.0 and hasattr(st, 'IsDefinedBy'):
        for rd in st.IsDefinedBy:
            if not rd:
                continue
            if rd.is_a('IfcRelDefinesByProperties'):
                prop = rd.RelatingPropertyDefinition
                if not prop:
                    continue
                if prop.is_a('IfcElementQuantity'):
                    for q in getattr(prop, 'Quantities', []):
                        a = get_area_from_quantity(q)
                        if a is not None:
                            st_area += a
                elif prop.is_a('IfcPropertySet'):
                    for p in getattr(prop, 'HasProperties', []):
                        a = get_area_from_quantity(p)
                        if a is not None:
                            st_area += a

    name = getattr(st, 'Name', None) or getattr(st, 'LongName', None) or str(getattr(st, 'GlobalId', ''))
    storey_areas[name] = st_area
    gross_total += st_area

# Set result and commit
result = {'value': gross_total, 'raw_model_response': storey_areas}
commit()

