def get_area_from_quantities(entity):
    areas = []
    if not hasattr(entity, 'IsDefinedBy'):
        return areas
    for rel in getattr(entity, 'IsDefinedBy', []):
        rdef = getattr(rel, 'RelatingPropertyDefinition', None)
        if rdef is None:
            continue
        # If element quantities
        if rdef.is_a('IfcElementQuantity'):
            for q in getattr(rdef, 'Quantities', []):
                if q.is_a('IfcQuantityArea'):
                    # try common attribute names
                    val = None
                    if hasattr(q, 'AreaValue'):
                        val = safe_float(getattr(q, 'AreaValue'))
                    elif hasattr(q, 'Area'):
                        val = safe_float(getattr(q, 'Area'))
                    # fallback
                    if val is not None:
                        areas.append((getattr(q, 'Name', ''), val))
        # If property set with single values
        elif rdef.is_a('IfcPropertySet'):
            for prop in getattr(rdef, 'HasProperties', []):
                if prop.is_a('IfcPropertySingleValue'):
                    name = getattr(prop, 'Name', '') or ''
                    # look for likely names indicating inner/net area
                    if 'inner' in name.lower() or 'net' in name.lower() or 'wall' in name.lower():
                        val = None
                        nv = getattr(prop, 'NominalValue', None)
                        if nv is not None:
