def safe_float(val):
    try:
        return float(val)
    except:
        try:
            return float(val.wrappedValue)
        except:
            try:
                return float(val[0])
            except:
                return None

def tri_area(a, b, c):
    # a,b,c are (x,y,z)
    ax,ay,az = a; bx,by,bz = b; cx,cy,cz = c
    ux,uy,uz = bx-ax, by-ay, bz-az
    vx,vy,vz = cx-ax, cy-ay, cz-az
    cxp = uy*vz - uz*vy
    cyp = uz*vx - ux*vz
    czp = ux*vy - uy*vx
    return 0.5 * math.sqrt(cxp*cxp + cyp*cyp + czp*czp)

def polygon_area_3d(pts):
    if len(pts) < 3:
        return 0.0
    v0 = pts[0]
    area = 0.0
    for i in range(1, len(pts)-1):
        area += tri_area(v0, pts[i], pts[i+1])
    return area


def coords_from_ifc_cartesian_point(p):
    # p.Coordinates is a list
    try:
        return tuple(float(c) for c in getattr(p, 'Coordinates', p)[0:3])
    except:
        # If p is just a list
        try:
            return tuple(float(c) for c in p[0:3])
        except:
            return (0.0,0.0,0.0)


def compute_area_from_rep_item(item):
    areas = []
    t = item.is_a()
    # Extruded area solid (common for walls)
    if item.is_a('IfcExtrudedAreaSolid'):
        depth = safe_float(getattr(item, 'Depth', None))
        swept = getattr(item, 'SweptArea', None)
        if swept is not None and depth is not None:
            # If rectangle profile
            if swept.is_a('IfcRectangleProfileDef'):
                x = safe_float(getattr(swept, 'XDim', None))
                y = safe_float(getattr(swept, 'YDim', None))
                # height is the larger of X/Y
                candidates = [v for v in (x,y) if v is not None]
                if candidates:
                    height = max(candidates)
                    area = float(depth) * float(height)
                    areas.append(('extruded_rectangle_estimated', area))
            else:
                # fallback: if swept has a ProfileType or Outer curve with points -> try compute perimeter
                # Not implementing complex profile parsing; skip
                pass
    # Faceted brep
    if item.is_a('IfcFacetedBrep'):
        shell = getattr(item, 'Outer', None)
        faces = getattr(shell, 'CfsFaces', None) or getattr(shell, 'Faces', None) or []
        # faces might be in shell.Faces
        if not faces and shell is not None:
            faces = getattr(shell, 'Faces', [])
        for face in faces:
            # face.Bounds
            bounds = getattr(face, 'Bounds', [])
            for b in bounds:
                bound = getattr(b, 'Bound', None)
                if bound is None:
                    continue
                if bound.is_a('IfcPolyLoop'):
                    pts = []
                    for cp in getattr(bound, 'Polygon', []):
                        pts.append(coords_from_ifc_cartesian_point(cp))
                    if pts:
                        areas.append(('faceted_face', polygon_area_3d(pts)))
                # If other bound types, try to extract
    # IfcTriangulatedFaceSet
    if item.is_a('IfcTriangulatedFaceSet'):
        coords = []
        if hasattr(item, 'Coordinates') and getattr(item, 'Coordinates') is not None:
            cl = getattr(item.Coordinates, 'CoordList', [])
            for c in cl:
                coords.append(tuple(float(v) for v in c[0:3]))
        # CoordIndex is list of triples
        for tri in getattr(item, 'CoordIndex', []):
            # tri may be tuple of ints
            if len(tri) >= 3:
                a = coords[tri[0]]
                b = coords[tri[1]]
                c = coords[tri[2]]
                areas.append(('tri_face', tri_area(a,b,c)))
    # IfcFaceBasedSurfaceModel
    if item.is_a('IfcFaceBasedSurfaceModel'):
        for face in getattr(item, 'FbFaces', []) or getattr(item, 'Faces', []):
            bounds = getattr(face, 'Bounds', [])
            for b in bounds:
                bound = getattr(b, 'Bound', None)
                if bound is None:
                    continue
                if bound.is_a('IfcPolyLoop'):
                    pts = [coords_from_ifc_cartesian_point(cp) for cp in getattr(bound, 'Polygon', [])]
                    areas.append(('surface_face', polygon_area_3d(pts)))
    return areas


def compute_wall_area(entity):
    areas = []
    rep = getattr(entity, 'Representation', None)
    if rep is None:
        return areas
    for rep2 in getattr(rep, 'Representations', []) or [rep]:
        for item in getattr(rep2, 'Items', []):
            areas.extend(compute_area_from_rep_item(item))
    return areas

