    # Common wrappers: IfcReal, IfcLengthMeasure, IfcAreaMeasure, IfcLabel may have .wrappedValue
    if hasattr(val, 'wrappedValue'):
        return float(val.wrappedValue)
    # Sometimes numeric directly
    try:
        return float(val)
