for gid in globalids:
    el = find_element_by_globalid(gid)
    details = {
        'globalid': gid,
        'found': el is not None,
        'quantities': [],
        'properties': [],
        'computed_area': None
    }
    chosen_area = None
    if not el:
        results[gid] = details
        missing.append(gid)
        continue

    # Inspect IsDefinedBy relationships for quantities and property sets
    length_val = None
    height_val = None
    for rel in getattr(el, 'IsDefinedBy', []) or []:
        rel_def = getattr(rel, 'RelatingPropertyDefinition', None)
        if rel_def is None:
            continue
        # IfcElementQuantity
        if rel_def.is_a('IfcElementQuantity'):
            for q in getattr(rel_def, 'Quantities', []) or []:
                qname = getattr(q, 'Name', None)
                entry = {'type': q.__class__.__name__, 'name': qname, 'value': None}
                val = None
                if q.is_a('IfcQuantityArea'):
                    # try common attribute names
                    val = getattr(q, 'AreaValue', None)
                    if val is None:
                        val = getattr(q, 'Area', None)
                elif q.is_a('IfcQuantityLength'):
                    val = getattr(q, 'LengthValue', None)
                else:
                    # other quantity types
                    for attr in ('AreaValue','Area','Value','LengthValue','VolumeValue'):
                        if hasattr(q, attr):
                            val = getattr(q, attr)
                            break
                entry['value'] = get_numeric(val)
                details['quantities'].append(entry)
        # IfcPropertySet
        elif rel_def.is_a('IfcPropertySet'):
            for p in getattr(rel_def, 'HasProperties', []) or []:
                pname = getattr(p, 'Name', None)
                pentry = {'type': p.__class__.__name__, 'name': pname, 'value': None}
                if p.is_a('IfcPropertySingleValue'):
                    nominal = getattr(p, 'NominalValue', None)
                    pentry['value'] = get_numeric(nominal)
                    details['properties'].append(pentry)
                    if pname:
                        pn = pname.lower()
                        if 'length' in pn and pentry['value'] is not None:
                            length_val = pentry['value']
                        if ('height' in pn or 'storey height' in pn) and pentry['value'] is not None:
                            height_val = pentry['value']
                        if 'area' in pn and pentry['value'] is not None:
                            # treat as candidate area
                            details['quantities'].append({'type': 'IfcPropertySingleValue(area)', 'name': pname, 'value': pentry['value']})
                else:
                    # other property types — ignore for now
                    pass

    # Now select best area from quantities
    # Prefer IfcQuantityArea entries with names containing 'outer' and/or 'net', then containing 'net', then containing 'outer', then generic 'area'
    q_areas = [q for q in details['quantities'] if q['value'] is not None]
    chosen = None
    def score(qname):
        if not qname:
            return 0
        n = qname.lower()
        s = 0
        if 'outer' in n: s += 4
        if 'net' in n: s += 3
        if 'gross' in n: s += 1
        if 'area' in n: s += 1
        return s

    if q_areas:
        # compute best by score
        best = max(q_areas, key=lambda q: score(q['name']))
        chosen = best['value']
        chosen_name = best['name']
    else:
        chosen = None
        chosen_name = None

    # If no explicit area found, try compute from length * height
    if chosen is None and length_val is not None and height_val is not None:
        chosen = length_val * height_val
        chosen_name = 'computed_length*height'
        details['computed_area'] = chosen

    details['chosen_area_name'] = chosen_name
    details['chosen_area_value'] = chosen

    results[gid] = details

# Sum chosen areas, ignoring None
total = 0.0
for gid, d in results.items():
    val = d.get('chosen_area_value')
    if val is not None:
        total += float(val)

# Set result as required
result = {
    'value': total,
    'units': 'm2',
    'per_wall': results,
}

# Commit (no changes, but required by instructions)
commit()

import re

globalids = ["1YYXjRkjn7ywhxb576N3hM", "1YYXjRkjn7ywhxb576N3nB", "1YYXjRkjn7ywhxb576N3m0", "1YYXjRkjn7ywhxb576N3gT"]

# Robust numeric extractor
unit_map = {
    'mm': ('length', 0.001),
    'cm': ('length', 0.01),
    'm': ('length', 1.0),
    'mm2': ('area', 1e-6),
    'cm2': ('area', 1e-4),
    'm2': ('area', 1.0),
    'sqm': ('area', 1.0),
    'sq m': ('area', 1.0),
}

num_re = re.compile(r'([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)(?:\s*([a-zA-Z0-9μ²^/\s]+))?')

def get_numeric(val, pname=None):
    if val is None:
        return None
    # If wrappedValue attr (IfcMeasureValue wrappers)
    if hasattr(val, 'wrappedValue'):
        try:
            return float(val.wrappedValue)
        except Exception:
            # fall through to string handling
            val = str(val.wrappedValue)
    # Direct numeric types
    try:
        return float(val)
    except Exception:
        pass
    s = str(val).strip()
    if s == '':
        return None
    m = num_re.search(s)
    if not m:
        return None
    num = float(m.group(1))
    unit = m.group(2)
    if unit:
        unit = unit.strip().lower()
        # normalize micro symbol
        unit = unit.replace('μ', 'u')
        # simplify unit by removing parens/slashes
        unit = unit.replace('²', '2').replace('^2', '2')
        # remove text like 'thickness' etc
        # try match known units keys
        for k in unit_map.keys():
            if k in unit:
                kind, factor = unit_map[k]
                # interpret based on pname: if pname suggests area and unit is length, convert squared
                if pname and 'area' in str(pname).lower() and kind == 'length':
                    # length unit given but pname says area -> assume unit meant squared
                    return num * (factor ** 2)
                return num * factor
    # no unit: infer from pname
    if pname:
        pn = str(pname).lower()
        if 'area' in pn or 'a' == pn:
            return num  # assume m2
        if 'length' in pn or 'height' in pn or 'width' in pn or 'thickness' in pn:
            return num  # assume meters
    # fallback: return number as-is
    return num

# Find element by GlobalId
def find_element_by_globalid(gid):
    try:
        el = ifc.by_guid(gid)
        if el:
            return el
    except Exception:
        pass
    for t in ("IfcWall", "IfcWallStandardCase", "IfcWallType"):
        for el in ifc.by_type(t):
            if getattr(el, 'GlobalId', None) == gid:
                return el
    for el in ifc.by_type('IfcProduct'):
        if getattr(el, 'GlobalId', None) == gid:
            return el
    return None

results = {}

for gid in globalids:
    el = find_element_by_globalid(gid)
    details = {'globalid': gid, 'found': bool(el), 'quantities': [], 'properties': [], 'chosen_area_name': None, 'chosen_area_value': None}
    if not el:
        results[gid] = details
        continue
    # inspect IsDefinedBy
    length_val = None
    height_val = None
    q_areas = []
    for rel in getattr(el, 'IsDefinedBy', []) or []:
        rel_def = getattr(rel, 'RelatingPropertyDefinition', None)
        if rel_def is None:
            continue
        # Quantities
        if rel_def.is_a('IfcElementQuantity'):
            for q in getattr(rel_def, 'Quantities', []) or []:
                qname = getattr(q, 'Name', None)
                val = None
                if q.is_a('IfcQuantityArea'):
                    # try common attribute names
                    val_attr = getattr(q, 'AreaValue', None)
                    if val_attr is None:
                        # some authors use 'Area' or 'Value'
                        for attr in ('Area', 'Value', 'AreaValue'):
                            if hasattr(q, attr):
                                val_attr = getattr(q, attr)
                                break
                    val = get_numeric(val_attr, qname)
                    if val is not None:
                        q_areas.append({'name': qname, 'value': val, 'source': q.__class__.__name__})
                elif q.is_a('IfcQuantityLength'):
                    val_attr = getattr(q, 'LengthValue', None)
                    val = get_numeric(val_attr, qname)
                    if val is not None:
                        if qname and 'height' in str(qname).lower():
                            height_val = val
                        elif qname and 'length' in str(qname).lower():
                            length_val = val
                else:
                    # try generic numeric attributes
                    for attr in ('AreaValue','Area','Value','LengthValue','VolumeValue'):
                        if hasattr(q, attr):
                            val_attr = getattr(q, attr)
                            val = get_numeric(val_attr, qname)
                            if val is not None:
                                q_areas.append({'name': qname, 'value': val, 'source': q.__class__.__name__})
                                break
                details['quantities'].append({'name': qname, 'value': val})
        # Property sets
        elif rel_def.is_a('IfcPropertySet'):
            for p in getattr(rel_def, 'HasProperties', []) or []:
                pname = getattr(p, 'Name', None)
                pval = None
                if p.is_a('IfcPropertySingleValue'):
                    nominal = getattr(p, 'NominalValue', None)
                    pval = get_numeric(nominal, pname)
                    details['properties'].append({'name': pname, 'value': pval, 'type': p.__class__.__name__})
                    if pname:
                        pn = pname.lower()
                        if 'length' in pn and pval is not None:
                            length_val = pval
                        if 'height' in pn and pval is not None:
                            height_val = pval
                        if 'area' in pn and pval is not None:
                            q_areas.append({'name': pname, 'value': pval, 'source': 'IfcPropertySingleValue'})
                else:
                    # ignore other property types
                    pass

    # Choose best area from q_areas: score by name containing outer/net
    def score_name(n):
        if not n:
            return 0
        n = n.lower()
        s = 0
        if 'outer' in n: s += 4
        if 'net' in n: s += 3
        if 'gross' in n: s += 1
        if 'area' in n: s += 1
        return s

    chosen = None
    chosen_name = None
    if q_areas:
        best = max(q_areas, key=lambda q: score_name(q.get('name')))
        chosen = best.get('value')
        chosen_name = best.get('name')
    # If not found, compute from length*height if both present
    if chosen is None and length_val is not None and height_val is not None:
        try:
            chosen = float(length_val) * float(height_val)
            chosen_name = 'computed_length*height'
        except Exception:
            chosen = None
    details['chosen_area_name'] = chosen_name
    details['chosen_area_value'] = chosen
    results[gid] = details

# Sum chosen areas
total = 0.0
for gid, d in results.items():
    v = d.get('chosen_area_value')
    if v is not None:
        try:
            total += float(v)
        except Exception:
            pass

result = {'value': total, 'units': 'm2', 'per_wall': results}
commit()

from math import pi

# The IFC model is already loaded as 'ifc'
wall_guids = ["37DacD4NnAp8bYABNd$pI9", "1YYXjRkjn7ywhxb576N3m0", "1YYXjRkjn7ywhxb576N3gT"]

def get_entity_by_guid(guid):
    try:
        ent = ifc.by_guid(guid)
        return ent
    except Exception:
        # fallback: linear search
        for e in ifc.by_type('IfcProduct'):
            if getattr(e, 'GlobalId', None) == guid:
                return e
    return None

def rect_area(profile):
    x = getattr(profile, 'XDimension', None)
    y = getattr(profile, 'YDimension', None)
    if x is not None and y is not None:
        return float(x) * float(y)
    return None

def circle_area(profile):
    r = getattr(profile, 'Radius', None)
    if r is not None:
        return pi * float(r) * float(r)
    return None

def swept_area_of_profile(profile):
    # handle common profile defs
    t = profile.is_a()
    if profile.is_a('IfcRectangleProfileDef'):
        a = rect_area(profile)
        if a is not None:
            return a
    if profile.is_a('IfcCircleProfileDef'):
        a = circle_area(profile)
        if a is not None:
            return a
    # fallback: unknown profile -> None
    return None


def compute_opening_area(opening):
    # try to find a simple swept area representation for the opening
    if hasattr(opening, 'Representation') and opening.Representation is not None:
        for rep in opening.Representation.Representations:
            for item in rep.Items:
                if item.is_a('IfcExtrudedAreaSolid'):
                    profile = item.SweptArea
                    a = swept_area_of_profile(profile)
                    if a is not None:
                        # For extruded opening, the swept area is profile area; opening projects through thickness/depth
                        return float(a)
    # fallback: if opening has bounding box proxy (not using geometry engine), try to read IfcQuantity
    if hasattr(opening, 'IsDefinedBy'):
        for rel in opening.IsDefinedBy:
            if rel.is_a('IfcRelDefinesByProperties') and rel.RelatingPropertyDefinition:
                q = rel.RelatingPropertyDefinition
                if q.is_a('IfcElementQuantity'):
                    for qty in q.Quantities:
                        if qty.is_a('IfcQuantityArea'):
                            return float(qty.AreaValue)
    return None


def compute_wall_inner_area_from_extrusion(wall):
    # Look for an IfcExtrudedAreaSolid in the wall representation
    for rep in (wall.Representation.Representations if getattr(wall, 'Representation', None) else []):
        for item in rep.Items:
            if item.is_a('IfcExtrudedAreaSolid'):
                profile = item.SweptArea
                depth = getattr(item, 'Depth', None)
                # Many IFC wall extrusions use rectangle profile with YDimension = height, depth = length
                # We assume inner surface area = height * length
                height = None
                if profile.is_a('IfcRectangleProfileDef'):
                    # Some models use YDimension as height
                    height = getattr(profile, 'YDimension', None)
                # If we didn't get height, check if profile has arbitrary area and try to get from quantities
                if height is None:
                    # try element quantities for Height or HeightValue
                    if hasattr(wall, 'IsDefinedBy'):
                        for rel in wall.IsDefinedBy:
                            if rel.is_a('IfcRelDefinesByProperties') and rel.RelatingPropertyDefinition:
                                q = rel.RelatingPropertyDefinition
                                if q.is_a('IfcElementQuantity'):
                                    for qty in q.Quantities:
                                        if qty.is_a('IfcQuantityLength') and ('Height' in getattr(qty, 'Name', '')):
                                            height = getattr(qty, 'LengthValue', None)
                if depth is None:
                    # try to get length from quantities
                    if hasattr(wall, 'IsDefinedBy'):
                        for rel in wall.IsDefinedBy:
                            if rel.is_a('IfcRelDefinesByProperties') and rel.RelatingPropertyDefinition:
                                q = rel.RelatingPropertyDefinition
                                if q.is_a('IfcElementQuantity'):
                                    for qty in q.Quantities:
                                        if qty.is_a('IfcQuantityLength') and ('Length' in getattr(qty, 'Name', '') or 'WallLength' in getattr(qty, 'Name', '')):
                                            depth = getattr(qty, 'LengthValue', None)
                # Coerce to floats if present
                try:
                    if depth is not None:
                        depth = float(depth)
                    if height is not None:
                        height = float(height)
                except Exception:
                    pass
                # If both available, compute inner area
                if height is not None and depth is not None:
                    return height * depth
    return None


def get_area_from_quantities(wall):
    if hasattr(wall, 'IsDefinedBy'):
        for rel in wall.IsDefinedBy:
            if rel.is_a('IfcRelDefinesByProperties') and rel.RelatingPropertyDefinition:
                prop = rel.RelatingPropertyDefinition
                if prop.is_a('IfcElementQuantity'):
                    for qty in prop.Quantities:
                        if qty.is_a('IfcQuantityArea'):
                            name = getattr(qty, 'Name', '').lower()
                            # prefer net-related names
                            if 'net' in name or 'inner' in name or 'interior' in name or 'surface' in name or name in ('area', 'areavalue'):
                                try:
                                    return float(qty.AreaValue)
                                except Exception:
                                    pass
    return None

results = {}

for gid in wall_guids:
    ent = get_entity_by_guid(gid)
    area = None
    note = []
    if ent is None:
        results[gid] = {'area_m2': None, 'note': 'Wall with GlobalId not found'}
        continue
    # Try quantities first
    area = get_area_from_quantities(ent)
    if area is not None:
        note.append('from_IFC_quantities')
    # Try extrusion-based computation
    if area is None:
        area = compute_wall_inner_area_from_extrusion(ent)
        if area is not None:
            note.append('from_extruded_profile_guess')
    # If we have openings, subtract their areas (if we computed from extrusion or quantities)
    if area is not None and hasattr(ent, 'HasOpenings') and ent.HasOpenings:
        total_openings_area = 0.0
        for rel in ent.HasOpenings:
            # rel is IfcRelVoidsElement
            opening = rel.RelatedOpeningElement
            oa = compute_opening_area(opening)
            if oa is not None:
                total_openings_area += float(oa)
        if total_openings_area > 0:
            area = area - total_openings_area
            note.append('openings_subtracted')
    # Fallback: estimate using default height 2.7 m and length from quantities or extrusion depth
    if area is None:
        default_height = 2.7
        # try to find length in quantities
        length_val = None
        if hasattr(ent, 'IsDefinedBy'):
            for rel in ent.IsDefinedBy:
                if rel.is_a('IfcRelDefinesByProperties') and rel.RelatingPropertyDefinition:
                    q = rel.RelatingPropertyDefinition
                    if q.is_a('IfcElementQuantity'):
                        for qty in q.Quantities:
                            if qty.is_a('IfcQuantityLength') and ('Length' in getattr(qty, 'Name', '') or 'WallLength' in getattr(qty, 'Name', '')):
                                length_val = getattr(qty, 'LengthValue', None)
        # try extrusion depth
        if length_val is None:
            # search representation for extruded depth
            for rep in (ent.Representation.Representations if getattr(ent, 'Representation', None) else []):
                for item in rep.Items:
                    if item.is_a('IfcExtrudedAreaSolid'):
                        length_val = getattr(item, 'Depth', None)
                        break
                if length_val is not None:
                    break
        try:
            if length_val is not None:
                length_val = float(length_val)
        except Exception:
            length_val = None
        if length_val is None:
            length_val = 5.0  # default guess
            note.append('used_default_length')
        area = default_height * length_val
        note.append('estimated_with_default_height')
        # subtract openings if available
        if hasattr(ent, 'HasOpenings') and ent.HasOpenings:
            total_openings_area = 0.0
            for rel in ent.HasOpenings:
                opening = rel.RelatedOpeningElement
                oa = compute_opening_area(opening)
                if oa is not None:
                    total_openings_area += float(oa)
            if total_openings_area > 0:
                area = area - total_openings_area
                note.append('openings_subtracted')
    # Ensure non-negative
    if area is not None and area < 0:
        area = 0.0
    results[gid] = {'area_m2': float(area) if area is not None else None, 'note': ';'.join(note) if note else None}

# Sum total
total = sum(v['area_m2'] for v in results.values() if v['area_m2'] is not None)

# Prepare result variable for the tool
result = {'per_wall': results, 'total_area_m2': float(total)}

# Commit as requested (even though we didn't modify the model)
commit()

# Recompute areas with unit conversion to meters
from math import pi

wall_guids = ["37DacD4NnAp8bYABNd$pI9", "1YYXjRkjn7ywhxb576N3m0", "1YYXjRkjn7ywhxb576N3gT"]

# Determine unit scale from project units
length_unit_factor = 1.0  # multiply file length values to get meters
area_unit_factor = 1.0
try:
    projects = ifc.by_type('IfcProject')
    if projects:
        pu = projects[0].UnitsInContext
        if pu:
            for u in pu.Units:
                try:
                    if u.is_a('IfcSIUnit') and getattr(u, 'UnitType', None) and u.UnitType == 'LENGTHUNIT':
                        prefix = getattr(u, 'Prefix', None)
                        # If prefix is MILLI, lengths are in millimetres
                        if prefix == 'MILLI':
                            length_unit_factor = 0.001
                        else:
                            length_unit_factor = 1.0
                    if u.is_a('IfcSIUnit') and getattr(u, 'UnitType', None) and u.UnitType == 'AREAUNIT':
                        # area unit factor should match square of length factor, but check prefix too
                        prefix = getattr(u, 'Prefix', None)
                        if prefix == 'MILLI':
                            area_unit_factor = 0.001 * 0.001
                        else:
                            area_unit_factor = 1.0
                except Exception:
                    continue
except Exception:
    pass

# helper functions

def get_entity_by_guid(guid):
    ent = ifc.by_guid(guid)
    if ent:
        return ent
    for e in ifc.by_type('IfcProduct'):
        if getattr(e, 'GlobalId', None) == guid:
            return e
    return None


def swept_area_of_profile(profile):
    if profile is None:
        return None
    if profile.is_a('IfcRectangleProfileDef'):
        x = getattr(profile, 'XDimension', None)
        y = getattr(profile, 'YDimension', None)
        if x is not None and y is not None:
            # X and Y are lengths in file units
            return float(x) * float(y) * (length_unit_factor ** 2)
    if profile.is_a('IfcCircleProfileDef'):
        r = getattr(profile, 'Radius', None)
        if r is not None:
            return pi * float(r) * float(r) * (length_unit_factor ** 2)
    return None


def compute_opening_area(opening):
    if opening is None:
        return None
    # Check quantities first
    if hasattr(opening, 'IsDefinedBy') and opening.IsDefinedBy:
        for rel in opening.IsDefinedBy:
            if rel.is_a('IfcRelDefinesByProperties') and rel.RelatingPropertyDefinition:
                q = rel.RelatingPropertyDefinition
                if q.is_a('IfcElementQuantity'):
                    for qty in q.Quantities:
                        if qty.is_a('IfcQuantityArea'):
                            return float(qty.AreaValue) * area_unit_factor
    # Look for extruded area solids
    if hasattr(opening, 'Representation') and opening.Representation:
        for rep in opening.Representation.Representations:
            for item in rep.Items:
                if item.is_a('IfcExtrudedAreaSolid'):
                    profile = item.SweptArea
                    prof_area = swept_area_of_profile(profile)
                    if prof_area is not None:
                        return float(prof_area)
    return None


def get_area_from_quantities(wall):
    if hasattr(wall, 'IsDefinedBy') and wall.IsDefinedBy:
        for rel in wall.IsDefinedBy:
            if rel.is_a('IfcRelDefinesByProperties') and rel.RelatingPropertyDefinition:
                prop = rel.RelatingPropertyDefinition
                if prop.is_a('IfcElementQuantity'):
                    for qty in prop.Quantities:
                        if qty.is_a('IfcQuantityArea'):
                            name = getattr(qty, 'Name', '').lower()
                            if 'net' in name or 'inner' in name or 'interior' in name or 'surface' in name or name in ('area', 'areavalue'):
                                return float(qty.AreaValue) * area_unit_factor
    return None


def compute_wall_area(wall):
    note = []
    # 1) Try quantity area
    area = get_area_from_quantities(wall)
    if area is not None:
        note.append('from_IFC_quantities')
    # 2) Try extruded area (height * depth)
    if area is None and hasattr(wall, 'Representation') and wall.Representation:
        for rep in wall.Representation.Representations:
            for item in rep.Items:
                if item.is_a('IfcExtrudedAreaSolid'):
                    profile = item.SweptArea
                    depth = getattr(item, 'Depth', None)
                    prof_area = swept_area_of_profile(profile)
                    if prof_area is not None and depth is not None:
                        # for extruded solids, prof_area is in m2 already due to swept_area_of_profile
                        depth_m = float(depth) * length_unit_factor
                        # area of wall surface (inner surface) is height * length; we need to identify which profile dimension is height
                        # If profile is rectangle, assume YDimension is height and Depth is length
                        height = None
                        if profile.is_a('IfcRectangleProfileDef'):
                            height = getattr(profile, 'YDimension', None)
                        if height is not None:
                            height_m = float(height) * length_unit_factor
                            length_m = depth_m
                            area = height_m * length_m
                            note.append('from_extruded_profile')
                            break
            if area is not None:
                break
    # 3) Fallback to default height and length from quantities or extrusion depth
    if area is None:
        default_height_m = 2.7
        length_val = None
        # try quantities
        if hasattr(wall, 'IsDefinedBy') and wall.IsDefinedBy:
            for rel in wall.IsDefinedBy:
