def rect_profile_dims(profile):
    # return (dim_long, dim_thin) or None
    xd = getattr(profile, 'XDim', None)
    yd = getattr(profile, 'YDim', None)
    if xd is None or yd is None:
        return None
    # assume larger is length
    if xd >= yd:
        return (float(xd), float(yd))
    else:
        return (float(yd), float(xd))


def arbitrary_profile_length(profile):
    # try to compute bounding box width of outer curve
    curve = getattr(profile, 'OuterCurve', None)
    if curve is None:
        return None
    pts = None
    if curve.is_a('IfcPolyline'):
        pts = []
        for p in curve.Points:
            coords = getattr(p, 'Coordinates', None)
            if coords:
                pts.append([float(c) for c in coords])
    if not pts:
        return None
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    # take max span as length
    spanx = max(xs)-min(xs)
    spany = max(ys)-min(ys)
    return max(spanx, spany)


