    # fallback: try if profile is IfcCircleProfileDef (unlikely)
    if profile.is_a('IfcCircleProfileDef'):
        r = getattr(profile, 'Radius', None)
        if r is not None:
            circ_length = 2*3.141592653589793*r
            return (circ_length, depth)
    return None


def resolve_mapped_item(item):
