            xs = [c[0] for c in coords if len(c)>=1]
            ys = [c[1] for c in coords if len(c)>=2]
            zs = [c[2] for c in coords if len(c)>=3]
            if not zs:
                height = 3.0
            else:
                height = max(zs) - min(zs)
                if abs(height) < 1e-6:
                    height = 3.0
            if xs and ys:
                dx = max(xs) - min(xs)
                dy = max(ys) - min(ys)
                # wall length approx as larger extent in plan
                length = max(dx, dy)
                if length <= 0:
                    # fallback diagonal
                    length = sqrt(dx*dx + dy*dy) if dx or dy else 0.0
                if length <= 0:
                    # cannot compute length, fallback to 1.0
                    length = 1.0
                area_val = height * length
                reason = 'bbox_estimate'
            else:
                # no XY coords
                area_val = 3.0 * 1.0
                reason = 'default_assumption'
        else:
            # no geometry at all
            area_val = 3.0 * 1.0
            reason = 'default_assumption_no_geometry'
    # store
    areas[gid] = {"area": float(area_val) if area_val is not None else None, "method": reason}

# sum up areas, ignoring None
total = sum(v['area'] for v in areas.values() if v['area'] is not None)

# prepare result
result = {"requested_gids": gids, "areas_per_wall": areas, "total_outer_gross_wall_area_m2": float(total)}

