    commit()
except Exception:
    pass

import math

# Helper functions

def polygon_area_2d(points):
    # points: list of (x,y)
    if len(points) < 3:
        return 0.0
    area = 0.0
    n = len(points)
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i + 1) % n]
        area += x1 * y2 - x2 * y1
    return abs(area) * 0.5


def polygon_area_3d(points):
    # Newell's method for polygon area in 3D
    if len(points) < 3:
        return 0.0
    nx = ny = nz = 0.0
    n = len(points)
    for i in range(n):
        x1, y1, z1 = points[i]
        x2, y2, z2 = points[(i + 1) % n]
        nx += (y1 - y2) * (z1 + z2)
        ny += (z1 - z2) * (x1 + x2)
        nz += (x1 - x2) * (y1 + y2)
    norm = math.sqrt(nx * nx + ny * ny + nz * nz)
    return 0.5 * norm


def coords_from_ifc_point(pt):
    coords = list(pt.Coordinates)
    return coords


def area_of_profile(profile):
    # Returns area in model units^2 (assumed meters)
    if profile is None:
        return 0.0
    t = profile.is_a()
    if t == 'IfcRectangleProfileDef':
        x = getattr(profile, 'XDim', 0.0) or 0.0
        y = getattr(profile, 'YDim', 0.0) or 0.0
        return float(x) * float(y)
    if t == 'IfcCircleProfileDef':
        r = getattr(profile, 'Radius', 0.0) or 0.0
        return math.pi * float(r) * float(r)
    if t == 'IfcEllipseProfileDef':
        a = getattr(profile, 'SemiAxis1', 0.0) or 0.0
        b = getattr(profile, 'SemiAxis2', 0.0) or 0.0
        return math.pi * float(a) * float(b)
    if t == 'IfcArbitraryClosedProfileDef':
        outer = getattr(profile, 'OuterCurve', None)
        if outer and outer.is_a('IfcPolyline'):
            pts = []
            for p in outer.Points:
                c = coords_from_ifc_point(p)
                # coordinates may be 2D; take first two
                if len(c) >= 2:
                    pts.append((float(c[0]), float(c[1])))
                elif len(c) == 1:
                    pts.append((float(c[0]), 0.0))
            return polygon_area_2d(pts)
    # Fallback: for other profile types, try to detect points in profile
    return 0.0


def area_of_faceted_brep(brep):
    # brep.Outer is IfcClosedShell
    total = 0.0
    outer = getattr(brep, 'Outer', None)
    if outer is None:
        return 0.0
    faces = getattr(outer, 'CfsFaces', [])
    for f in faces:
        # f is IfcFace
        face_area = 0.0
        for bound in getattr(f, 'Bounds', []):
            # FaceBound
            orientation = getattr(bound, 'Orientation', True)
            loop = getattr(bound, 'Bound', None)
            if loop is None:
                continue
            if loop.is_a('IfcPolyLoop'):
                poly_pts = []
                for p in loop.Polygon:
                    c = coords_from_ifc_point(p)
                    # Ensure 3D
                    if len(c) == 2:
                        poly_pts.append((float(c[0]), float(c[1]), 0.0))
                    else:
                        poly_pts.append((float(c[0]), float(c[1]), float(c[2]) if len(c) > 2 else 0.0))
                a = polygon_area_3d(poly_pts)
                face_area += a if orientation else -a
            else:
                # If bound.Bound is IfcIndexedPolygonalFace or others, try to handle IfcPolyLoop only
                pass
        total += abs(face_area)
    return total


opening_areas = []

# Iterate IfcOpeningElement entities
for opening in ifc.by_type('IfcOpeningElement'):
    area = 0.0
    rep = getattr(opening, 'Representation', None)
    processed = False
    if rep:
        for rep_item in getattr(rep, 'Representations', []) or []:
            for item in getattr(rep_item, 'Items', []) or []:
                t = item.is_a()
                if t == 'IfcExtrudedAreaSolid':
                    profile = getattr(item, 'SweptArea', None)
                    a_profile = area_of_profile(profile)
                    # Use profile area (cross-sectional area) as opening area
                    if a_profile and a_profile > 0.0:
                        area = float(a_profile)
                        processed = True
                        break
                elif t in ('IfcFacetedBrep', 'IfcFacetedBrepWithVoids', 'IfcAdvancedBrep', 'IfcBrep'):
                    a = area_of_faceted_brep(item)
                    if a and a > 0.0:
                        # assume largest face area approximates the opening; use a directly
                        area = float(a)
                        processed = True
                        break
                elif t == 'IfcShapeRepresentation':
                    # sometimes Items nested differently; try inner items if present
                    for sub in getattr(item, 'Items', []) or []:
                        st = sub.is_a()
                        if st == 'IfcExtrudedAreaSolid':
                            profile = getattr(sub, 'SweptArea', None)
                            a_profile = area_of_profile(profile)
                            if a_profile and a_profile > 0.0:
                                area = float(a_profile)
                                processed = True
                                break
            if processed:
                break
    # If not processed, look for geometry as direct attribute (fallback)
    if not processed:
        # Try to inspect product representations on related elements
        pass
    # If still zero, skip
    if area and area > 0.0:
        # area is in model units^2; assume meters
        opening_areas.append({'ifc_id': opening.id(), 'global_id': getattr(opening, 'GlobalId', None), 'area_m2': float(area)})

# Filter openings > 2 sqm
openings_over_2 = [o for o in opening_areas if o['area_m2'] > 2.0]

total_over_2 = sum(o['area_m2'] for o in openings_over_2)

# Prepare raw text response
lines = []
lines.append(f"Found {len(opening_areas)} openings with computed area; {len(openings_over_2)} larger than 2.0 m^2.")
for o in openings_over_2:
    lines.append(f"Ifc id #{o['ifc_id']} (GlobalId={o['global_id']}): {o['area_m2']:.4f} m^2")
lines.append(f"Total area of openings > 2.0 m^2: {total_over_2:.4f} m^2")
raw = '\n'.join(lines)

# Set result to return
result = {
    'value': float(total_over_2),
    'raw_model_response': raw,
    'openings': openings_over_2,
}

