# Helper to extract property sets for an element
def get_psets(entity):
    psets = {}
    # Some IFCs use IsDefinedBy relationships to point to IfcPropertySet
    if hasattr(entity, 'IsDefinedBy') and entity.IsDefinedBy:
        for rel in entity.IsDefinedBy:
            try:
                if rel.is_a('IfcRelDefinesByProperties'):
                    prop_def = rel.RelatingPropertyDefinition
                    if prop_def and prop_def.is_a('IfcPropertySet'):
                        for prop in prop_def.HasProperties:
                            if prop.is_a('IfcPropertySingleValue'):
                                name = str(prop.Name)
                                val = None
                                if hasattr(prop, 'NominalValue') and prop.NominalValue is not None:
                                    try:
                                        # Most nominal values expose wrappedValue
                                        val = prop.NominalValue.wrappedValue
                                    except Exception:
                                        # fallback to raw attribute
                                        try:
                                            val = prop.NominalValue
                                        except Exception:
                                            val = None
                                psets[name] = val
            except Exception:
                # defensive: skip problematic relationships
                continue
    return psets

