import math

def get_length_unit_factor(ifc):
    # Default to meters
    factor = 1.0
    try:
        project = ifc.by_type('IfcProject')
        if project:
            project = project[0]
            ucontext = getattr(project, 'UnitsInContext', None)
            if ucontext:
                units = getattr(ucontext, 'Units', [])
                for u in units:
                    try:
                        # Check common SI unit case
                        if u.is_a('IfcSIUnit'):
                            # Some IFCs store UnitType as an enum-like value
                            ut = getattr(u, 'UnitType', None)
                            if ut and (str(ut).upper().endswith('LENGTHUNIT') or 'LENGTH' in str(ut).upper()):
                                name = getattr(u, 'Name', None)
                                if name:
                                    n = str(name).upper()
                                    if 'METRE' in n or 'METER' in n:
                                        return 1.0
                                    if 'MILLI' in n:
                                        return 0.001
                                    if 'CENTI' in n:
                                        return 0.01
                                    if 'DECI' in n:
                                        return 0.1
                                    if 'MICRO' in n:
                                        return 1e-6
                                # fallback: check Prefix
                                prefix = getattr(u, 'Prefix', None)
                                if prefix:
                                    p = str(prefix).upper()
                                    if 'MILLI' in p:
                                        return 0.001
                                    if 'CENTI' in p:
                                        return 0.01
                                    if 'DECI' in p:
                                        return 0.1
                                    if 'KILO' in p:
                                        return 1000.0
                        # Conversion based units
                        if u.is_a('IfcConversionBasedUnit'):
                            # Name often contains unit name
                            name = getattr(u, 'Name', None)
                            if name:
                                n = str(name).upper()
                                if 'MILLI' in n or 'MM' in n:
                                    return 0.001
                                if 'CENTI' in n or 'CM' in n:
                                    return 0.01
                                if 'METRE' in n or 'METER' in n or 'M' == n:
                                    return 1.0
                    except Exception:
                        continue
    except Exception:
        pass
    return factor


def extract_cartesian_points(obj):
    pts = []
    visited = set()
    def rec(o):
        if o is None:
            return
        oid = getattr(o, 'id', None)
        if oid is not None:
            if oid in visited:
                return
            visited.add(oid)
        # If it's a CartesianPoint
        try:
            if o.is_a('IfcCartesianPoint'):
                coords = getattr(o, 'Coordinates', None)
                if coords:
                    pts.append(tuple(float(c) for c in coords))
                return
        except Exception:
            pass
        # If it's a CartesianPointList
        try:
            if o.is_a('IfcCartesianPointList3D'):
                coords = getattr(o, 'CoordList', None) or getattr(o, 'Coord', None)
                if coords:
                    for c in coords:
                        pts.append(tuple(float(x) for x in c))
                return
        except Exception:
            pass
        # If it's a list or tuple
        if isinstance(o, (list, tuple)):
            for e in o:
                rec(e)
            return
        # Recurse into attributes
        for attr in dir(o):
            if attr.startswith('_'):
                continue
            try:
                v = getattr(o, attr)
            except Exception:
                continue
            # Skip methods
            if callable(v):
                continue
            # Primitive types
            if isinstance(v, (int, float, str, bool)) or v is None:
                continue
            rec(v)
    rec(obj)
    return pts


def max_point_distance(pts):
    if not pts:
        return 0.0
    maxd = 0.0
    for i in range(len(pts)):
        xi, yi, zi = (pts[i] + (0.0,))[:3]
        for j in range(i+1, len(pts)):
            xj, yj, zj = (pts[j] + (0.0,))[:3]
            dx = xi - xj
            dy = yi - yj
            dz = zi - zj
            d = math.sqrt(dx*dx + dy*dy + dz*dz)
            if d > maxd:
                maxd = d
    return maxd

# Begin processing
walls = []
walls += ifc.by_type('IfcWall')
walls += ifc.by_type('IfcWallStandardCase')
unit_factor = get_length_unit_factor(ifc)

per_wall = []
total_length = 0.0
for w in walls:
    length = None
    # 1) Try IfcElementQuantity -> IfcQuantityLength
    try:
        refs = getattr(w, 'IsDefinedBy', []) or []
        for r in refs:
            try:
                if r.is_a('IfcRelDefinesByProperties'):
                    propdef = r.RelatingPropertyDefinition
                    if propdef and propdef.is_a('IfcElementQuantity'):
                        quants = getattr(propdef, 'Quantities', []) or []
                        for q in quants:
                            if q.is_a('IfcQuantityLength'):
                                val = getattr(q, 'LengthValue', None)
                                if val is None:
                                    # sometimes value stored as 'Value' or 'Length'
                                    val = getattr(q, 'Value', None) or getattr(q, 'Length', None)
                                if val is not None:
                                    length = float(val) * unit_factor
                                    break
                        if length is not None:
                            break
            except Exception:
                continue
    except Exception:
        pass
    if length is not None:
        per_wall.append((w.GlobalId if hasattr(w, 'GlobalId') else getattr(w,'Name',None), length, 'quantity'))
        total_length += length
        continue
    # 2) Try Representation -> IfcExtrudedAreaSolid Depth
    try:
        rep = getattr(w, 'Representation', None)
        if rep:
            reps = getattr(rep, 'Representations', []) or []
            for r in reps:
                items = getattr(r, 'Items', []) or []
                for it in items:
                    try:
                        if it.is_a('IfcExtrudedAreaSolid'):
                            depth = getattr(it, 'Depth', None)
                            if depth is not None:
                                length = float(depth) * unit_factor
                                break
                    except Exception:
                        continue
                if length is not None:
                    break
            # Some models place the extruded solid directly under Representation.Items
            if length is None:
                items2 = getattr(rep, 'Items', []) or []
                for it in items2:
                    try:
                        if it.is_a('IfcExtrudedAreaSolid'):
                            depth = getattr(it, 'Depth', None)
                            if depth is not None:
                                length = float(depth) * unit_factor
                                break
                    except Exception:
                        continue
    except Exception:
        pass
    if length is not None:
        per_wall.append((w.GlobalId if hasattr(w, 'GlobalId') else getattr(w,'Name',None), length, 'extrusion_depth'))
        total_length += length
        continue
    # 3) Fallback: extract cartesian points from representation and use max distance
    try:
        pts = []
        if rep:
            reps = getattr(rep, 'Representations', []) or []
            for r in reps:
                items = getattr(r, 'Items', []) or []
                for it in items:
                    pts += extract_cartesian_points(it)
            # also try rep.Items
            items2 = getattr(rep, 'Items', []) or []
            for it in items2:
                pts += extract_cartesian_points(it)
        # Also try to look at geometry of nested representations
        if not pts:
            # search all related geometry entities by walking attributes of the wall
            pts = extract_cartesian_points(w)
        if pts:
            maxd = max_point_distance(pts)
            length = float(maxd) * unit_factor
    except Exception:
        length = None
    if length is None:
        length = 0.0
        per_wall.append((w.GlobalId if hasattr(w, 'GlobalId') else getattr(w,'Name',None), length, 'unknown'))
    else:
        per_wall.append((w.GlobalId if hasattr(w, 'GlobalId') else getattr(w,'Name',None), length, 'approx'))
        total_length += length

# Prepare result
summary_lines = []
for gid, l, tag in per_wall:
    name = gid if gid else 'unnamed'
    summary_lines.append(f"{name}: {l:.6f} m ({tag})")
summary = '\n'.join(summary_lines)

# Set result
result = {
    'value': total_length,
