import math

def cartesian_point_to_tuple(p):
    # p.Coordinates may be list-like
    coords = []
    if hasattr(p, 'Coordinates'):
        coords = list(p.Coordinates)
    else:
        return None
    return tuple(float(c) for c in coords)


def polygon_area(points):
    # points: list of (x,y,...) coordinate tuples; project to 2D using first two coords
    if len(points) < 3:
        return 0.0
    pts = [(float(p[0]), float(p[1])) for p in points]
    area = 0.0
    n = len(pts)
    for i in range(n):
        x1,y1 = pts[i]
        x2,y2 = pts[(i+1)%n]
        area += x1*y2 - x2*y1
    return abs(area)/2.0


def extract_points_from_ifc_polyline(poly):
    pts = []
    if not poly:
        return pts
    if hasattr(poly, 'Points'):
        for p in poly.Points:
            t = cartesian_point_to_tuple(p)
            if t is not None:
                pts.append(t)
    return pts


def profile_area(profile):
    # Try multiple profile types
    if profile is None:
        return None
    t = profile.is_a()
    if t == 'IfcRectangleProfileDef':
        x = float(profile.XDim)
        y = float(profile.YDim)
        return x*y
    if t == 'IfcCircleProfileDef':
        r = float(profile.Radius)
        return math.pi * r * r
    if t == 'IfcEllipseProfileDef':
        a = float(profile.SemiAxis1)
        b = float(profile.SemiAxis2)
        return math.pi * a * b
    if t == 'IfcRoundedRectangleProfileDef':
        x = float(profile.XDim)
        y = float(profile.YDim)
        r = float(profile.RoundingRadius) if hasattr(profile, 'RoundingRadius') and profile.RoundingRadius is not None else 0.0
        # area = X*Y - (4 - pi)*r^2
        return x*y - (4.0 - math.pi)*(r*r)
    if t in ('IfcArbitraryClosedProfileDef', 'IfcArbitraryOpenProfileDef', 'IfcArbitraryProfileDef'):
        # Try OuterCurve
        if hasattr(profile, 'OuterCurve') and profile.OuterCurve is not None:
            curve = profile.OuterCurve
            if curve.is_a('IfcPolyline'):
                pts = extract_points_from_ifc_polyline(curve)
                return polygon_area(pts)
            # If composite curve or others, try to collect points from segments if available
            if curve.is_a('IfcCompositeCurve') and hasattr(curve, 'Segments'):
                pts = []
                for seg in curve.Segments:
                    # Each segment may have ParentCurve like IfcPolyline or IfcLine
                    if hasattr(seg, 'ParentCurve') and seg.ParentCurve is not None:
                        pc = seg.ParentCurve
                        if pc.is_a('IfcPolyline'):
                            pts.extend(extract_points_from_ifc_polyline(pc))
                if pts:
                    return polygon_area(pts)
        # No curve understood
        return None
    # Fallback: If profile has 'ProfileType' and maybe OuterCurve
    if hasattr(profile, 'OuterCurve'):
        curve = profile.OuterCurve
        if curve is not None and curve.is_a('IfcPolyline'):
            pts = extract_points_from_ifc_polyline(curve)
            return polygon_area(pts)
    return None


def compute_area_from_rep_item(item):
    # Handle IfcExtrudedAreaSolid
    if item is None:
        return None
    itype = item.is_a()
    if itype == 'IfcExtrudedAreaSolid':
        swept = item.SweptArea
        return profile_area(swept)
    # Sometimes representation items are profiles directly (rare)
    if itype.endswith('ProfileDef'):
        return profile_area(item)
    # If item is IfcFaceBasedSurfaceModel or BRep: try to find a planar face and compute projected area
    if itype in ('IfcFacetedBrep','IfcFaceBasedSurfaceModel'):
        # Try to compute area by summing areas of outer faces projected to XY
        # This is heuristic and may be incorrect; skip for now
        return None
    # If item is IfcSweptDiskSolid etc, skip
    return None

