import math

# 'ifc' variable is provided by the execution environment per the tool description.

def get_cartesian_coords(point):
    # point.Coordinates is a list of floats
    return tuple(float(c) for c in point.Coordinates)

def polygon_area_2d(points):
    # points: list of (x,y) tuples
    area = 0.0
    n = len(points)
    if n < 3:
        return 0.0
    for i in range(n):
        x1,y1 = points[i]
        x2,y2 = points[(i+1) % n]
        area += x1*y2 - x2*y1
    return 0.5 * abs(area)

def tri_tetra_volume(a, b, c):
    # returns scalar triple product dot(a, cross(b, c)) / 6
    cross = (b[1]*c[2] - b[2]*c[1],
             b[2]*c[0] - b[0]*c[2],
             b[0]*c[1] - b[1]*c[0])
    dot = a[0]*cross[0] + a[1]*cross[1] + a[2]*cross[2]
    return dot / 6.0


def polyhedron_volume_from_closed_shell(shell):
    # shell should be IfcClosedShell; compute volume by summing tetra volumes from origin
    # Try to access faces via common attribute names
    faces = None
    for attr in ("CfsFaces", "Faces", "Bound"):
        if hasattr(shell, attr):
            faces = getattr(shell, attr)
            break
    if faces is None:
        # try iterating attributes for lists of IfcFace
        faces = []
        for v in shell.__dict__.values():
            if isinstance(v, (list, tuple)):
                faces.extend([x for x in v if hasattr(x, 'Bounds')])
    total = 0.0
    for face in faces:
        # Each face has Bounds; we take the outer bound (IfcFaceOuterBound)
        bounds = getattr(face, 'Bounds', [])
        for b in bounds:
            loop = getattr(b, 'Bound', None)
            if loop is None:
                continue
            # If poly loop
            if loop.is_a('IfcPolyLoop'):
                poly = [get_cartesian_coords(p) for p in loop.Polygon]
                # triangulate polygon as fan about poly[0]
                if len(poly) < 3:
                    continue
                v0 = poly[0]
                for i in range(1, len(poly)-1):
                    vi = poly[i]
                    vj = poly[i+1]
                    total += tri_tetra_volume(v0, vi, vj)
            else:
                # other loop types not handled
                continue
    return abs(total)


def volume_of_extruded_area_solid(item):
    swept = getattr(item, 'SweptArea', None)
    if swept is None:
        return 0.0
    area = 0.0
    # Handle common swept area types
    if swept.is_a('IfcArbitraryClosedProfileDef'):
        outer = getattr(swept, 'OuterCurve', None)
        if outer is None:
            return 0.0
        if outer.is_a('IfcPolyline'):
            poly = [get_cartesian_coords(p) for p in outer.Points] if hasattr(outer, 'Points') else [get_cartesian_coords(p) for p in outer.Coordinates]
            # poly points may be 3D; project to plane: use first two coords
            poly2d = [(p[0], p[1]) for p in poly]
            area = polygon_area_2d(poly2d)
        else:
            # unsupported curve
            return 0.0
    elif swept.is_a('IfcRectangleProfileDef'):
        x = float(getattr(swept, 'XDim', 0.0))
        y = float(getattr(swept, 'YDim', 0.0))
        area = abs(x * y)
    elif swept.is_a('IfcCircleProfileDef'):
        r = float(getattr(swept, 'Radius', 0.0))
        area = math.pi * r * r
    else:
        # other profile types not handled
        return 0.0

    depth = float(getattr(item, 'Depth', 0.0))
    return abs(area * depth)


def volume_from_representation_item(item):
    # Handle several item types
    if item.is_a('IfcExtrudedAreaSolid'):
        return volume_of_extruded_area_solid(item)
    if item.is_a('IfcFacetedBrep'):
        shell = getattr(item, 'Outer', None)
        if shell is None:
            return 0.0
        return polyhedron_volume_from_closed_shell(shell)
    if item.is_a('IfcAdvancedBrep'):
        # AdvancedBrep has 'Outer' which may be a brep or shell
        outer = getattr(item, 'Outer', None)
        if outer is None:
            return 0.0
        # try to find closed shell inside
        if outer.is_a('IfcClosedShell'):
            return polyhedron_volume_from_closed_shell(outer)
        # If it's a shell container, attempt to find shells
        for attr in ('Outer', 'OuterShell', 'Shells'):
            if hasattr(item, attr):
                val = getattr(item, attr)
                if val is None:
                    continue
        return 0.0
    # Not handled types (IfcBooleanResult, IfcSolidModel etc.) -> skip
    return 0.0

