                if roelist:
                    if isinstance(roelist, (list, tuple)):
                        openings.extend(roelist)
            else:
                openings.append(roe)

    total_volume = 0.0
    detail_msgs = []
    for opening in openings:
        vol_opening = 0.0
        rep = getattr(opening, 'Representation', None)
        if rep is None:
            detail_msgs.append(f"Opening {opening.GlobalId}: no Representation")
            continue
        reps = getattr(rep, 'Representations', [])
        for r in reps:
