import math
# ifc is already loaded by the tool as variable `ifc`
# We'll compute net wall volume by trying quantities first, then falling back to geometry extraction

def get_point_coords(pt):
    # IfcCartesianPoint.Coordinates is iterable
    coords = list(pt.Coordinates)
    return [float(c) for c in coords]

def dot(u,v):
    return u[0]*v[0] + u[1]*v[1] + u[2]*v[2]

def cross(u,v):
    return [u[1]*v[2]-u[2]*v[1], u[2]*v[0]-u[0]*v[2], u[0]*v[1]-u[1]*v[0]]

def tetra_signed_volume(a,b,c):
    # volume of tetrahedron formed by points a,b,c and origin = dot(a, cross(b,c))/6
    return dot(a, cross(b,c)) / 6.0

def polygon_area_xy(points):
    # points: list of (x,y,...) -> project to XY and compute shoelace
    if len(points) < 3:
        return 0.0
    s = 0.0
    for i in range(len(points)):
        x1 = points[i][0]
        y1 = points[i][1]
        x2 = points[(i+1)%len(points)][0]
        y2 = points[(i+1)%len(points)][1]
        s += x1*y2 - x2*y1
    return abs(s) / 2.0


total_volume = 0.0
walls = []
walls.extend(ifc.by_type('IfcWall'))
walls.extend(ifc.by_type('IfcWallStandardCase'))

for wall in walls:
    counted = False
    # 1) try element quantities (IfcElementQuantity)
    if hasattr(wall, 'IsDefinedBy') and wall.IsDefinedBy:
        for rel in wall.IsDefinedBy:
            try:
                propdef = rel.RelatingPropertyDefinition
            except Exception:
                propdef = None
            if not propdef:
                continue
            # IfcElementQuantity
            if propdef.is_a('IfcElementQuantity'):
                for q in propdef.Quantities:
                    if q.is_a('IfcQuantityVolume'):
                        # different versions may name attribute VolumeValue or Value
                        val = None
                        if hasattr(q, 'VolumeValue'):
                            val = q.VolumeValue
                        elif hasattr(q, 'Value'):
                            val = q.Value
                        if val is not None:
                            try:
                                total_volume += float(val)
                                counted = True
                                break
                            except Exception:
                                pass
                if counted:
                    break
            # Sometimes people put volume in IfcPropertySet as IfcPropertySingleValue
            if propdef.is_a('IfcPropertySet') or propdef.is_a('IfcPropertySetDefinition'):
                # iterate properties
                props = []
                if hasattr(propdef, 'HasProperties') and propdef.HasProperties:
                    props = propdef.HasProperties
                for p in props:
                    if p.is_a('IfcPropertySingleValue') and p.Name:
                        name = p.Name.lower()
                        if 'volume' in name:
                            val = None
                            try:
                                if hasattr(p, 'NominalValue') and p.NominalValue is not None:
                                    # NominalValue might be an IfcReal, IfcLengthMeasure etc
                                    nv = p.NominalValue
                                    if hasattr(nv, 'wrappedValue'):
                                        val = nv.wrappedValue
                                    elif hasattr(nv, 'value'):
                                        val = nv.value
                                    elif hasattr(nv, 'Value'):
                                        val = nv.Value
                                    else:
                                        # sometimes direct
                                        val = nv
                            except Exception:
                                val = None
                            if val is not None:
                                try:
                                    total_volume += float(val)
                                    counted = True
                                    break
                                except Exception:
                                    pass
                if counted:
                    break
    if counted:
        continue

    # 2) try geometric representations
    try:
        rep = wall.Representation
    except Exception:
        rep = None
    if not rep:
        continue
    # iterate representation items
    local_volume = 0.0
    for representation in rep.Representations:
        for item in representation.Items:
            # Extruded area solids
            if item.is_a('IfcExtrudedAreaSolid'):
                depth = float(item.Depth)
                area = 0.0
                profile = item.SweptArea
                if profile is None:
                    continue
                if profile.is_a('IfcRectangleProfileDef'):
                    # XDim, YDim
                    try:
                        area = float(profile.XDim) * float(profile.YDim)
                    except Exception:
                        area = 0.0
                elif profile.is_a('IfcCircleProfileDef'):
                    try:
                        r = float(profile.Radius)
                        area = math.pi * r * r
                    except Exception:
                        area = 0.0
                elif profile.is_a('IfcIShapeProfileDef'):
                    try:
                        D = float(profile.Depth)
                        BF = float(profile.FlangeWidth)
                        TF = float(profile.FlangeThickness)
                        TW = float(profile.WebThickness)
                        # approximate I-shape area
                        area = 2.0 * BF * TF + (D - 2.0*TF) * TW
                    except Exception:
                        area = 0.0
                elif profile.is_a('IfcArbitraryClosedProfileDef'):
                    # try to get OuterCurve which may be IfcPolyline or IfcCompositeCurve
                    oc = profile.OuterCurve
                    pts = []
                    if oc is None:
                        area = 0.0
                    else:
                        if oc.is_a('IfcPolyline'):
                            for p in oc.Points:
                                pts.append(get_point_coords(p))
                            area = polygon_area_xy(pts)
                        else:
                            # fallback: if profile has Coordinates attribute with points
                            if hasattr(profile, 'Points') and profile.Points:
                                for p in profile.Points:
                                    pts.append(get_point_coords(p))
                                area = polygon_area_xy(pts)
                            else:
                                area = 0.0
                else:
                    # other profile types: try if it has OuterCurve or Points
                    pts = []
                    if hasattr(profile, 'OuterCurve') and profile.OuterCurve is not None and profile.OuterCurve.is_a('IfcPolyline'):
                        for p in profile.OuterCurve.Points:
                            pts.append(get_point_coords(p))
                        area = polygon_area_xy(pts)
                vol = area * depth
                local_volume += vol
            elif item.is_a('IfcFacetedBrep'):
                # compute volume from closed shell by triangulating face loops
                brep = item
                outer = brep.Outer
                if outer is None:
                    continue
                shell = outer
                mesh_vol = 0.0
                for face in shell.CfsFaces:
                    # each face has Bounds (IfcFaceBound list), first one is outer loop
                    if not face.Bounds:
                        continue
                    # take the first bound as main polygon
                    bound = face.Bounds[0]
                    loop = bound.Bound
                    # IfcPolyLoop -> Polygon attribute: list of IfcCartesianPoint
                    if loop.is_a('IfcPolyLoop') and loop.Polygon:
                        pts = [get_point_coords(p) for p in loop.Polygon]
                    else:
                        # try other types
                        pts = []
                    if len(pts) < 3:
                        continue
                    p0 = pts[0]
                    for i in range(1, len(pts)-1):
                        p1 = pts[i]
                        p2 = pts[i+1]
                        mesh_vol += tetra_signed_volume(p0, p1, p2)
                local_volume += abs(mesh_vol)
            elif item.is_a('IfcTriangulatedFaceSet'):
                # has Coordinates (IfcCartesianPointList3D?) and CoordIndex
                try:
                    coords = []
                    # some versions: item.Coordinates.Coordinates is list of points
                    if hasattr(item, 'Coordinates'):
                        coord_container = item.Coordinates
                        if hasattr(coord_container, 'Coordinates'):
                            for p in coord_container.Coordinates:
                                coords.append(get_point_coords(p))
                    # triangles indices in item.CoordIndex
                    idx = getattr(item, 'CoordIndex', None)
                    if idx:
                        mesh_vol = 0.0
                        for tri in idx:
                            if len(tri) >= 3:
                                # tri may have sentinel -1 at end; take first three
                                a = coords[int(tri[0])]
                                b = coords[int(tri[1])]
                                c = coords[int(tri[2])]
                                mesh_vol += tetra_signed_volume(a,b,c)
                        local_volume += abs(mesh_vol)
                except Exception:
                    pass
            # else: other item types not handled
    total_volume += local_volume

# final absolute
if total_volume < 0:
    total_volume = abs(total_volume)

# prepare result
result = {'value': total_volume, 'raw_model_response': f'Computed net wall volume for {len(walls)} walls.'}
# save (even though we didn't modify)
commit()

# Python code executed with ifcopenshell available as `ifc`
# The goal: compute net room volume (m3) of the non-rectangular room.
# Strategy:
# 1. Inspect IfcSpace entities and try to read quantity IfcQuantityVolume from defined quantities.
# 2. If not available, attempt to compute volume from geometric representations: IfcExtrudedAreaSolid, IfcFacetedBrep/IfcClosedShell, IfcAdvancedBrep, or IfcShellBasedSurfaceModel.
# 3. Identify a non-rectangular room by checking swept profile vertices (polygon with !=4 corners). If none identified, pick the largest space by computed volume.

import math

def polygon_area_2d(points):
    # points: list of (x,y)
    area = 0.0
    n = len(points)
    if n < 3:
        return 0.0
    for i in range(n):
        x1,y1 = points[i][0], points[i][1]
        x2,y2 = points[(i+1)%n][0], points[(i+1)%n][1]
        area += x1*y2 - x2*y1
    return abs(area)/2.0


def get_cartesian_point_coords(cp):
    # cp is IfcCartesianPoint
    # attribute Coordinates is a list
    try:
        return tuple(float(v) for v in cp.Coordinates)
    except Exception:
        return None


def extract_poly_points_from_ifc_polyline(polyline):
    pts = []
    try:
        for p in polyline.Points:
            c = get_cartesian_point_coords(p)
            if c is not None:
                pts.append(c)
    except Exception:
        pass
    return pts


def compute_volume_from_extruded_area(item):
    # item is IfcExtrudedAreaSolid
    try:
        depth = float(item.Depth)
    except Exception:
        return None
    # SweptArea could be various profile defs
    sa = item.SweptArea
    area = None
    try:
        t = sa.is_a
    except Exception:
        t = None
    if sa is None:
        return None
    # Rectangle
    if sa.is_a('IfcRectangleProfileDef'):
        try:
            area = float(sa.XDim) * float(sa.YDim)
        except Exception:
            area = None
    elif sa.is_a('IfcCircleProfileDef'):
        try:
            r = float(sa.Radius)
            area = math.pi * r * r
        except Exception:
            area = None
    elif sa.is_a('IfcArbitraryClosedProfileDef'):
        # OuterCurve could be IfcPolyline
        outer = getattr(sa, 'OuterCurve', None)
        if outer is not None and outer.is_a('IfcPolyline'):
            pts = extract_poly_points_from_ifc_polyline(outer)
            # project to 2D - use first two coordinates
            if len(pts) >= 3:
                pts2 = [(p[0], p[1]) for p in pts]
                area = polygon_area_2d(pts2)
    # fallback: if item has SweptArea with ProfileType and dimensions in attributes
    if area is None:
        # try profile parameters
        try:
            if hasattr(sa, 'ProfileType') and str(sa.ProfileType).upper() == 'AREA':
                # unknown; skip
                area = None
        except Exception:
            area = None
    if area is None:
        return None
    return abs(area * depth)


def compute_volume_from_closed_shell(closed_shell):
    # closed_shell is IfcClosedShell with list of faces
    # We'll sum volumes of tetrahedrons formed by triangles fan from first vertex of each face to origin
    total = 0.0
    try:
        faces = list(closed_shell.CfsFaces)
    except Exception:
        try:
            faces = list(closed_shell[0])
        except Exception:
            faces = []
    for face in faces:
        # face is IfcFace, get bounds -> IfcFaceOuterBound -> Bound -> IfcPolyLoop or IfcPolyline
        loops = getattr(face, 'Bounds', [])
        for b in loops:
            # b.Bound is IfcPolyLoop or IfcCartesianPointList3D maybe
            bound = getattr(b, 'Bound', None)
            poly_pts = []
            if bound is None:
                continue
            if bound.is_a('IfcPolyLoop'):
                # bound.Polygon is list of IfcCartesianPoint
                try:
                    for p in bound.Polygon:
                        c = get_cartesian_point_coords(p)
                        if c is not None:
                            poly_pts.append(c)
                except Exception:
                    pass
            elif bound.is_a('IfcPolyLoop') or bound.is_a('IfcCartesianPointList3D'):
                # duplicate check
                try:
                    for p in bound.Polygon:
                        c = get_cartesian_point_coords(p)
                        if c is not None:
                            poly_pts.append(c)
                except Exception:
                    pass
            else:
                # If bound is an IfcIndexedPolygonalFace or other, try to access Decomposed geometry
                try:
                    # try IfcPolyline
                    if hasattr(bound, 'Points'):
                        for p in bound.Points:
                            c = get_cartesian_point_coords(p)
                            if c is not None:
                                poly_pts.append(c)
                except Exception:
                    pass
            if len(poly_pts) < 3:
                continue
            # triangulate fan from first vertex
            v0 = poly_pts[0]
            for i in range(1, len(poly_pts)-1):
                v1 = poly_pts[i]
                v2 = poly_pts[i+1]
                # compute tetra volume with origin
                # scalar triple product: dot(v0, cross(v1, v2)) / 6
                ax,ay,az = v0
                bx,by,bz = v1
                cx,cy,cz = v2
                # cross v1 x v2
                cross_x = by*cz - bz*cy
                cross_y = bz*cx - bx*cz
                cross_z = bx*cy - by*cx
                dot = ax*cross_x + ay*cross_y + az*cross_z
                total += dot/6.0
    return abs(total)


def compute_space_volume(space):
    # 1. Check if quantities attached
    try:
        for rel in getattr(space, 'IsDefinedBy', []) or []:
            if rel.is_a('IfcRelDefinesByProperties'):
                prop = rel.RelatingPropertyDefinition
                if prop is None:
                    continue
