# Calculate net volume of all IfcSlab elements
# The IFC model is provided as `ifc`. commit() writes back to the same file.
# Result should be set to a variable `result`.

def try_get_volume_from_quantities(slab):
    # Search IsDefinedBy -> IfcElementQuantity -> IfcQuantityVolume
    vols = []
    for rel in getattr(slab, 'IsDefinedBy', []) or []:
        try:
            if rel.is_a('IfcRelDefinesByProperties'):
                propdef = rel.RelatingPropertyDefinition
                if propdef and propdef.is_a('IfcElementQuantity'):
                    for q in getattr(propdef, 'Quantities', []) or []:
                        try:
                            if q.is_a('IfcQuantityVolume'):
                                val = None
                                if hasattr(q, 'VolumeValue'):
                                    val = q.VolumeValue
                                elif hasattr(q, 'Value'):
                                    val = q.Value
                                if val is not None:
                                    vols.append(float(val))
                        except Exception:
                            continue
        except Exception:
            continue
    if vols:
        # choose the first or sum? take the sum of volume quantities for safety
        return sum(vols)
    return None


def polygon_area(points):
    # points: list of (x,y) tuples
    if len(points) < 3:
        return 0.0
    area = 0.0
    for i in range(len(points)):
        x1, y1 = points[i]
        x2, y2 = points[(i+1) % len(points)]
        area += x1 * y2 - x2 * y1
    return abs(area) / 2.0


def try_get_volume_from_geometry(slab):
    # Attempt to parse simple swept area solids (IfcExtrudedAreaSolid) from the representation
    try:
        rep = slab.Representation
        if not rep:
            return None
        for rep_item in getattr(rep, 'Representations', []) or []:
            for item in getattr(rep_item, 'Items', []) or []:
                try:
                    if item.is_a('IfcExtrudedAreaSolid'):
                        depth = getattr(item, 'Depth', None)
                        swept = getattr(item, 'SweptArea', None)
                        if depth is None or swept is None:
                            continue
                        area = None
                        if swept.is_a('IfcRectangleProfileDef'):
                            x = getattr(swept, 'XDim', None)
                            y = getattr(swept, 'YDim', None)
                            if x is not None and y is not None:
                                area = float(x) * float(y)
                        elif swept.is_a('IfcCircleProfileDef'):
                            r = getattr(swept, 'Radius', None)
                            if r is not None:
                                area = 3.141592653589793 * float(r) ** 2
                        elif swept.is_a('IfcArbitraryClosedProfileDef'):
                            curve = getattr(swept, 'OuterCurve', None)
                            if curve and curve.is_a('IfcPolyline'):
                                pts = []
                                for p in getattr(curve, 'Points', []) or []:
                                    coords = getattr(p, 'Coordinates', None)
                                    if coords and len(coords) >= 2:
                                        pts.append((float(coords[0]), float(coords[1])))
                                if pts:
                                    area = polygon_area(pts)
                        # If area computed, multiply by depth
                        if area is not None:
                            return float(area) * float(depth)
                    # Some representations may directly have IfcFaceBasedSurfaceModel or similar; skip complex types
                except Exception:
                    continue
    except Exception:
        return None
    return None


slabs = ifc.by_type('IfcSlab')
total_vol = 0.0
details = []
for slab in slabs:
    vol = try_get_volume_from_quantities(slab)
    source = 'quantity' if vol is not None else None
    if vol is None:
        vol = try_get_volume_from_geometry(slab)
        source = 'geometry' if vol is not None else None
    if vol is None:
        vol = 0.0
        source = 'missing'
    total_vol += float(vol)
    details.append({'GlobalId': getattr(slab, 'GlobalId', None), 'Name': getattr(slab, 'Name', None), 'volume': float(vol), 'source': source})

# Prepare result
