import math

def coord_dist(a, b):
    return math.sqrt((a[0]-b[0])**2 + (a[1]-b[1])**2)

perimeters = {}

# Helper to get numeric value from IfcValue types
def get_numeric_value(prop):
    try:
        val = prop.NominalValue.wrappedValue
    except Exception:
        try:
            val = prop.NominalValue
        except Exception:
            try:
                val = float(prop.wrappedValue)
            except Exception:
                val = None
    try:
        return float(val)
    except Exception:
        return None

# Try to extract perimeter from property sets
for space in ifc.by_type('IfcSpace'):
    key = f"{getattr(space, 'GlobalId', '')} | {getattr(space, 'Name', '')}"
    perim = None
    # Check IsDefinedBy property sets
    try:
        for rel in getattr(space, 'IsDefinedBy', []) or []:
            if rel.is_a('IfcRelDefinesByProperties'):
                pset = rel.RelatingPropertyDefinition
                if pset and pset.is_a('IfcPropertySet'):
                    for prop in getattr(pset, 'HasProperties', []) or []:
                        if prop.is_a('IfcPropertySingleValue'):
                            name = getattr(prop, 'Name', '')
                            if name and 'perimeter' in name.lower():
                                val = get_numeric_value(prop)
                                if val is not None:
                                    perim = float(val)
                                    break
            if perim is not None:
                break
    except Exception:
        pass

    # If found from properties, record
    if perim is not None:
        perimeters[key] = perim
        continue

    # Otherwise, try to compute from geometry representations
    # Search for common swept solids (IfcExtrudedAreaSolid) and profile defs
    pts = []
    polyline_points = None
    try:
        rep = getattr(space, 'Representation', None)
        if rep:
            for r in getattr(rep, 'Representations', []) or []:
                for item in getattr(r, 'Items', []) or []:
                    # If it's an ExtrudedAreaSolid, inspect SweptArea profile
                    try:
                        if item.is_a('IfcExtrudedAreaSolid'):
                            swept = getattr(item, 'SweptArea', None)
                            if swept is not None:
                                # If profile has ProfileOuterCurve (IfcArbitraryClosedProfileDef)
                                poc = getattr(swept, 'OuterCurve', None)
                                if poc is None:
                                    # Some schemas use ProfileDef.ProfileOuterCurve
                                    poc = getattr(swept, 'ProfileOuterCurve', None)
                                if poc is not None and poc.is_a('IfcPolyline'):
                                    # collect XY points
                                    poly = [tuple(p.Coordinates) for p in getattr(poc, 'Points', [])]
                                    if poly:
                                        polyline_points = poly
                                        break
                                # Rectangle or circle profile types
                                if swept.is_a('IfcRectangleProfileDef'):
                                    x = getattr(swept, 'XDim', None)
                                    y = getattr(swept, 'YDim', None)
                                    if x and y:
                                        perim = 2*(float(x)+float(y))
                                        break
                                if swept.is_a('IfcCircleProfileDef'):
                                    r = getattr(swept, 'Radius', None)
                                    if r:
                                        perim = 2*math.pi*float(r)
                                        break
                    except Exception:
                        pass

                    # If item itself is a polyline or contains points, collect
                    try:
                        if item.is_a('IfcPolyline'):
                            poly = [tuple(p.Coordinates) for p in getattr(item, 'Points', [])]
                            if poly:
                                polyline_points = poly
                                break
                        # If item is IfcPolygonalFaceSet or IfcFaceBasedSurfaceModel, try to collect Cartesian points
                        if item.is_a('IfcCartesianPointList3D') or item.is_a('IfcCartesianPointList2D'):
                            # CoordList attribute
                            cl = getattr(item, 'CoordList', None) or getattr(item, 'CoordList', None)
                            if cl:
                                for c in cl:
                                    if len(c) >= 2:
                                        pts.append((float(c[0]), float(c[1])))
                        # If item has attribute Points or Vertices
                        for attr in ('Points', 'CoordList', 'Coordinates', 'Vertices'):
                            if hasattr(item, attr):
                                a = getattr(item, attr)
                                if a:
                                    for p in a:
                                        try:
                                            if hasattr(p, 'Coordinates'):
                                                c = tuple(p.Coordinates)
                                                if len(c) >= 2:
                                                    pts.append((float(c[0]), float(c[1])))
                                        except Exception:
                                            pass
                    except Exception:
                        pass
                if perim is not None or polyline_points is not None:
                    break
    except Exception:
        pass

    if perim is None:
        if polyline_points:
            # compute closed perimeter for polyline
            # ensure 2D coords
            pcoords = [(float(p[0]), float(p[1])) for p in polyline_points]
            per = 0.0
            for i in range(len(pcoords)):
                a = pcoords[i]
                b = pcoords[(i+1)%len(pcoords)]
                per += coord_dist(a,b)
            perim = per
        elif pts:
            # fallback: use bounding box perimeter from collected points
            xs = [p[0] for p in pts]
            ys = [p[1] for p in pts]
            dx = max(xs) - min(xs)
            dy = max(ys) - min(ys)
            perim = 2*(abs(dx)+abs(dy))
        else:
            perim = 0.0

    perimeters[key] = float(perim)

