# Helper: collect property name->value from property sets attached to an entity
def get_pset_dict(entity):
    d = {}
    # iterate all IfcRelDefinesByProperties where this entity is a RelatedObject
    for rel in ifc.by_type('IfcRelDefinesByProperties'):
        try:
            if entity in rel.RelatedObjects:
                prop = rel.RelatingPropertyDefinition
                if prop.is_a('IfcPropertySet'):
                    for p in prop.HasProperties:
                        if p.is_a('IfcPropertySingleValue'):
                            name = str(p.Name)
                            val = None
                            if getattr(p, 'NominalValue', None) is not None:
                                # try to extract wrappedValue safely
                                nv = p.NominalValue
                                if hasattr(nv, 'wrappedValue'):
                                    val = nv.wrappedValue
                                else:
                                    val = str(nv)
                            d[name] = val
        except Exception:
            # robust against unexpected relation contents
            continue
    return d

# Helper: determine if a wall has a softness indicator
def wall_has_softness(wall):
    # check property sets
    p = get_pset_dict(wall)
    for k, v in p.items():
        if k and 'soft' in k.lower() or (k and 'spatially' in k.lower()) or (k and 'perceived' in k.lower()):
            if isinstance(v, str):
                if v.lower() in ('true', 'yes', '1', 'y'):
                    return True
            if isinstance(v, bool) and v:
                return True
            if v is not None and isinstance(v, (int, float)) and v > 0:
                # numeric softness indicator (heuristic)
                return True
    # check material names associated via IfcRelAssociatesMaterial
    for rel in ifc.by_type('IfcRelAssociatesMaterial'):
        try:
            if rel.RelatedObjects and wall in rel.RelatedObjects:
                mat = rel.RelatingMaterial
                if mat is None:
                    continue
                # various material entity types
                name = getattr(mat, 'Name', None)
                if name and 'soft' in name.lower():
                    return True
                # If material is a complex type, try deeper
                if mat.is_a('IfcMaterial'):
                    if getattr(mat, 'Name', None) and 'soft' in mat.Name.lower():
                        return True
                else:
                    # str(mat) fallback
                    try:
                        if 'soft' in str(mat).lower():
                            return True
                    except Exception:
                        pass
        except Exception:
            continue
    return False

