def collect_points(obj, points, seen):
    try:
        oid = id(obj)
    except Exception:
        oid = None
    if oid and oid in seen:
        return
    if oid:
        seen.add(oid)
    # primitives
    if obj is None:
        return
    if isinstance(obj, (int, float, str, bool)):
        return
    # ifcopenshell entity checks
    try:
        if hasattr(obj, 'is_a') and obj.is_a('IfcCartesianPoint'):
            coords = list(getattr(obj, 'Coordinates', []))
            try:
                coords = [float(c) for c in coords]
                if len(coords) >= 3:
                    points.append((coords[0], coords[1], coords[2]))
                elif len(coords) == 2:
                    points.append((coords[0], coords[1], 0.0))
            except Exception:
                pass
            return
        if hasattr(obj, 'is_a') and obj.is_a('IfcCartesianPointList3D'):
            try:
                for c in getattr(obj, 'CoordList', []):
                    if c:
                        coords = [float(x) for x in c]
                        if len(coords) >= 3:
                            points.append((coords[0], coords[1], coords[2]))
            except Exception:
                pass
            return
    except Exception:
        pass
    # iterables
    if isinstance(obj, (list, tuple)):
        for o in obj:
            collect_points(o, points, seen)
        return
    # try attributes via dir to find nested geometry objects
    try:
        for name in dir(obj):
            if name.startswith('_'):
                continue
            # skip many common non-data attributes
            if name in ('is_a', 'id', 'get_info'):
                continue
            try:
                val = getattr(obj, name)
            except Exception:
                continue
            # skip callables
            if callable(val):
                continue
            collect_points(val, points, seen)
    except Exception:
        pass


def translation_from_placement(placement):
    # accumulate translations through nested IfcLocalPlacement
    tx = ty = tz = 0.0
    seen = set()
    p = placement
    while p is not None:
        if id(p) in seen:
            break
        seen.add(id(p))
        try:
            if p.is_a('IfcLocalPlacement'):
                rel = getattr(p, 'RelativePlacement', None)
                if rel is not None and hasattr(rel, 'is_a') and rel.is_a('IfcAxis2Placement3D'):
                    loc = getattr(rel, 'Location', None)
                    if loc is not None and hasattr(loc, 'Coordinates'):
                        try:
                            coords = [float(c) for c in loc.Coordinates]
                            if len(coords) >= 3:
                                tx += coords[0]
                                ty += coords[1]
                                tz += coords[2]
                        except Exception:
                            pass
                # move up the chain
                p = getattr(p, 'PlacementRelTo', None)
                continue
        except Exception:
            break
        break
    return (tx, ty, tz)

