for prod in products:
    try:
        reps = []
        if hasattr(prod, 'Representation') and prod.Representation is not None:
            reps = list(getattr(prod.Representation, 'Representations', []))
        if not reps:
            continue
        points = []
        seen = set()
        for rep in reps:
            items = getattr(rep, 'Items', [])
            collect_points(items, points, seen)
        if not points:
            continue
        # apply placement translation
        try:
            placement = getattr(prod, 'ObjectPlacement', None)
        except Exception:
            placement = None
        tx, ty, tz = translation_from_placement(placement)
        transformed = [(float(x)+tx, float(y)+ty, float(z)+tz) for (x,y,z) in points]
        xs = [p[0] for p in transformed]
        ys = [p[1] for p in transformed]
        zs = [p[2] for p in transformed]
        minx, maxx = min(xs), max(xs)
        miny, maxy = min(ys), max(ys)
        minz, maxz = min(zs), max(zs)
        dx = maxx - minx
        dy = maxy - miny
        dz = maxz - minz
        vol = 0.0
        if dx > 0 and dy > 0 and dz > 0:
