import ifcopenshell

spaces = ifc.by_type('IfcSpace')
keywords = ['corridor','corr','flur','gang','korridor','hallway','vestibule','diele','hall']

matches = []
for s in spaces:
    parts = []
    for attr in ('Name','LongName','Description','Tag'):
        val = getattr(s, attr, None)
        if val:
            parts.append(str(val))
    combined = " ".join(parts).lower()
    if any(k in combined for k in keywords):
        matches.append({'global_id': s.GlobalId, 'name': getattr(s,'Name',None), 'long_name': getattr(s,'LongName',None), 'description': getattr(s,'Description',None), 'tag': getattr(s,'Tag',None)})

# If none found by direct attributes, search property sets text
if not matches:
    for s in spaces:
        try:
            for rel in getattr(s, 'IsDefinedBy', []) or []:
                propdef = getattr(rel, 'RelatingPropertyDefinition', None)
                if propdef is None:
                    continue
                txt = str(propdef).lower()
                if any(k in txt for k in keywords):
                    matches.append({'global_id': s.GlobalId, 'name': getattr(s,'Name',None), 'long_name': getattr(s,'LongName',None), 'description': getattr(s,'Description',None), 'tag': getattr(s,'Tag',None)})
                    break
                # also check properties
                for p in getattr(propdef, 'HasProperties', []) or []:
                    try:
                        if any(k in str(p).lower() for k in keywords):
                            matches.append({'global_id': s.GlobalId, 'name': getattr(s,'Name',None), 'long_name': getattr(s,'LongName',None), 'description': getattr(s,'Description',None), 'tag': getattr(s,'Tag',None)})
                            raise StopIteration
                    except StopIteration:
                        break
        except Exception:
            pass

# Fallback: if still none, pick the largest area by IfcQuantityArea if available
if not matches and spaces:
    best = None
    best_area = -1.0
    for s in spaces:
        area = None
        # try quantity sets
        for rel in getattr(s, 'IsDefinedBy', []) or []:
            propdef = getattr(rel, 'RelatingPropertyDefinition', None)
            if not propdef:
                continue
            for p in getattr(propdef, 'HasProperties', []) or []:
                if p.is_a('IfcQuantityArea'):
                    try:
                        area = float(p.AreaValue)
                    except Exception:
                        try:
                            area = float(getattr(p, 'AreaValue', 0))
                        except Exception:
                            area = None
        if area is None:
            # try geometry bounding box fallback not used
            area = 0
        if area > best_area:
            best_area = area
            best = s
    if best:
        matches.append({'global_id': best.GlobalId, 'name': getattr(best,'Name',None), 'long_name': getattr(best,'LongName',None), 'description': getattr(best,'Description',None), 'tag': getattr(best,'Tag',None), 'estimated_area': best_area})

# Prepare result
if matches:
    result = {'found': True, 'count': len(matches), 'matches': matches, 'primary_global_id': matches[0]['global_id']}
else:
    result = {'found': False, 'count': 0, 'matches': []}

