    graph = {gid: [] for gid in spaces}
    for door_gid, space_set in door_to_spaces.items():
        space_list = list(space_set)
        if len(space_list) >= 2:
            # connect each pair (usually two)
            a, b = space_list[0], space_list[1]
            graph[a].append((b, door_gid))
            graph[b].append((a, door_gid))
        # If more than two spaces share a door (unlikely), connect all pairs
        if len(space_list) > 2:
            for i in range(len(space_list)):
                for j in range(i+1, len(space_list)):
                    a = space_list[i]; b = space_list[j]
                    graph[a].append((b, door_gid))
                    graph[b].append((a, door_gid))

    # BFS shortest path on spaces
    queue = deque([src_gid])
    prev = {src_gid: (None, None)}  # space -> (previous_space, door_gid used to get here)
    found = False
    while queue:
        cur = queue.popleft()
        if cur == dst_gid:
            found = True
            break
        for neighbor, door_gid in graph.get(cur, []):
            if neighbor not in prev:
                prev[neighbor] = (cur, door_gid)
                queue.append(neighbor)
    if not found:
        result = {
            'global_ids': [],
            'raw_model_response': 'No path found between the given spaces using door-space adjacency.'
        }
        commit()
    else:
        # reconstruct door global ids along path
        path_doors = []
        cur = dst_gid
        while prev[cur][0] is not None:
            prev_space, via_door = prev[cur]
            path_doors.append(via_door)
            cur = prev_space
        path_doors.reverse()
        result = {
            'global_ids': path_doors,
            'raw_model_response': f'Found path with {len(path_doors)} doors.'
        }
        commit()

