        target = s
        break
    # check properties in IfcPropertySet
    if hasattr(s, 'IsDefinedBy'):
        for rel in s.IsDefinedBy:
            try:
                pset = rel.RelatingPropertyDefinition
            except Exception:
                pset = None
            if pset and getattr(pset, 'is_a', lambda x: False)('IfcPropertySet'):
                for prop in getattr(pset, 'HasProperties', []):
                    name = getattr(prop, 'Name', None)
                    val = None
                    if prop.is_a('IfcPropertySingleValue'):
                        v = getattr(prop, 'NominalValue', None)
                        if v:
                            val = getattr(v, 'wrappedValue', str(v))
                    if contains_semi(name) or contains_semi(val):
                        target = s
                        break
                if target:
                    break
    # check classifications
    if hasattr(s, 'HasAssociations'):
        for assoc in s.HasAssociations:
            if assoc.is_a('IfcRelAssociatesClassification'):
                cl = assoc.RelatingClassification
                if cl is not None:
                    txt = getattr(cl, 'Name', '') or getattr(cl, 'Description', '')
                    if contains_semi(txt):
                        target = s
                        break
        if target:
            break

