                continue
            # check pset name/description
            if match_text(getattr(pset,'Name',None)) or match_text(getattr(pset,'Description',None)):
                matches.append({'global_id': s.GlobalId, 'name': getattr(s,'Name',None), 'pset': getattr(pset,'Name',None)})
                found = True
                break
            for prop in getattr(pset,'HasProperties',[]):
                # check property name and value
                if match_text(getattr(prop,'Name',None)):
                    matches.append({'global_id': s.GlobalId, 'name': getattr(s,'Name',None), 'pset': getattr(pset,'Name',None), 'property': getattr(prop,'Name',None)})
                    found = True
                    break
                if prop.is_a('IfcPropertySingleValue'):
                    v = getattr(prop,'NominalValue',None)
                    if v and match_text(getattr(v,'wrappedValue',str(v))):
                        matches.append({'global_id': s.GlobalId, 'name': getattr(s,'Name',None), 'pset': getattr(pset,'Name',None), 'property': getattr(prop,'Name',None), 'value': getattr(v,'wrappedValue',str(v))})
                        found = True
                        break
                else:
                    # fallback check string of prop
                    if match_text(str(prop)):
                        matches.append({'global_id': s.GlobalId, 'name': getattr(s,'Name',None), 'pset': getattr(pset,'Name',None), 'property': getattr(prop,'Name',None)})
                        found = True
                        break
            if found:
                break
    if found:
        continue
    # check classifications and associations
    if hasattr(s, 'HasAssociations'):
        for assoc in s.HasAssociations:
            try:
                if assoc.is_a('IfcRelAssociatesClassification'):
                    cl = assoc.RelatingClassification
                    if cl and (match_text(getattr(cl,'Name',None)) or match_text(getattr(cl,'Description',None)) or match_text(str(cl))):
                        matches.append({'global_id': s.GlobalId, 'name': getattr(s,'Name',None), 'classification': getattr(cl,'Name',None)})
                        found = True
                        break
            except Exception:
                continue
        if found:
            continue
    # deep string scan of the entity
    s_str = str(s)
    if match_text(s_str):
        matches.append({'global_id': s.GlobalId, 'name': getattr(s,'Name',None), 'string': s_str})
        continue

result = {'matches': matches}
commit()

