import ifcopenshell

# Collect spaces
spaces = ifc.by_type("IfcSpace")

# Prepare data structures
scores = {}
detail = {}

# Build quick lookup for IfcRelVoidsElement and IfcRelFillsElement
rel_voids = ifc.by_type("IfcRelVoidsElement")
rel_fills = ifc.by_type("IfcRelFillsElement")
rel_space_boundaries = ifc.by_type("IfcRelSpaceBoundary")

# Helper: get area from element quantities or property sets
def get_area_from_element(elem):
    try:
        if hasattr(elem, "IsDefinedBy"):
            for rel in elem.IsDefinedBy:
                if rel.is_a("IfcRelDefinesByProperties"):
                    prop = rel.RelatingPropertyDefinition
                    if prop is None:
                        continue
                    # If IfcElementQuantity
                    if prop.is_a("IfcElementQuantity"):
                        for q in getattr(prop, 'Quantities', []) or []:
                            if q is None:
                                continue
                            if q.is_a("IfcQuantityArea"):
                                # AreaValue attribute
                                val = getattr(q, 'AreaValue', None)
                                if val is not None:
                                    try:
                                        return float(val)
                                    except:
                                        pass
                    # If IfcPropertySet (IfcPropertySet) containing IfcPropertySingleValue
                    if prop.is_a("IfcPropertySet"):
                        for p in getattr(prop, 'HasProperties', []) or []:
                            if p is None:
                                continue
                            name = (getattr(p, 'Name', '') or '').lower()
                            if name in ("area", "netarea", "grossarea", "windowarea"):
                                nom = getattr(p, 'NominalValue', None)
                                if nom is not None:
                                    # Try wrappedValue
                                    val = getattr(nom, 'wrappedValue', None)
                                    if val is None:
                                        val = nom
                                    try:
                                        return float(val)
                                    except:
                                        pass
    except Exception:
        pass
    return None

# Initialize spaces
for sp in spaces:
    sid = sp.GlobalId
    scores[sid] = 0.0
    detail[sid] = {"space_name": getattr(sp, 'Name', None), "windows":0, "window_area":0.0, "openings":0, "opening_area":0.0, "doors":0, "door_area":0.0}

# Process space boundaries
for rel in rel_space_boundaries:
    sp = getattr(rel, 'RelatingSpace', None)
    if sp is None:
        continue
    sid = sp.GlobalId
    related = getattr(rel, 'RelatedBuildingElement', None)
    if related is None:
        continue
    try:
        if related.is_a('IfcWindow'):
            area = get_area_from_element(related) or 1.5
            detail[sid]['windows'] += 1
            detail[sid]['window_area'] += float(area)
        elif related.is_a('IfcDoor'):
            area = get_area_from_element(related) or 1.2
            detail[sid]['doors'] += 1
            detail[sid]['door_area'] += float(area)
        elif related.is_a('IfcOpeningElement'):
            # check if filled
            filled = False
            for rf in rel_fills:
                if getattr(rf, 'RelatingOpeningElement', None) == related:
                    filled_elem = getattr(rf, 'RelatedBuildingElement', None)
                    if filled_elem is None:
                        continue
                    if filled_elem.is_a('IfcWindow'):
                        area = get_area_from_element(filled_elem) or 1.5
                        detail[sid]['windows'] += 1
                        detail[sid]['window_area'] += float(area)
                        filled = True
                        break
                    elif filled_elem.is_a('IfcDoor'):
                        area = get_area_from_element(filled_elem) or 1.2
                        detail[sid]['doors'] += 1
                        detail[sid]['door_area'] += float(area)
                        filled = True
                        break
            if not filled:
                area = 1.0
                detail[sid]['openings'] += 1
                detail[sid]['opening_area'] += float(area)
        elif related.is_a('IfcWall') or related.is_a('IfcWallStandardCase'):
            # find openings in this wall
            for rv in rel_voids:
                if getattr(rv, 'RelatingBuildingElement', None) == related:
                    opening = getattr(rv, 'RelatedOpeningElement', None)
                    if opening is None:
                        continue
                    # check fills
                    filled2 = False
                    for rf in rel_fills:
                        if getattr(rf, 'RelatingOpeningElement', None) == opening:
                            filled_elem = getattr(rf, 'RelatedBuildingElement', None)
                            if filled_elem is None:
                                continue
                            if filled_elem.is_a('IfcWindow'):
                                area = get_area_from_element(filled_elem) or 1.5
                                detail[sid]['windows'] += 1
                                detail[sid]['window_area'] += float(area)
                                filled2 = True
                                break
                            elif filled_elem.is_a('IfcDoor'):
                                area = get_area_from_element(filled_elem) or 1.2
                                detail[sid]['doors'] += 1
                                detail[sid]['door_area'] += float(area)
                                filled2 = True
                                break
                    if not filled2:
                        area = 1.0
                        detail[sid]['openings'] += 1
                        detail[sid]['opening_area'] += float(area)
    except Exception:
        # ignore problematic relation
        continue

# Compute brightness score (use glazing area primarily)
for sid, d in detail.items():
    # score: windows count weighted by area + openings and doors reduced
    score = d['window_area'] + 0.6 * d['opening_area'] + 0.5 * d['door_area']
    scores[sid] = float(score)

# Find best space
best_sid = None
best_score = -1.0
for sid, sc in scores.items():
    if sc > best_score:
        best_score = sc
        best_sid = sid

result = {
    'global_id': best_sid,
    'best_score': best_score,
    'detail': detail
}

commit()

import ifcopenshell
from collections import defaultdict

# Load IFC (variable 'ifc' is provided by the tool loader when opening path)
# The tool will provide ifc when opening; if not, open explicitly
# But per tool instructions, the tool loads the IFC as variable `ifc`.

# Find a target space (IfcSpace). If multiple, pick the first.
spaces = ifc.by_type('IfcSpace')
if len(spaces) == 0:
    # fallback: try IfcBuildingStorey as proxy for the room
    spaces = ifc.by_type('IfcBuildingStorey')

if len(spaces) == 0:
    # nothing to analyze
    result = {'error': 'No IfcSpace or IfcBuildingStorey found in the model.'}
else:
    target_space = spaces[0]
    # collect walls bounding the space via IfcRelSpaceBoundary
    walls = []
    for rel in ifc.by_type('IfcRelSpaceBoundary'):
        try:
            if rel.RelatingSpace and rel.RelatingSpace.GlobalId == target_space.GlobalId:
                elem = rel.RelatedBuildingElement
                if elem is not None and (elem.is_a('IfcWall') or elem.is_a('IfcWallStandardCase')):
                    if elem not in walls:
                        walls.append(elem)
        except Exception:
            pass

    # fallback: if no space boundaries found, search for walls in model (take all walls)
    if not walls:
        for w in ifc.by_type('IfcWall') + ifc.by_type('IfcWallStandardCase'):
            walls.append(w)

    def opening_area_from_rep(rep_item):
        # try to extract rectangle profile dims from IfcExtrudedAreaSolid
        try:
            if rep_item.is_a('IfcExtrudedAreaSolid'):
                swept = rep_item.SweptArea
                # Rectangle profile
                if swept is not None and swept.is_a('IfcRectangleProfileDef'):
                    x = swept.XDim if hasattr(swept, 'XDim') and swept.XDim is not None else 0.0
                    y = swept.YDim if hasattr(swept, 'YDim') and swept.YDim is not None else 0.0
                    return float(x) * float(y)
        except Exception:
            pass
        return 0.0

    def compute_product_area(product):
        # Inspect Representation -> Representations -> Items
        area = 0.0
        try:
            if product.Representation:
                for rep in product.Representation.Representations:
                    if rep and hasattr(rep, 'Items'):
                        for item in rep.Items:
                            area += opening_area_from_rep(item)
        except Exception:
            pass
        return area

    wall_stats = []
    for w in walls:
        # find openings in this wall using IfcRelVoidsElement
        openings = []
        for rel in ifc.by_type('IfcRelVoidsElement'):
            try:
                if rel.RelatingBuildingElement and rel.RelatingBuildingElement.GlobalId == w.GlobalId:
                    if rel.RelatedOpeningElement is not None:
                        openings.append(rel.RelatedOpeningElement)
            except Exception:
                pass

        # for each opening, check if it is filled by a window (IfcRelFillsElement)
        window_fill_area = 0.0
        window_count = 0
        opening_area_total = 0.0
        for o in openings:
            area_o = compute_product_area(o)
            opening_area_total += area_o
            # find fills
            filled = False
            for rf in ifc.by_type('IfcRelFillsElement'):
                try:
                    if rf.RelatingOpeningElement and rf.RelatingOpeningElement.GlobalId == o.GlobalId:
                        # rf.RelatedBuildingElement should be the window
                        wb = rf.RelatedBuildingElement
                        if wb is not None and (wb.is_a('IfcWindow') or wb.is_a('IfcWindowStandardCase')):
                            filled = True
                            # try to compute window representation area if available; else use opening area
                            area_w = compute_product_area(wb)
                            if area_w <= 0.0:
                                area_w = area_o
                            window_fill_area += area_w
                            window_count += 1
                except Exception:
                    pass
            # if not filled, contributes 0 to window_fill_area

        wall_stats.append({
            'wall': w,
            'wall_global_id': w.GlobalId,
            'opening_count': len(openings),
            'opening_area_total': opening_area_total,
            'window_count': window_count,
            'window_area_total': window_fill_area
        })

    # choose the wall with smallest window_area_total (darkest)
    if not wall_stats:
        result = {'error': 'No walls found to analyze.'}
    else:
        # sort by window_area_total, then by window_count, then by opening_area_total
        wall_stats.sort(key=lambda x: (x['window_area_total'], x['window_count'], x['opening_area_total']))
        chosen = wall_stats[0]
        result = {
            'selected_wall_global_id': chosen['wall_global_id'],
            'window_area_total': chosen['window_area_total'],
            'window_count': chosen['window_count'],
            'opening_count': chosen['opening_count'],
            'opening_area_total': chosen['opening_area_total'],
            'considered_space_global_id': target_space.GlobalId
        }

# Save changes (none expected, but required)
commit()

