import collections

def extract_text_from_value(val):
    try:
        if val is None:
            return ''
        # If it's an IfcValue with wrappedValue
        if hasattr(val, 'wrappedValue'):
            return str(val.wrappedValue)
        return str(val)
    except Exception:
        return ''

spaces = ifc.by_type('IfcSpace')
indirect_spaces = []

for space in spaces:
    related_elements = set()
    # collect RelatedElements from IfcRelContainedInSpatialStructure
    for inv in ifc.get_inverse(space):
        if inv.is_a('IfcRelContainedInSpatialStructure'):
            for re in inv.RelatedElements or []:
                related_elements.add(re)
    matched = False
    for elem in related_elements:
        texts = []
        # basic attributes
        for a in ('Name','ObjectType','Description','LongName'):
            try:
                v = getattr(elem, a, None)
                if v:
                    texts.append(str(v))
            except Exception:
                pass
        # entity/type name
        try:
            texts.append(elem.is_a())
        except Exception:
            pass
        # check related type object (IfcRelDefinesByType)
        for rel in ifc.get_inverse(elem):
            if rel.is_a('IfcRelDefinesByType'):
                typ = rel.RelatingType
                if typ:
                    for a in ('Name','PredefinedType','ObjectType','Description'):
                        try:
                            v = getattr(typ, a, None)
                            if v:
                                texts.append(str(v))
                        except Exception:
                            pass
                    # property sets on the type
                    for inv2 in ifc.get_inverse(typ):
                        if inv2.is_a('IfcRelDefinesByProperties'):
                            pdef = inv2.RelatingPropertyDefinition
                            if pdef and pdef.is_a('IfcPropertySet'):
                                for prop in pdef.HasProperties or []:
                                    try:
                                        if hasattr(prop, 'Name') and prop.Name:
                                            texts.append(str(prop.Name))
                                    except Exception:
                                        pass
                                    try:
                                        if hasattr(prop, 'NominalValue') and prop.NominalValue:
                                            texts.append(extract_text_from_value(prop.NominalValue))
                                    except Exception:
                                        pass
        # property sets on element
        for inv in ifc.get_inverse(elem):
            if inv.is_a('IfcRelDefinesByProperties'):
                pdef = inv.RelatingPropertyDefinition
                if pdef:
                    # If it's an IfcPropertySet
                    if pdef.is_a('IfcPropertySet'):
                        for prop in pdef.HasProperties or []:
                            try:
                                if hasattr(prop, 'Name') and prop.Name:
                                    texts.append(str(prop.Name))
                            except Exception:
