import collections

def stringify(obj, visited=None, depth=0, maxdepth=5):
    if visited is None:
        visited = set()
    try:
        if depth>maxdepth:
            return ''
        if obj is None:
            return ''
        if isinstance(obj, (str, int, float, bool)):
            return str(obj)
        if hasattr(obj, 'is_a'):
            eid = id(obj)
            if eid in visited:
                return ''
            visited.add(eid)
            info = obj.get_info()
            parts = []
            for k,v in info.items():
                parts.append(str(k))
                parts.append(stringify(v, visited, depth+1, maxdepth))
            return ' '.join(parts)
        if isinstance(obj, (list, tuple, set)):
            return ' '.join([stringify(x, visited, depth+1, maxdepth) for x in obj])
        try:
            return str(obj)
        except Exception:
            return ''
    except Exception:
        return ''

