# Code to find the IfcSpace whose placement is closest to the centroid of all spaces
# The IFC model is provided as variable `ifc` by the execution environment. If not, open it from ifc_file_path.

try:
    ifc  # ifc is already loaded by the execution environment
except NameError:
    import ifcopenshell
    ifc = ifcopenshell.open(ifc_file_path)

# Helper: extract coordinates from IfcAxis2Placement2D/3D

def get_axis_coords(axis):
    if axis is None:
        return (0.0, 0.0, 0.0)
    # Axis could be IfcAxis2Placement3D or IfcAxis2Placement2D
    loc = getattr(axis, 'Location', None)
    if loc is None:
        return (0.0, 0.0, 0.0)
    coords = []
    # loc should be an IfcCartesianPoint with Coordinates attribute
    if hasattr(loc, 'Coordinates'):
        coords = list(loc.Coordinates)
    # normalize to 3 components
    if len(coords) == 0:
        return (0.0, 0.0, 0.0)
    if len(coords) == 1:
        return (float(coords[0]), 0.0, 0.0)
    if len(coords) == 2:
        return (float(coords[0]), float(coords[1]), 0.0)
    # >=3
    return (float(coords[0]), float(coords[1]), float(coords[2]))

# Recursively accumulate translations from IfcLocalPlacement chain

def get_placement_translation(placement):
    if placement is None:
        return (0.0, 0.0, 0.0)
    # If it's not a local placement but an axis placement, try to extract coords directly
    if placement.is_a('IfcLocalPlacement'):
        rel = getattr(placement, 'RelativePlacement', None)
        this_coords = get_axis_coords(rel)
        parent = None
        # try common attribute names for parent placement
        if hasattr(placement, 'PlacementRelTo') and placement.PlacementRelTo:
            parent = placement.PlacementRelTo
        elif hasattr(placement, 'RelativeTo') and placement.RelativeTo:
            parent = placement.RelativeTo
        if parent:
            parent_coords = get_placement_translation(parent)
        else:
            parent_coords = (0.0, 0.0, 0.0)
        # sum component-wise
        return (this_coords[0] + parent_coords[0],
                this_coords[1] + parent_coords[1],
                this_coords[2] + parent_coords[2])
    else:
        # Not a local placement (rare). If it's an axis placement, extract coords
        if placement.is_a('IfcAxis2Placement3D') or placement.is_a('IfcAxis2Placement2D'):
            return get_axis_coords(placement)
        return (0.0, 0.0, 0.0)

# Collect spaces and their computed placement coordinates
spaces = ifc.by_type('IfcSpace')
space_coords = []
for sp in spaces:
    try:
        coords = get_placement_translation(getattr(sp, 'ObjectPlacement', None))
    except Exception:
        coords = (0.0, 0.0, 0.0)
    space_coords.append((sp, coords))

# If no spaces found or none with placement, fallback to first IfcSpace
if not space_coords:
    result = {'error': 'No IfcSpace instances found in the model.'}
    commit()
else:
    # compute average centroid
    count = float(len(space_coords))
    sumx = sum([c[0] for (_, c) in space_coords])
    sumy = sum([c[1] for (_, c) in space_coords])
    sumz = sum([c[2] for (_, c) in space_coords])
    avg = (sumx / count, sumy / count, sumz / count)

    def dist2(a, b):
        return (a[0]-b[0])**2 + (a[1]-b[1])**2 + (a[2]-b[2])**2

    # find space with minimum distance to average centroid
    min_space = None
    min_coords = None
    min_d2 = None
    for sp, coords in space_coords:
        d2 = dist2(coords, avg)
        if (min_d2 is None) or (d2 < min_d2):
            min_d2 = d2
            min_space = sp
            min_coords = coords

    # prepare result
    result = {
        'global_id': getattr(min_space, 'GlobalId', None),
        'name': getattr(min_space, 'Name', None),
        'coords': (min_coords[0], min_coords[1], min_coords[2]),
        'centroid_of_all_spaces': (avg[0], avg[1], avg[2]),
        'distance_squared_to_centroid': float(min_d2) if min_d2 is not None else None
    }
    commit()

# This code runs with `ifc` variable preloaded (ifcopenshell file) and must set `result` and call commit().
from collections import defaultdict

def get_cartesian_coords(point):
    try:
        return tuple(float(c) for c in point.Coordinates)
    except Exception:
        return None

# Compute translation from IfcLocalPlacement (sum of nested placements). Ignore rotation in complex cases.
def placement_translation(placement):
    tx, ty, tz = 0.0, 0.0, 0.0
    visited = set()
    p = placement
    while p is not None:
        if p.id() in visited:
            break
        visited.add(p.id())
        # RelativePlacement is IfcAxis2Placement3D or 2D
        rel = getattr(p, 'RelativePlacement', None)
        if rel:
            loc = getattr(rel, 'Location', None)
            if loc:
                coords = get_cartesian_coords(loc)
                if coords:
                    tx += coords[0]
                    ty += coords[1]
                    tz += coords[2]
        # move to PlacementRelTo
        p = getattr(p, 'PlacementRelTo', None)
    return (tx, ty, tz)


def apply_translation(pt, trans):
    return (pt[0] + trans[0], pt[1] + trans[1], pt[2] + trans[2])


def collect_points_from_representation(rep, placement_trans=(0,0,0)):
    pts = []
    if not rep:
        return pts
    for ri in rep.Representations:
        # iterate items
        for item in ri.Items:
            typename = item.is_a()
            try:
                if typename == 'IfcFacetedBrep':
                    shell = item.Outer
                    if shell:
                        for face in shell.CfsFaces:
                            for bound in face.Bounds:
                                loop = bound.Bound
                                # Often IfcPolyLoop
                                if loop and loop.is_a('IfcPolyLoop'):
                                    for p in loop.Polygon:
                                        c = get_cartesian_coords(p)
                                        if c: pts.append(apply_translation(c, placement_trans))
                elif typename == 'IfcFacetedBrepWithVoids':
                    shell = item.Outer
                    if shell:
                        for face in shell.CfsFaces:
                            for bound in face.Bounds:
                                loop = bound.Bound
                                if loop and loop.is_a('IfcPolyLoop'):
                                    for p in loop.Polygon:
                                        c = get_cartesian_coords(p)
                                        if c: pts.append(apply_translation(c, placement_trans))
                elif typename == 'IfcMappedItem':
                    # try to resolve MappingSource mapping to representation
                    map_source = item.MappingSource
                    if map_source and getattr(map_source, 'MappedRepresentation', None):
                        mapped = map_source.MappedRepresentation
                        # MappedRepresentation has Representations
                        for mapped_rep in mapped.Representations:
                            for mapped_item in mapped_rep.Items:
                                # recursive: try IfcFacetedBrep
                                if mapped_item.is_a('IfcFacetedBrep'):
                                    shell = mapped_item.Outer
                                    if shell:
                                        for face in shell.CfsFaces:
                                            for bound in face.Bounds:
                                                loop = bound.Bound
                                                if loop and loop.is_a('IfcPolyLoop'):
                                                    for p in loop.Polygon:
                                                        c = get_cartesian_coords(p)
                                                        if c: pts.append(apply_translation(c, placement_trans))
                elif typename == 'IfcPolygonalFaceSet':
                    for p in item.CoordIndex:
                        # CoordIndex are indices into Coordinates
                        pass
                elif typename == 'IfcTriangulatedFaceSet':
                    if getattr(item, 'Coordinates', None):
                        for p in item.Coordinates.CoordList:
                            c = tuple(float(x) for x in p)
                            pts.append(apply_translation(c, placement_trans))
                elif typename == 'IfcExtrudedAreaSolid':
                    # handle rectangle and circle profiles by sampling corners
                    swept = item.SweptArea
                    depth = float(item.Depth) if getattr(item, 'Depth', None) is not None else 0.0
                    # default extrusion direction
                    exdir = (0.0, 0.0, 1.0)
                    if getattr(item, 'ExtrudedDirection', None) and getattr(item.ExtrudedDirection, 'DirectionRatios', None):
                        exdir = tuple(float(x) for x in item.ExtrudedDirection.DirectionRatios)
                    if swept and swept.is_a('IfcRectangleProfileDef'):
                        xdim = float(swept.XDim)
                        ydim = float(swept.YDim)
                        # rectangle centered at local origin? If position exists, include it
                        offset = (0.0, 0.0, 0.0)
                        if getattr(swept, 'Position', None) and getattr(swept.Position, 'Location', None):
                            loc = swept.Position.Location
                            c = get_cartesian_coords(loc)
                            if c:
                                offset = c
                        # four corners in local plane (assume XY plane)
                        corners = [(-xdim/2, -ydim/2, 0), (xdim/2, -ydim/2, 0), (xdim/2, ydim/2, 0), (-xdim/2, ydim/2, 0)]
                        for cor in corners:
                            # add offset and then optionally extrude endpoints
                            p1 = (cor[0]+offset[0], cor[1]+offset[1], cor[2]+offset[2])
                            pts.append(apply_translation(p1, placement_trans))
                            p2 = (p1[0]+exdir[0]*depth, p1[1]+exdir[1]*depth, p1[2]+exdir[2]*depth)
                            pts.append(apply_translation(p2, placement_trans))
                    elif swept and swept.is_a('IfcCircleProfileDef'):
                        radius = float(swept.Radius)
                        # sample 8 points around circle
                        import math
                        for i in range(8):
                            a = 2*math.pi*i/8
                            p = (radius*math.cos(a), radius*math.sin(a), 0)
                            pts.append(apply_translation(p, placement_trans))
                elif typename == 'IfcFaceBasedSurfaceModel':
                    for face in item.FbsmFaces:
                        for bound in face.Bounds:
                            loop = bound.Bound
                            if loop and loop.is_a('IfcPolyLoop'):
                                for p in loop.Polygon:
                                    c = get_cartesian_coords(p)
                                    if c: pts.append(apply_translation(c, placement_trans))
                # add more handlers if needed
            except Exception:
                continue
    return pts

# Gather products of interest
product_types = set(['IfcWall', 'IfcWallStandardCase', 'IfcCurtainWall', 'IfcWindow', 'IfcDoor'])
products = [p for p in ifc.by_type('IfcProduct') if p.is_a() in product_types]

# For fallback capture: also include IfcBuildingElement proxies
if not products:
    products = [p for p in ifc.by_type('IfcProduct') if p.is_a() in ('IfcBuildingElementProxy',)]

all_points = []
product_intervals = []  # (product, minx, maxx, miny, maxy)
for prod in products:
    # get placement translation
    placement = getattr(prod, 'ObjectPlacement', None)
    trans = (0.0, 0.0, 0.0)
    if placement:
        try:
            trans = placement_translation(placement)
        except Exception:
            trans = (0.0, 0.0, 0.0)
    # try geometric representations
    rep = getattr(prod, 'Representation', None)
    pts = []
    if rep:
        pts = collect_points_from_representation(rep, placement_trans=trans)
    # try representations from IfcProductDefinitionShape (some products have .Representation directly already)
    if not pts:
        # try to find representation via IfcProductDefinitionShape attribute
        if getattr(prod, 'Representation', None):
            pts = collect_points_from_representation(prod.Representation, placement_trans=trans)
    # fallback: try to use bounds from IfcBoundingBox if present in representation
    # If still empty, attempt to use the object's placement Location if available
    if not pts:
        if placement and getattr(placement, 'RelativePlacement', None) and getattr(placement.RelativePlacement, 'Location', None):
            loc = get_cartesian_coords(placement.RelativePlacement.Location)
            if loc:
                pts = [apply_translation(loc, (0,0,0))]
    if not pts:
        continue
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    zs = [p[2] for p in pts]
    minx, maxx = min(xs), max(xs)
    miny, maxy = min(ys), max(ys)
    minz, maxz = min(zs), max(zs)
    product_intervals.append((prod, minx, maxx, miny, maxy, minz, maxz))
    all_points.extend(pts)

if not all_points:
    # nothing found; return zero
    result = {'number': '0', 'raw_model_response': 'No geometry points found for products.'}
    commit()
else:
    # compute model min Y to identify south facade (south = -Y direction)
    all_ys = [p[1] for p in all_points]
    model_min_y = min(all_ys)
    # tolerance: 5 cm
    tol = 0.05
    # select products that touch south face (any part within tol of min Y)
    south_products = []
    for prod, minx, maxx, miny, maxy, minz, maxz in product_intervals:
        if abs(miny - model_min_y) <= tol or abs(maxy - model_min_y) <= tol or (miny <= model_min_y + tol and maxy >= model_min_y - tol):
            south_products.append((prod, minx, maxx, miny, maxy, minz, maxz))
    # If none found with small tol, expand tol to 0.5m
    if not south_products:
        tol = 0.5
        for prod, minx, maxx, miny, maxy, minz, maxz in product_intervals:
            if abs(miny - model_min_y) <= tol or abs(maxy - model_min_y) <= tol or (miny <= model_min_y + tol and maxy >= model_min_y - tol):
                south_products.append((prod, minx, maxx, miny, maxy, minz, maxz))

    # Build X intervals for south products
    intervals = [(p[1], p[2]) for (_, p[1], p[2], p[3], p[4], p[5], p[6]) in [(None,)*0]]
    # fix: actually build from south_products
    intervals = [(it[1], it[2]) for it in south_products]
    # If none found, try selecting products with centroid Y very low
    if not intervals:
        for prod, minx, maxx, miny, maxy, minz, maxz in product_intervals:
            cy = (miny+maxy)/2
            if cy <= model_min_y + 0.2:
                intervals.append((minx, maxx))
    # Merge intervals with gap tolerance
    if not intervals:
        number = 0
    else:
        intervals_sorted = sorted(intervals, key=lambda x: x[0])
        merged = []
        gap_tol = 0.15  # 15 cm gap tolerance: if gap > this, separate zone
        cur_min, cur_max = intervals_sorted[0]
        for a,b in intervals_sorted[1:]:
            if a <= cur_max + gap_tol:
                # overlap/close: merge
                cur_max = max(cur_max, b)
            else:
                merged.append((cur_min, cur_max))
                cur_min, cur_max = a, b
        merged.append((cur_min, cur_max))
        number = len(merged)

    # prepare raw response summary
    raw_lines = []
    raw_lines.append(f"model_min_y={model_min_y:.3f}, south_tol={tol}")
    raw_lines.append(f"south_products_count={len(south_products)}")
    raw_lines.append(f"raw_intervals={intervals}")
    raw_lines.append(f"merged_intervals={merged if intervals else []}")
    raw_lines.append(f"zone_count={number}")
    raw_model_response = '\n'.join(raw_lines)
    result = {'number': str(number), 'raw_model_response': raw_model_response}
    commit()

# This script runs with `ifc` preloaded. It computes the number of horizontal facade
# articulation zones on the south elevation (south = -Y direction) by finding products
# that touch the model's minimum Y and merging their vertical (Z) intervals.
