# collect candidate products
candidate_types = set(['IfcWall', 'IfcWallStandardCase', 'IfcCurtainWall', 'IfcWindow', 'IfcDoor', 'IfcSlab', 'IfcBuildingElementProxy'])
products = [p for p in ifc.by_type('IfcProduct') if p.is_a() in candidate_types]

all_points = []
product_intervals = []
for prod in products:
