    pts = []
    rep = getattr(prod, 'Representation', None)
    if rep:
        pts = collect_points_from_representation(rep, placement_trans=trans)
    # fallback to Representation attribute on product
    if not pts and getattr(prod, 'Representation', None):
        pts = collect_points_from_representation(prod.Representation, placement_trans=trans)
    # fallback: use bounding boxes if present in geometric representation contexts
    if not pts:
        # try to get bounds from IfcProduct.Representation.Representations[*].Items[*].Box
        try:
            if rep:
                for ri in rep.Representations:
