    # fallback: use placement location
    if not pts and placement and getattr(placement, 'RelativePlacement', None) and getattr(placement.RelativePlacement, 'Location', None):
        loc = get_cartesian_coords(placement.RelativePlacement.Location)
        if loc:
            pts = [apply_translation(loc, (0,0,0))]
    if not pts:
