# Helper to safely get attribute
def safe_str(val):
    try:
        if val is None:
            return ""
        # If it's an ifcopenshell entity (like IfcLabel wrapper), try wrappedValue
        if hasattr(val, 'wrappedValue'):
            return str(val.wrappedValue)
        return str(val)
    except Exception:
        return ""


def get_psets(entity):
    psets = {}
    try:
        if not hasattr(entity, 'IsDefinedBy'):
            return psets
        for rel in entity.IsDefinedBy:
            try:
                if rel.is_a('IfcRelDefinesByProperties'):
                    prop_def = rel.RelatingPropertyDefinition
                    if prop_def is None:
                        continue
                    if prop_def.is_a('IfcPropertySet'):
                        pset_name = safe_str(prop_def.Name).strip()
                        pset_dict = {}
                        for p in prop_def.HasProperties:
                            try:
                                pname = safe_str(p.Name).strip()
                                pval = None
                                # If single value
                                if p.is_a('IfcPropertySingleValue'):
                                    pval = safe_str(p.NominalValue)
                                elif p.is_a('IfcPropertyEnumeratedValue'):
                                    # join enumeration values
                                    vals = []
                                    for ev in p.EnumerationValues:
                                        vals.append(safe_str(ev))
                                    pval = ",".join(vals)
                                else:
                                    pval = safe_str(p)
                                pset_dict[pname] = pval
                            except Exception:
                                continue
                        psets[pset_name] = pset_dict
            except Exception:
                continue
    except Exception:
        pass
    return psets


# Keywords to detect entrance
keywords = ['entrance','main','entry','eingang','front','principal','main door','entrance door','lobby']

doors = []
try:
    doors = ifc.by_type('IfcDoor')
except Exception:
    doors = []

candidates = []
for d in doors:
    try:
        gid = safe_str(d.GlobalId)
        name = safe_str(getattr(d, 'Name', ''))
        desc = safe_str(getattr(d, 'Description', ''))
        obtype = safe_str(getattr(d, 'ObjectType', ''))
        tag = safe_str(getattr(d, 'Tag', ''))
        psets = get_psets(d)
        # aggregate text
        text_parts = [name, desc, obtype, tag]
        for pset_name, props in psets.items():
            text_parts.append(pset_name)
            for k,v in props.items():
                text_parts.append(k)
                if v is not None:
                    text_parts.append(v)
        text = ' '.join([t for t in text_parts if t])
        low = text.lower()
        match = any(kw in low for kw in keywords)
        candidates.append({'global_id': gid, 'name': name, 'description': desc, 'object_type': obtype, 'tag': tag, 'psets': psets, 'match_keywords': match, 'text': text})
    except Exception:
        continue

# Prefer candidates with keyword match
matched = [c for c in candidates if c['match_keywords']]
chosen = None
if matched:
    # pick the one with strongest keyword match (first occurrence)
    chosen = matched[0]['global_id']
else:
    # fallback: look for Pset_DoorCommon IsExternal = TRUE or property indicating exterior
    for c in candidates:
        psets = c.get('psets', {})
        pset = psets.get('Pset_DoorCommon') or psets.get('Pset_DoorCommon.V1') or psets.get('Pset_DoorCommon:Common')
        if pset:
